insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 1, $study_guide${"guide":"study_guide_acc_cm201","code":"ACC-CM201","courseId":"40000000-0000-4000-8000-000000000007","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"fc9a0adc-5f6f-5c98-a35f-7473c94a400a","before":{"title":"Financial Accounting I","body":"Fundamentals of financial accounting under IFRS: the IASB conceptual framework and the key standards governing revenue, financial-statement presentation, inventories, accounting policies, property, plant and equipment, government grants, and borrowing costs.","topics":[{"chapter":"1","description":"IASB Framework for the Preparation and Presentation of Financial Statements"},{"chapter":"2","description":"IFRS 15 - Revenue from Contracts with Customers"},{"chapter":"3","description":"IAS 1 - Presentation of Financial Statements"},{"chapter":"4","description":"IAS 2 - Accounting for Inventory"},{"chapter":"5","description":"IAS 8 - Accounting Policies, Changes in Estimates and Errors"},{"chapter":"6","description":"IAS 16 - Property, Plant, and Equipment (PPE)"},{"chapter":"7","description":"IAS 20 - Government Grants"},{"chapter":"8","description":"IAS 23 - Borrowing Costs"}],"examFocus":["IASB Framework qualitative characteristics","IFRS 15 five-step revenue recognition model","IAS 1 complete set of financial statements","IAS 2 inventory valuation (lower of cost and NRV)","IAS 8 retrospective vs prospective application","IAS 16 depreciation calculations (straight-line & reducing balance)","IAS 20 government grants recognition rules","IAS 23 borrowing costs capitalization"]},"after":{"title":"Financial Accounting I","body":"Fundamentals of financial accounting under IFRS: the IASB conceptual framework and the key standards governing revenue, financial-statement presentation, inventories, accounting policies, property, plant and equipment, government grants, and borrowing costs.","topics":[{"chapter":"1","description":"IASB Framework for the Preparation and Presentation of Financial Statements"},{"chapter":"2","description":"IFRS 15 - Revenue from Contracts with Customers"},{"chapter":"3","description":"IAS 1 - Presentation of Financial Statements"},{"chapter":"4","description":"IAS 2 - Accounting for Inventory"},{"chapter":"5","description":"IAS 8 - Accounting Policies, Changes in Estimates and Errors"},{"chapter":"6","description":"IAS 16 - Property, Plant, and Equipment (PPE)"},{"chapter":"7","description":"IAS 20 - Government Grants"},{"chapter":"8","description":"IAS 23 - Borrowing Costs"}],"examFocus":["IASB Framework qualitative characteristics","IFRS 15 five-step revenue recognition model","IAS 1 complete set of financial statements","IAS 2 inventory valuation (lower of cost and NRV)","IAS 8 retrospective vs prospective application","IAS 16 depreciation calculations (straight-line & reducing balance)","IAS 20 government grants recognition rules","IAS 23 borrowing costs capitalization"],"outcomes":["Explain the purpose of the Conceptual Framework, the qualitative characteristics, the elements, recognition and measurement.","Apply the five-step model of IFRS 15 to recognise revenue.","Prepare and present financial statements in line with IAS 1.","Measure inventories at the lower of cost and net realisable value under IAS 2.","Account for changes in accounting policies and estimates, and correct prior period errors, under IAS 8.","Recognise, measure, depreciate, revalue and derecognise property, plant and equipment under IAS 16.","Account for government grants under IAS 20.","Capitalise borrowing costs on qualifying assets under IAS 23."],"assessment":["Expect objective questions and calculations on each standard.","Calculations come up in every topic. Work through every worked example until you can do them quickly.","Every topic is examinable."]}},"retire":[{"itemId":"5eb40a2c-bcd4-5574-a16f-24e35c1b47d5","revision":1,"parentRevision":null},{"itemId":"30197d9b-d3db-5a45-b0b4-2a07215aade0","revision":1,"parentRevision":null},{"itemId":"bd294dd5-b14f-5b96-ac88-e0b616959c46","revision":1,"parentRevision":null},{"itemId":"4fac2aba-ca43-567a-b2a8-3585165894bd","revision":1,"parentRevision":null},{"itemId":"fbd5318d-3689-51c0-bcd9-e988ec5fd8d5","revision":1,"parentRevision":null},{"itemId":"7a831529-9b24-5e62-a49c-4239e9394c64","revision":1,"parentRevision":null},{"itemId":"506f7eb2-b2f8-5240-966c-cc555e9e962a","revision":1,"parentRevision":null},{"itemId":"46259144-f5d2-5bb3-9325-5c706cd0dc07","revision":1,"parentRevision":null},{"itemId":"7055f2ab-06ae-53de-9cdc-f1841358d1df","revision":1,"parentRevision":null},{"itemId":"06c82082-6f32-58ed-8584-985f733f7871","revision":1,"parentRevision":null},{"itemId":"77fd5219-370d-5f83-bad9-d039b15eb2f3","revision":1,"parentRevision":null},{"itemId":"dc5f215f-7522-579d-9908-cacfb2540f2f","revision":1,"parentRevision":null},{"itemId":"e425d10e-a58e-57a8-9863-1242807c85c1","revision":1,"parentRevision":null},{"itemId":"be235e41-144e-5be6-83c2-fa0e9a378eb3","revision":1,"parentRevision":null},{"itemId":"d0c2497d-21bd-57c3-82ae-9f899f677b2f","revision":1,"parentRevision":null},{"itemId":"7950ed60-9916-5392-98d9-4172fe590c7e","revision":1,"parentRevision":null},{"itemId":"53f5f0b3-10e3-50e1-9817-eae79a21f18e","revision":1,"parentRevision":null},{"itemId":"c00b960b-5f71-5609-b0cb-f12b64b56f8c","revision":1,"parentRevision":null},{"itemId":"25370e19-306d-5a4a-b772-fda88e6fd959","revision":1,"parentRevision":null},{"itemId":"3692d3ac-9ff7-5c9e-8b63-828c55dfa4cd","revision":1,"parentRevision":null}],"keep":[{"itemId":"c9a5d8d9-4efe-54b9-a5fb-b8fb88a7579e","revision":1},{"itemId":"965ec205-bbb3-53c8-bb5a-593ab0b3d5b5","revision":1},{"itemId":"5f90392c-a10a-569a-8ebb-1241e9e8981c","revision":1},{"itemId":"2c3c9eb0-3322-5391-977c-6af53e68257c","revision":1},{"itemId":"d4c93605-c101-542c-835e-b9fe4f271618","revision":1},{"itemId":"d82404d7-d3df-5e0b-86d6-61bd2e860726","revision":1},{"itemId":"2f66b8e5-b7ed-5154-92f7-7be966f5e136","revision":1},{"itemId":"38e3aaa1-9ecb-5902-8d77-1dc61d2992e0","revision":1},{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 2, $study_guide$"itemId":"f82b4aa1-8e36-571b-8786-641a2c249084","revision":1},{"itemId":"be5ae6f3-379e-52e3-8bab-3778e9480990","revision":1},{"itemId":"bd6ccb8d-25ff-5287-8ceb-6e77a5f23f38","revision":1},{"itemId":"a6bb985c-079e-5850-89cf-b80fb10d8a14","revision":1},{"itemId":"eb4a5644-323e-573a-ba24-7cfa4145e3a0","revision":1},{"itemId":"579fbccf-8a22-5ec0-a797-e058a5015869","revision":1},{"itemId":"46dcfac3-d27e-55db-be01-c1a29c8d519f","revision":1},{"itemId":"c89a446d-d7c4-5f6e-a32a-74ce1739a3c8","revision":1},{"itemId":"4104a77c-9ab1-5705-8fac-c11370a3fc0d","revision":1},{"itemId":"13ba1de3-c0e6-52f9-9909-0744346ade31","revision":1},{"itemId":"1c7a210d-3b08-523c-bcfe-a02ccaf34e4a","revision":1},{"itemId":"e552f3e4-f695-5574-a9d0-3d8cf60e823f","revision":1},{"itemId":"7b757965-e0e0-5855-8986-6e38d676cf94","revision":1},{"itemId":"6a9ca9d1-99bb-502c-b414-2de980d59933","revision":1},{"itemId":"9ed907ae-5696-5b5d-876b-91d737bc1789","revision":1},{"itemId":"e2386253-9107-58a7-9929-1b99d52e3272","revision":1},{"itemId":"eeffeb74-741b-5268-9148-1976e9af0363","revision":1},{"itemId":"b3a2a49d-0141-5b0c-bb59-7c4b4b787a7f","revision":1},{"itemId":"d45c3176-95f4-5168-97c1-d8e77c87d12c","revision":1},{"itemId":"922e039a-dd20-563d-83b8-b3afb9f27a4a","revision":1},{"itemId":"56f5b8ae-6ebf-5d25-8e34-0f53a68eb0e5","revision":1},{"itemId":"14f56b1c-ca11-59a9-9884-ce37d77629ff","revision":1},{"itemId":"41b225cc-5946-5b6b-995f-1df7c419318b","revision":1},{"itemId":"4a0bab6b-867d-5983-8414-ac22bd9c6b40","revision":1},{"itemId":"0c831812-5f88-513b-9dfc-973139c4f38e","revision":1},{"itemId":"3bba1d5a-1327-5855-8e69-95fb33e7136e","revision":1},{"itemId":"e9b16dc5-3d12-50a6-b6cd-4320b2c1a1be","revision":1},{"itemId":"d50fdef2-be88-5b64-bd9a-117150e58d9f","revision":1},{"itemId":"7f65e7aa-2de6-5b1d-a081-5fb345fc1f2b","revision":1},{"itemId":"4bce501d-934f-59cd-a628-41084f6514e7","revision":1},{"itemId":"e636e048-ae9e-5fda-b8c0-173bb1432dc2","revision":1},{"itemId":"7c7eea1c-43c8-5091-86fd-f4b7ad9df64c","revision":1}],"notes":[{"kind":"note","itemId":"6ca675c9-b94c-587f-9342-f0e868e3fe95","sourceKey":"guide-topic:1","position":1,"payload":{"title":"The IASB Conceptual Framework","body":"Standards and the IASB; the Framework's purpose, status, scope and benefits; the objective of financial reporting and its users; qualitative characteristics, cost constraint and going concern; the five elements, recognition and derecognition; measurement bases; capital maintenance.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"Standards and the IASB; the Framework's purpose, status, scope and benefits; the objective of financial reporting and its users; qualitative characteristics, cost constraint and going concern; the five elements, recognition and derecognition; measurement bases; capital maintenance."}],"lessons":[{"number":"1.1","title":"Accounting standards, the IASB and the IFRS Foundation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"GAAP (generally accepted accounting principles):","bold":true},{"text":" the concepts and rules behind financial statements, found partly in law and partly in standards. GAAP "},{"text":"vary from country to country","bold":true},{"text":" because "},{"text":"legal and regulatory systems are not the same","bold":true},{"text":". Many countries now use one uniform set: "},{"text":"IFRS","bold":true},{"text":" and the older "},{"text":"IAS","bold":true},{"text":"."}]},{"text":[{"text":"Accounting standards:","bold":true},{"text":" common sets of principles and procedures that define the basis of financial accounting policies and practices. They apply to the "},{"text":"whole spectrum","bold":true},{"text":" of an entity's transactions and other events: assets, liabilities, revenue, expenses and equity."}]},{"text":[{"text":"Legal status:","bold":true},{"text":" accounting standards "},{"text":"do not have the force of law","bold":true},{"text":", but they become effective when a "},{"text":"country adopts","bold":true},{"text":" them. Nigeria began adopting IFRS in "},{"text":"2012","bold":true},{"text":", starting with companies listed on what is now the "},{"text":"Nigerian Exchange Group","bold":true},{"text":". The "},{"text":"Financial Reporting Council of Nigeria (FRC of Nigeria)","bold":true},{"text":" is the national body that oversees and enforces compliance with IFRS in Nigeria."}]},{"text":[{"text":"IASB (International Accounting Standards Board, \"the Board\"):","bold":true},{"text":" the independent body of highly skilled accounting experts responsible for "},{"text":"issuing new IFRSs","bold":true},{"text":". It has full responsibility for all technical matters."}]}]},{"type":"paragraph","text":[{"text":"Outputs of the IASB (3):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Exposure drafts","bold":true},{"text":" of standards (proposals published for public comment)."}]},{"text":[{"text":"Revised IASs and new IFRSs.","bold":true}]},{"text":[{"text":"Final interpretations","bold":true},{"text":" of the "},{"text":"IFRS Interpretations Committee","bold":true},{"text":" (IFRICs)."}]}]},{"type":"paragraph","text":[{"text":"Responsibilities of the IASB:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Issues the "},{"text":"Conceptual Framework","bold":true},{"text":", which sets out the concepts underlying the preparation and presentation of financial statements."}]},{"text":[{"text":"Issues "},{"text":"accounting standards","bold":true},{"text":" (IFRSs) and Interpretations (IFRICs), used worldwide for consistency and transparency."}]},{"text":[{"text":"Works with "},{"text":"national standard setters","bold":true},{"text":" such as the FRC of Nigeria, through which "},{"text":"compliance","bold":true},{"text":" with IFRS is promoted."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Structure:","bold":true},{"text":" the not-for-profit "},{"text":"IFRS Foundat$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 3, $study_guide$ion","bold":true},{"text":" sits at the top. Its "},{"text":"Trustees","bold":true},{"text":" appoint, fund and oversee the boards and answer to a "},{"text":"Monitoring Board","bold":true},{"text":" of public capital-market authorities. Under it sit the "},{"text":"IASB","bold":true},{"text":" (IFRS Accounting Standards), the "},{"text":"ISSB","bold":true},{"text":" (International Sustainability Standards Board, sustainability disclosure standards), the "},{"text":"IFRS Interpretations Committee","bold":true},{"text":" (IFRICs) and the "},{"text":"IFRS Advisory Council","bold":true},{"text":" (advice)."}]},{"text":[{"text":"IAS vs IFRS:","bold":true},{"text":" the IASB replaced the "},{"text":"International Accounting Standards Committee (IASC)","bold":true},{"text":" in "},{"text":"2001","bold":true},{"text":". IASC standards are called "},{"text":"IAS","bold":true},{"text":" (e.g. IAS 16); IASB standards are "},{"text":"IFRS","bold":true},{"text":" (e.g. IFRS 15). Both remain in force unless withdrawn."}]},{"text":[{"text":"Trap:","bold":true},{"text":" audited financial statements, tax rates and audits are "},{"text":"not","bold":true},{"text":" IASB outputs or duties. Companies prepare accounts, government sets tax, auditors audit."}]}]}]},{"number":"1.2","title":"What the Conceptual Framework is, its purpose, status and scope","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Conceptual Framework:","bold":true},{"text":" a "},{"text":"coherent system of interrelated objectives and fundamental concepts","bold":true},{"text":" that prescribes the nature, function and limits of financial accounting and reporting, and is expected to lead to consistent guidance. The current version is the "},{"text":"Conceptual Framework for Financial Reporting 2018","bold":true},{"text":" (published March 2018)."}]}]},{"type":"paragraph","text":[{"text":"Purpose (3):","bold":true},{"text":" the Framework exists to"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"assist the IASB","bold":true},{"text":" in developing and revising IFRS Accounting Standards (its "},{"text":"primary","bold":true},{"text":" purpose: guidance for developing standards);"}]},{"text":[{"text":"assist entities (preparers)","bold":true},{"text":" in developing consistent accounting policies "},{"text":"when no Standard applies","bold":true},{"text":" to a transaction or other event, "},{"text":"or when a Standard allows a choice","bold":true},{"text":" of accounting policy;"}]},{"text":[{"text":"assist all stakeholders","bold":true},{"text":" to understand and interpret the Standards."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Status:","bold":true},{"text":" the Framework is "},{"text":"not an IFRS Standard","bold":true},{"text":". Nothing in it "},{"text":"overrides","bold":true},{"text":" any Standard or requirement in a Standard. Where a Standard conflicts with the Framework, the Standard wins."}]}]},{"type":"paragraph","text":[{"text":"Scope of the 2018 Framework (8 chapters):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"objective","bold":true},{"text":" of general purpose financial reporting."}]},{"text":[{"text":"The "},{"text":"qualitative characteristics","bold":true},{"text":" of useful financial information."}]},{"text":[{"text":"A description of the "},{"text":"reporting entity","bold":true},{"text":" and its "},{"text":"boundary","bold":true},{"text":"."}]},{"text":[{"text":"Definitions of the "},{"text":"elements","bold":true},{"text":" (asset, liability, equity, income, expenses)."}]},{"text":[{"text":"Recognition","bold":true},{"text":" (criteria for including assets and liabilities) and "},{"text":"derecognition","bold":true},{"text":" (when to remove them)."}]},{"text":[{"text":"Measurement","bold":true},{"text":" bases and when to use them."}]},{"text":[{"text":"Presentation and disclosure","bold":true},{"text":"."}]},{"text":[{"text":"Capital and capital maintenance","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Benefits (4):","bold":true}]},{"type":"table","header":[[{"text":"Benefit"}],[{"text":"What it gives"}]],"rows":[[[{"text":"Consistency and comparability"}],[{"text":"A common set of principles, so statements are easier to compare across companies and periods"}]],[[{"text":"Guidance for standard setters"}],[{"text":"Helps the IASB and others develop consistent, conceptually sound standards"}]],[[{"text":"Assistance to preparers"}],[{"text":"Helps companies develop accounting policies where no standard exists or a choice is allowed"}]],[[{"text":"Enhanced understanding"}],[{"text":"Helps investors, lenders and analysts understand and interpret financial statements"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"History:","bold":true},{"text":" April 1989 IASC Board approves the "},{"text":"Framework for the Preparation and Presentation of Financial Statements","italic":true},{"text":" (published July 1989); April 2001 adopted by the IASB; September 2010 "},{"text":"Conceptual Framework for Financial Reporting 2010","italic":true},{"text":" approved; March 2018 revised "},{"text":"Conceptual Framework","italic":true},{"text":" published."}]},{"text":[{"text":"Applying it:","bold":true},{"text":" Ikeja Agro Ltd meets a new type of transaction that no IFRS covers. It should develop its policy by looking to the "},{"text":"Conceptual Framework","bold":true},{"text":" (through the IAS 8 hierarchy you meet in Topic 5), not to whatever gives the highest profit, stock exchange rules or its tax computation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" assessing how efficiently management has used resources (stewardship) is what "},{"text":"users","bold":true},{"text":" do; it is "},{"text":"not","bold":true},{"text":" a purpose of the Framework. The Framework does "},{"text":"not","bold":true},{"text":" set tax rates, listing rules, audit p$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 4, $study_guide$rocedures or directors' pay."}]},{"text":[{"text":"Reporting entity:","bold":true},{"text":" an entity that is "},{"text":"required, or chooses,","bold":true},{"text":" to prepare financial statements. It can be a "},{"text":"single entity","bold":true},{"text":", a "},{"text":"portion","bold":true},{"text":" of an entity, or "},{"text":"more than one entity","bold":true},{"text":", and it is "},{"text":"not necessarily a legal entity","bold":true},{"text":". When Delta Holdings Plc and its three subsidiaries prepare one set of consolidated statements, that group of four companies is one reporting entity."}]}]}]},{"number":"1.3","title":"Objective of general purpose financial reporting and its users","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Objective:","bold":true},{"text":" to provide financial information about the reporting entity that is "},{"text":"useful to existing and potential investors, lenders and other creditors","bold":true},{"text":" in making decisions about providing resources to the entity."}]},{"text":[{"text":"General purpose financial reports (GPFR):","bold":true},{"text":" financial statements meant to meet the information needs "},{"text":"common","bold":true},{"text":" to users who "},{"text":"cannot command","bold":true},{"text":" reports tailored to their own needs. They comply with accounting standards and GAAP."}]},{"text":[{"text":"Special-purpose financial statements:","bold":true},{"text":" prepared to meet the demands of "},{"text":"a particular user","bold":true},{"text":" or group (e.g. a report in a format a bank designs only for its loan assessment)."}]},{"text":[{"text":"GPFR "},{"text":"cannot provide all","bold":true},{"text":" the information users need; users must also consider information from "},{"text":"other sources","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Primary users (3):","bold":true},{"text":" "},{"text":"present and potential investors","bold":true},{"text":", "},{"text":"lenders","bold":true},{"text":", and "},{"text":"other creditors","bold":true},{"text":". They decide about:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"buying, selling or holding","bold":true},{"text":" equity or debt instruments;"}]},{"text":[{"text":"providing or settling loans","bold":true},{"text":" and other forms of credit;"}]},{"text":[{"text":"exercising rights to vote","bold":true},{"text":" on, or otherwise influence, management's actions that affect the use of the entity's resources."}]}]},{"type":"paragraph","text":[{"text":"To decide, they need information to assess:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the entity's "},{"text":"prospects for future net cash inflows","bold":true},{"text":"; and"}]},{"text":[{"text":"how efficiently and effectively management has discharged its responsibility to use the entity's resources: "},{"text":"stewardship","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Other users","bold":true},{"text":" (may find GPFR useful but are "},{"text":"not","bold":true},{"text":" primary users; GPFR are not mainly directed at them): "},{"text":"prudential and market regulators","bold":true},{"text":" (e.g. the Central Bank of Nigeria), "},{"text":"management","bold":true},{"text":", "},{"text":"analysts and brokerage firms","bold":true},{"text":", and the "},{"text":"government","bold":true},{"text":" (deciding how much tax to collect)."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Users and their information needs","bold":true},{"text":" (learn the table: exams swap the rows):"}]},{"type":"table","header":[[{"text":"User"}],[{"text":"Interested in"}]],"rows":[[[{"text":"Owners / investors"}],[{"text":"Appraisal of the "},{"text":"efficiency of management performance","bold":true}]],[[{"text":"Management"}],[{"text":"Overall performance, growth and survival","bold":true}]],[[{"text":"Trade creditors (payables)"}],[{"text":"Liquidity","bold":true}]],[[{"text":"Employees"}],[{"text":"Liquidity, profitability and survival","bold":true},{"text":" (job and wage security)"}]],[[{"text":"Customers"}],[{"text":"Quality","bold":true},{"text":" of products or services"}]],[[{"text":"Government"}],[{"text":"Profitability for tax purposes","bold":true},{"text":" and policy formulation"}]],[[{"text":"Financial analysts"}],[{"text":"Appraisal of the "},{"text":"entire business activities","bold":true}]],[[{"text":"Lenders"}],[{"text":"Liquidity, profitability and reliability of the business assets","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A workers' union in a Lagos factory checking whether jobs and wages are safe is an employee group: liquidity, profitability and survival."}]},{"text":[{"text":"Trap:","bold":true},{"text":" judging product quality before buying is a "},{"text":"customer's","bold":true},{"text":" decision, not one of the three primary-user decisions. The government is "},{"text":"not","bold":true},{"text":" a primary user, even though it reads the accounts for tax."}]}]}]},{"number":"1.4","title":"Qualitative characteristics, the cost constraint and going concern","mustKnow":[{"type":"paragraph","text":[{"text":"Information is "},{"text":"useful","bold":true},{"text":" if it is "},{"text":"relevant","bold":true},{"text":" and "},{"text":"faithfully represents","bold":true},{"text":" what it purports to represent. Usefulness is "},{"text":"enhanced","bold":true},{"text":" if it is comparable, verifiable, timely and understandable."}]},{"type":"table","header":[[{"text":"Fundamental (2)"}],[{"text":"Enhancing (4)"}]],"rows":[[[{"text":"Relevance (includes "},{"text":"materiality","bold":true},{"text":")"}],[{"text":"Comparability"}]],[[{"text":"Faithful representation"}],[{"text":"Verifiability"}]],[[],[{"text":"Timeliness"}]],[[],[{"text":"Understandability"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Relevance:","bold":true},{"text":" inform$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 5, $study_guide$ation is relevant if it can "},{"text":"make a difference to users' decisions","bold":true},{"text":": it has "},{"text":"predictive value","bold":true},{"text":", "},{"text":"confirmatory value","bold":true},{"text":", or both."}]},{"text":[{"text":"Materiality:","bold":true},{"text":" an "},{"text":"entity-specific aspect of relevance","bold":true},{"text":": information is material if omitting, misstating or obscuring it could reasonably be expected to influence users' decisions. Judged on "},{"text":"nature or magnitude (or both)","bold":true},{"text":" in the context of the "},{"text":"individual entity","bold":true},{"text":"; there is "},{"text":"no uniform amount","bold":true},{"text":" for all entities."}]},{"text":[{"text":"Faithful representation:","bold":true},{"text":" representing the "},{"text":"substance","bold":true},{"text":" of an economic phenomenon instead of its "},{"text":"legal form only","bold":true},{"text":" (substance over form). A perfectly faithful depiction is:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Complete:","bold":true},{"text":" all information needed for understanding is included."}]},{"text":[{"text":"Neutral:","bold":true},{"text":" without bias or slanting, supported by "},{"text":"prudence","bold":true},{"text":" (caution when judging under uncertainty)."}]},{"text":[{"text":"Free from error:","bold":true},{"text":" no errors or omissions in the description or in the process used."}]}]}]},{"text":[{"text":"Comparability:","bold":true},{"text":" lets users identify "},{"text":"similarities and differences","bold":true},{"text":", e.g. trends over time and comparison with similar businesses. "},{"text":"Consistency","bold":true},{"text":" (using the "},{"text":"same methods","bold":true},{"text":" for the same items "},{"text":"from period to period","bold":true},{"text":", and across entities) helps achieve comparability. Consistency is the means; comparability is the goal."}]},{"text":[{"text":"Verifiability:","bold":true},{"text":" different "},{"text":"knowledgeable and independent observers","bold":true},{"text":" could reach "},{"text":"consensus, although not necessarily complete agreement","bold":true},{"text":", that a depiction is a faithful representation."}]},{"text":[{"text":"Timeliness:","bold":true},{"text":" available "},{"text":"early enough","bold":true},{"text":" to be capable of influencing decisions."}]},{"text":[{"text":"Understandability:","bold":true},{"text":" classified, characterised and presented clearly and concisely. It assumes users "},{"text":"have a reasonable knowledge of business and economic activities","bold":true},{"text":" and "},{"text":"review and analyse the information diligently","bold":true},{"text":"."}]},{"text":[{"text":"Cost constraint:","bold":true},{"text":" reporting has a cost, so the "},{"text":"benefits","bold":true},{"text":" of information must "},{"text":"justify the costs","bold":true},{"text":" of providing and using it. Cost is a pervasive constraint, not a qualitative characteristic."}]},{"text":[{"text":"Going concern:","bold":true},{"text":" the "},{"text":"underlying assumption","bold":true},{"text":" that the entity will "},{"text":"continue operating for the foreseeable future","bold":true},{"text":", with no intention or need to "},{"text":"liquidate or curtail","bold":true},{"text":" its operations materially. If that is not true, statements are prepared on a different basis."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Going concern and relevance (classic question):","bold":true},{"text":" Eko Foods Plc is a going concern with no plan to curtail operations. Is "},{"text":"depreciated cost","bold":true},{"text":" or "},{"text":"net realisable value (NRV)","bold":true},{"text":" more relevant for its machinery? "},{"text":"Depreciated cost","bold":true},{"text":", because the business will keep using the machine, not sell it. If Eko Foods were "},{"text":"not","bold":true},{"text":" a going concern, "},{"text":"NRV","bold":true},{"text":" (what the machine would fetch on sale) would be more relevant. Scrap value and undepreciated cost are wrong answers."}]},{"text":[{"text":"Materiality is entity-specific:","bold":true},{"text":" a ₦2 million omission could seriously mislead users of a small Yaba printing business yet be trivial in the accounts of a large commercial bank."}]},{"text":[{"text":"Spot the missing characteristic:","bold":true},{"text":" Oshodi Foods Ltd's MD deliberately slants estimates to look good: "},{"text":"neutrality","bold":true},{"text":" is missing. Aba Plastics Ltd leaves out a large bank loan: "},{"text":"completeness","bold":true},{"text":" is missing. An investor comparing Ogun Cement Plc's five-year sales trend with two rival cement firms relies on "},{"text":"comparability","bold":true},{"text":"."}]},{"text":[{"text":"Traps:","bold":true},{"text":" materiality and relevance are "},{"text":"not","bold":true},{"text":" enhancing characteristics; timeliness is "},{"text":"not","bold":true},{"text":" part of faithful representation; \"neutrality and prudence\" is "},{"text":"not","bold":true},{"text":" the fundamental pair. If asked which characteristic means \"no change in the basis of preparation from period to period\", answer "},{"text":"consistency","bold":true},{"text":"."}]},{"text":[{"text":"Enhancing characteristics improve useful information but "},{"text":"cannot make irrelevant or unfaithful information useful","bold":true},{"text":"."}]},{"text":[{"text":"Faithful representation replaced the older term \"reliability\" in 2010; the 2018 version brought back "},{"text":"prudence","bold":true},{"text":" and made "},{"text":"stewardship","bold":true},{"text":" explicit."}]}]}]},{"number":"1.5","title":"The elements, recognition and derecognition","mustKnow":[{"type":"paragraph","text":[{"text":"Elements of financial statements:","bold":true},{"text":" the broad classes into $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 6, $study_guide$which the financial effects of transactions and other events are grouped according to their economic characteristics."}]},{"type":"table","header":[[{"text":"Financial position (statement of financial position)"}],[{"text":"Performance (statement of profit or loss)"}]],"rows":[[[{"text":"Assets, Liabilities, Equity"}],[{"text":"Income, Expenses"}]]]},{"type":"paragraph","text":[{"text":"The "},{"text":"statement of cash flows","bold":true},{"text":" reflects "},{"text":"both","bold":true},{"text":" income-statement elements and "},{"text":"some changes","bold":true},{"text":" in statement-of-financial-position elements."}]},{"type":"paragraph","text":[{"text":"Definitions","bold":true},{"text":" (the wording most exam options use; the 2018 wording follows in brackets):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Asset:","bold":true},{"text":" a "},{"text":"resource controlled by the entity as a result of past events","bold":true},{"text":" and from which "},{"text":"future economic benefits are expected","bold":true},{"text":" to flow to the entity. (2018: a "},{"text":"present economic resource","bold":true},{"text":" controlled by the entity as a result of past events; an economic resource is a "},{"text":"right that has the potential to produce economic benefits","bold":true},{"text":".)"}]},{"text":[{"text":"Liability:","bold":true},{"text":" a "},{"text":"present obligation","bold":true},{"text":" of the entity "},{"text":"arising from past events","bold":true},{"text":", the settlement of which is expected to result in an "},{"text":"outflow","bold":true},{"text":" of resources embodying economic benefits. (2018: a present obligation of the entity to "},{"text":"transfer an economic resource","bold":true},{"text":" as a result of past events.)"}]},{"text":[{"text":"Equity:","bold":true},{"text":" the "},{"text":"residual interest in the assets","bold":true},{"text":" of the entity "},{"text":"after deducting all its liabilities","bold":true},{"text":"."}]},{"text":[{"text":"Income:","bold":true},{"text":" "},{"text":"increases in economic benefits","bold":true},{"text":" during the period, as "},{"text":"inflows or enhancements of assets or decreases of liabilities","bold":true},{"text":", that "},{"text":"increase equity","bold":true},{"text":", "},{"text":"other than contributions from equity participants","bold":true},{"text":". (2018 says \"holders of equity claims\"; the idea is the same.)"}]},{"text":[{"text":"Expenses:","bold":true},{"text":" "},{"text":"decreases in economic benefits","bold":true},{"text":" during the period, as "},{"text":"outflows or depletions of assets or incurrences of liabilities","bold":true},{"text":", that "},{"text":"decrease equity","bold":true},{"text":", "},{"text":"other than distributions to equity participants","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Formulas (the accounting equation):","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Assets = Equity + Liabilities"}]},{"text":[{"text":"Equity = Assets − Liabilities"}]},{"text":[{"text":"Liabilities = Assets − Equity"}]},{"text":[{"text":"Closing equity = Opening equity + Profit + New capital contributed − Dividends (distributions)"}]},{"text":[{"text":"Profit = Income − Expenses = Closing equity − Opening equity − New capital + Dividends"}]}]},{"type":"paragraph","text":[{"text":"Recognition:","bold":true},{"text":" capturing an item that meets the definition of an element for inclusion in the statement of financial position or performance. Under the 2018 Framework an asset or liability is recognised "},{"text":"only if","bold":true},{"text":" it meets the definition "},{"text":"and","bold":true},{"text":" recognition gives users "},{"text":"relevant","bold":true},{"text":" information and a "},{"text":"faithful representation","bold":true},{"text":", with benefits justifying costs. (The older Framework used two tests: it is "},{"text":"probable","bold":true},{"text":" that future economic benefits will flow, and the item has a cost or value that can be "},{"text":"measured reliably","bold":true},{"text":".)"}]},{"type":"paragraph","text":[{"text":"Derecognition:","bold":true},{"text":" removing all or part of a recognised asset or liability. An asset is derecognised when the entity "},{"text":"loses control","bold":true},{"text":" of it; a liability when the entity "},{"text":"no longer has a present obligation","bold":true},{"text":"."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Control:","bold":true},{"text":" the "},{"text":"ability to obtain the economic benefits and to restrict the access of others","bold":true},{"text":" (e.g. being the sole user of a plant, or selling surplus plant). It is "},{"text":"not","bold":true},{"text":" physical possession or legal title."}]},{"text":[{"text":"Past event:","bold":true},{"text":" Lekki Logistics Ltd has only "},{"text":"discussed","bold":true},{"text":" a lease it will sign next March, so at 31 December there is "},{"text":"no liability","bold":true},{"text":": the past event has not happened."}]},{"text":[{"text":"Constructive obligation:","bold":true},{"text":" arises from "},{"text":"expected practice or published policy","bold":true},{"text":", not law or contract. Niger Delta Oil Ltd publishes a policy of cleaning up damage it causes, though no law requires it; its duty to clean up damage already caused is constructive."}]},{"text":[{"text":"Income = revenue + gains.","bold":true},{"text":" "},{"text":"Revenue","bold":true},{"text":" arises from ordinary activities: "},{"text":"sales, fees, interest, dividends, royalties, rent","bold":true},{"text":" (capital contributed is "},{"text":"not","bold":true},{"text":" revenue). "},{"text":"Gains","bold":true},{"text":" are "},{"text":"no different in nature from revenue","bold":true},{"text":", so they are "},{"text":"not a separate element","bold":true},{"text":"."}]},{"text":[{"text":"Expen$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 7, $study_guide$ses include losses","bold":true},{"text":" and ordinary costs such as "},{"text":"cost of sales, wages, depreciation","bold":true},{"text":". "},{"text":"Losses","bold":true},{"text":" are "},{"text":"no different in nature from other expenses","bold":true},{"text":", so they are "},{"text":"not a separate element","bold":true},{"text":"."}]},{"text":[{"text":"Owner transactions:","bold":true},{"text":" Ibadan Bakeries Ltd's shareholders pay ₦5 million for new shares: equity rises but it is "},{"text":"not income","bold":true},{"text":" (contribution from equity participants). A ₦1.5 million dividend is "},{"text":"not an expense","bold":true},{"text":" (distribution to equity participants). Buying a van or repaying loan principal is not an expense either."}]}]},{"type":"paragraph","text":[{"text":"Worked examples (₦):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Equity.","italic":true},{"text":" Assets ₦250m, liabilities ₦90m: equity = 250 − 90 = "},{"text":"₦160m","bold":true},{"text":". Buying equipment for ₦30m on credit gives 280 − 120 = "},{"text":"₦160m","bold":true},{"text":": unchanged."}]},{"text":[{"text":"Assets.","italic":true},{"text":" Equity ₦40m, liabilities ₦25m: assets = 40 + 25 = "},{"text":"₦65m","bold":true},{"text":". "},{"text":"Liabilities.","italic":true},{"text":" Assets ₦120m, equity ₦70m: liabilities = 120 − 70 = "},{"text":"₦50m","bold":true},{"text":"."}]},{"text":[{"text":"Loan repayment.","italic":true},{"text":" Assets ₦60m, liabilities ₦25m; ₦4m of loan repaid in cash. Liabilities = 25 − 4 = "},{"text":"₦21m","bold":true},{"text":"; assets 56m; equity 56 − 21 = "},{"text":"₦35m","bold":true},{"text":" (unchanged)."}]},{"text":[{"text":"Profit from equity.","italic":true},{"text":" Opening equity ₦60m, closing ₦84m, new shares ₦15m, dividends ₦6m. Profit = 84 − 60 − 15 + 6 = "},{"text":"₦15m","bold":true},{"text":". Check: 60 + 15 + 15 − 6 = 84."}]},{"text":[{"text":"Classifying.","italic":true},{"text":" Enugu Prints Ltd's first month: capital received ₦8m, cash revenue ₦3m, wages ₦1.2m, dividend ₦0.5m. Income = "},{"text":"₦3m","bold":true},{"text":"; expenses = "},{"text":"₦1.2m","bold":true},{"text":"; profit = ₦1.8m. Closing equity (from zero) = 8 + 1.8 − 0.5 = "},{"text":"₦9.3m","bold":true},{"text":"."}]}]}]},{"number":"1.6","title":"Measurement bases, capital and capital maintenance","mustKnow":[{"type":"paragraph","text":[{"text":"Measurement:","bold":true},{"text":" quantifying, in money, the elements recognised. The 2018 Framework has two groups of bases:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Historical cost:","bold":true},{"text":" based on the price of the transaction that created the item: for an asset, the consideration paid plus transaction costs, later reduced by depreciation and impairment."}]},{"text":[{"text":"Current value","bold":true},{"text":" (updated to conditions at the measurement date):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fair value:","bold":true},{"text":" the price that would be received to "},{"text":"sell an asset","bold":true},{"text":", or paid to "},{"text":"transfer a liability","bold":true},{"text":", in an orderly transaction between market participants at the measurement date."}]},{"text":[{"text":"Value in use","bold":true},{"text":" (assets) / "},{"text":"fulfilment value","bold":true},{"text":" (liabilities): the "},{"text":"present value of the cash flows","bold":true},{"text":" the entity expects from using and finally disposing of an asset, or expects to transfer to fulfil a liability. These are entity-specific."}]},{"text":[{"text":"Current cost:","bold":true},{"text":" the cost of an "},{"text":"equivalent asset","bold":true},{"text":" at the measurement date (consideration that would be paid plus transaction costs), or the consideration that would be received for an equivalent liability minus transaction costs."}]}]}]}]},{"type":"paragraph","text":[{"text":"Concepts of capital (2):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Financial capital:","bold":true},{"text":" capital is the "},{"text":"net assets or equity","bold":true},{"text":" of the entity, measured either in "},{"text":"nominal money","bold":true},{"text":" units or in units of "},{"text":"constant purchasing power","bold":true},{"text":". Most entities use this."}]},{"text":[{"text":"Physical capital:","bold":true},{"text":" capital is the entity's "},{"text":"productive capacity","bold":true},{"text":" or "},{"text":"operating capability","bold":true},{"text":" (e.g. units of output per day)."}]}]},{"type":"paragraph","text":[{"text":"Capital maintenance:","bold":true},{"text":" profit is earned only if capital at the end of the period exceeds capital at the start, "},{"text":"after excluding contributions from and distributions to owners","bold":true},{"text":". Anything more than what is needed to maintain opening capital is profit."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Profit (money financial capital) = Closing net assets − Opening net assets"}]},{"text":[{"text":"Profit (constant purchasing power) = Closing net assets − Opening net assets × (1 + general inflation rate)"}]},{"text":[{"text":"Profit (physical capital) = Closing net assets − Cost of the opening operating capability at closing prices"}]},{"text":[{"text":"(In each case first remove owner contributions and add back distributions.)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Measurement example.","bold":true},{"text":" Eko Foods Plc's machine cost ₦20m; accumulated depreciation is ₦8m. Historical cost carrying amount = 20 − 8 = "},{"text":"₦12m","bold":true},{"text":". It would sell today for ₦10m ("},{"text":"fair value","bold":true},{"text":"). The present value of cash from using and then disposing of it is ₦13m ("},{"text":"value in use","bold":true},{"text":"). A similar$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 8, $study_guide$ used machine would cost ₦14m today ("},{"text":"current cost","bold":true},{"text":"). One asset, four measures."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"market value only\", \"replacement cost only\" and \"tax value\" are "},{"text":"not","bold":true},{"text":" the Framework's list of bases; "},{"text":"historical cost","bold":true},{"text":" is."}]},{"text":[{"text":"Capital maintenance example (all figures ₦).","bold":true},{"text":" Adaeze starts a trading business with ₦10,000,000, buys 2,000 bags of rice at ₦5,000 each and sells them all by year end for ₦13,000,000 cash. General inflation is 10%. Replacing 2,000 bags at year end costs ₦6,000 each."}]}]},{"type":"table","header":[[{"text":"Concept"}],[{"text":"Capital to maintain"}],[{"text":"Profit"}]],"rows":[[[{"text":"Money financial capital"}],[{"text":"₦10,000,000"}],[{"text":"13,000,000 − 10,000,000 = "},{"text":"₦3,000,000","bold":true}]],[[{"text":"Constant purchasing power"}],[{"text":"10,000,000 × 1.10 = ₦11,000,000"}],[{"text":"13,000,000 − 11,000,000 = "},{"text":"₦2,000,000","bold":true}]],[[{"text":"Physical capital"}],[{"text":"2,000 × 6,000 = ₦12,000,000"}],[{"text":"13,000,000 − 12,000,000 = "},{"text":"₦1,000,000","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Under the last two concepts, the part of the ₦3,000,000 gain needed to maintain capital (₦1,000,000 or ₦2,000,000) is a "},{"text":"capital maintenance adjustment","bold":true},{"text":", taken to equity, not profit. Physical capital maintenance needs the "},{"text":"current cost","bold":true},{"text":" basis."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Standards bind only once a country adopts them (Nigeria: 2012). The IASB issues IFRSs, exposure drafts and IFRICs."}]},{"text":[{"text":"The Framework is not a Standard and never overrides one; it helps the IASB, preparers and all stakeholders."}]},{"text":[{"text":"Primary users: present and potential investors, lenders and other creditors (future net cash inflows, stewardship)."}]},{"text":[{"text":"Fundamental: relevance (incl. materiality) and faithful representation (complete, neutral, free from error). Enhancing: comparability, verifiability, timeliness, understandability."}]},{"text":[{"text":"Cost constraint; going concern is the underlying assumption."}]},{"text":[{"text":"Elements: asset, liability, equity; income, expenses. Owner contributions and dividends are neither income nor expenses."}]},{"text":[{"text":"Assets = Equity + Liabilities; Profit = Closing equity − Opening equity − New capital + Dividends."}]},{"text":[{"text":"Measurement: historical cost; current value (fair value, value in use / fulfilment value, current cost)."}]},{"text":[{"text":"Capital: financial (money or purchasing power) or physical; profit only after capital is maintained."}]}]}],"theory":{"itemId":"b202e757-7d10-53d4-bacc-0546607956a5","question":[{"type":"paragraph","text":[{"text":"Kano Textiles Ltd had net assets of ₦20,000,000 at the start of the year and ₦26,000,000 at the end. There were no capital contributions or dividends. General inflation was 12%, and restoring the company's opening operating capability at year-end prices would cost ₦25,000,000. Compute profit under (a) money financial capital, (b) constant purchasing power financial capital and (c) physical capital maintenance."}]}]},"practice":[{"topic":"IASB Conceptual Framework","named":false}]}},{"kind":"note","itemId":"41f736b6-b2ae-5907-b4ba-0a83ac114fa1","sourceKey":"guide-topic:2","position":2,"payload":{"title":"IFRS 15 Revenue from Contracts with Customers","body":"The objective, background, scope and key terms of IFRS 15; the five-step model (contract, performance obligations, transaction price, allocation, recognition); variable consideration, financing, non-cash consideration and consideration payable to a customer; over time vs point in time; contract costs, principal vs agent and warranties; every computation.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The objective, background, scope and key terms of IFRS 15; the five-step model (contract, performance obligations, transaction price, allocation, recognition); variable consideration, financing, non-cash consideration and consideration payable to a customer; over time vs point in time; contract costs, principal vs agent and warranties; every computation."}],"lessons":[{"number":"2.1","title":"Objective, background, scope and key terms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Objective:","bold":true},{"text":" to establish the principles an entity applies to report useful information to users of financial statements about the "},{"text":"nature, amount, timing and uncertainty","bold":true},{"text":" of revenue and cash flows arising from a contract with a customer (4 features; \"profitability\" is "},{"text":"not","bold":true},{"text":" one). It promotes "},{"text":"consistency and comparability across industries and capital markets","bold":true},{"text":"."}]},{"text":[{"text":"Issued:","bold":true},{"text":" 28 "},{"text":"May 2014","bold":true},{"text":". "},{"text":"Effective:","bold":true},{"text":" "},{"text":"1 January 2018","bold":true},{"text":" (annual periods beginning on or after that date)."}]},{"text":[{"text":"It replaced 6 pronouncements:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"IAS 18 Revenue"}]},{"text":[{"text":"IAS 11 Construction Contracts"}]},{"text":[{"text":"IFRIC 13 Customer Loyalty Programmes"}]},{"text":[{"text":"IFRIC 15 Agreements for the Construction of Real Estate"}]},{"text":[{"text":"IFRIC 18 Transfers of Assets from Customers"}]},{"text":[{"text":"SIC-31 Revenue: Barter Transactions Involving Advertising Services"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Core principle:","bold":true},{"text":" recognise revenue to depict the transfer of promised goods or services to customers at$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 9, $study_guide$ the amount of consideration the entity expects to be entitled to in exchange. Revenue is recognised "},{"text":"when (or as) control","bold":true},{"text":" of the goods or services passes to the customer (not risk only, legal title or physical possession only)."}]},{"text":[{"text":"Scope:","bold":true},{"text":" all contracts with customers "},{"text":"except","bold":true},{"text":" (1) leases (IFRS 16); (2) insurance contracts (IFRS 17); (3) financial instruments and other contractual rights or obligations within IFRS 9, IFRS 10, IFRS 11, IAS 27 and IAS 28; (4) non-monetary exchanges between entities in the same line of business to help sales to customers."}]}]},{"type":"paragraph","text":[{"text":"Key terms (IFRS 15 wording)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Contract:","bold":true},{"text":" an agreement between two or more parties that creates enforceable rights and obligations."}]},{"text":[{"text":"Customer:","bold":true},{"text":" a party that has contracted with an entity to obtain goods or services that are an "},{"text":"output of the entity's ordinary activities","bold":true},{"text":" in exchange for consideration."}]},{"text":[{"text":"Income:","bold":true},{"text":" increases in economic benefits during the accounting period in the form of inflows or enhancements of assets or decreases of liabilities that result in an increase in equity, "},{"text":"other than those relating to contributions from equity participants","bold":true},{"text":"."}]},{"text":[{"text":"Revenue:","bold":true},{"text":" income arising in the course of an entity's "},{"text":"ordinary activities","bold":true},{"text":"."}]},{"text":[{"text":"Performance obligation:","bold":true},{"text":" a promise in a contract with a customer to transfer to the customer either (a) a good or service (or a bundle of goods or services) that is "},{"text":"distinct","bold":true},{"text":"; or (b) a "},{"text":"series","bold":true},{"text":" of distinct goods or services that are substantially the same and that have the same pattern of transfer to the customer."}]}]},{"type":"paragraph","text":[{"text":"The five steps (in order)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the contract(s) with a customer."}]},{"text":[{"text":"Identify the performance obligations in the contract."}]},{"text":[{"text":"Determine the transaction price."}]},{"text":[{"text":"Allocate the transaction price to the performance obligations."}]},{"text":[{"text":"Recognise revenue when (or as) the entity satisfies a performance obligation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The income definition above is IFRS 15's own. The 2018 Conceptual Framework (Topic 1) words it as increases in assets, or decreases in liabilities, that increase equity, other than contributions from holders of equity claims. Either way, owners' contributions are never income."}]},{"text":[{"text":"Income vs revenue:","bold":true},{"text":" revenue is the part of income from ordinary activities. For Adaeze Foods Ltd, a Lagos supermarket chain, "},{"text":"sales of groceries","bold":true},{"text":" are revenue. Cash paid in by owners, new shares issued and a bank loan are "},{"text":"not","bold":true},{"text":" revenue (owners' contributions are excluded from income; a loan is a liability)."}]},{"text":[{"text":"Traps:","bold":true},{"text":" a customer buys the entity's "},{"text":"output","bold":true},{"text":"; the buyer of Eko Foods Plc's old delivery van is not a customer, and the gain is not revenue. May 2014 is the "},{"text":"issue","bold":true},{"text":" date, 1 January 2018 the "},{"text":"effective","bold":true},{"text":" date."}]}]}]},{"number":"2.2","title":"Steps 1 and 2: the contract and performance obligations","mustKnow":[{"type":"paragraph","text":[{"text":"Step 1: a contract is within IFRS 15 only when all 5 criteria are met:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The parties have "},{"text":"approved","bold":true},{"text":" the contract and are committed to perform their obligations."}]},{"text":[{"text":"Each party's "},{"text":"rights","bold":true},{"text":" regarding the goods or services can be identified."}]},{"text":[{"text":"The "},{"text":"payment terms","bold":true},{"text":" can be identified."}]},{"text":[{"text":"The contract has "},{"text":"commercial substance","bold":true},{"text":" (it is expected to change the entity's future cash flows)."}]},{"text":[{"text":"It is "},{"text":"probable","bold":true},{"text":" that the entity will "},{"text":"collect","bold":true},{"text":" the consideration to which it will be entitled."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Form:","bold":true},{"text":" a contract may be "},{"text":"written, oral (non-written) or implied","bold":true},{"text":" by the entity's customary business practices. It also covers goods or services the customer reasonably expects because of the entity's practices or statements, even if not written down."}]},{"text":[{"text":"If any criterion fails:","bold":true},{"text":" an "},{"text":"accounting contract does not exist","bold":true},{"text":", even though a legal contract may exist. The entity must "},{"text":"continue to assess","bold":true},{"text":" whether the criteria are subsequently met. Any consideration received is recognised as a "},{"text":"liability","bold":true},{"text":" (not revenue) until the criteria are met, or until the amount is non-refundable and either the entity has no remaining obligations and has received substantially all the consideration, or the contract has been terminated."}]}]},{"type":"paragraph","text":[{"text":"Step 2: performance obligations.","bold":true},{"text":" At contract inception, assess the promised goods or services and identify each distinct good or service (or bundle), or series, as a performance obligation."}]},{"type":"paragraph","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 10, $study_guide$text":[{"text":"A good or service is distinct if both conditions are met:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Capable of being distinct:","bold":true},{"text":" the customer can benefit from it "},{"text":"on its own or together with other readily available resources","bold":true},{"text":"."}]},{"text":[{"text":"Distinct within the context of the contract:","bold":true},{"text":" the promise is "},{"text":"separately identifiable","bold":true},{"text":" from other promises in the contract. It is not separately identifiable when it is "},{"text":"integrated with, highly dependent on or highly interrelated with","bold":true},{"text":" other goods or services in the contract, or significantly modifies them."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Series:","bold":true},{"text":" a promise of goods or services that are substantially the same with the same pattern of transfer (e.g. daily cleaning for a year) is "},{"text":"one","bold":true},{"text":" performance obligation made up of a series of distinct services."}]}]},{"type":"paragraph","text":[{"text":"Warranties","bold":true}]},{"type":"table","header":[[],[{"text":"Assurance-type warranty"}],[{"text":"Service-type warranty"}]],"rows":[[[{"text":"What it gives"}],[{"text":"Assurance the product works as agreed"}],[{"text":"An extra service beyond that assurance, or customer can buy it separately"}]],[[{"text":"Performance obligation?"}],[{"text":"No"}],[{"text":"Yes, a separate one"}]],[[{"text":"Accounting"}],[{"text":"Provision under IAS 37"}],[{"text":"Allocate part of the transaction price; recognise over the warranty period"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Collectability (criterion 5):","bold":true},{"text":" Okon Plastics Ltd has made goods worth ₦15,000,000 exclusively for a customer restructuring because of liquidity problems, which promises a bank letter of credit not yet finalised. Collection is not yet probable, so no accounting contract exists. Revenue is recognised "},{"text":"only when the letter of credit is finalised (payment becomes probable) and the goods are transferred","bold":true},{"text":": not when the goods are made, not on the customer's promise, and not \"never\"."}]},{"text":[{"text":"Payment terms (criterion 3):","bold":true},{"text":" On 1 April 2024, Ilupeju Medical Ltd agrees to sell 1,000 machines, but the price depends on a part from another vendor, not yet priced. It receives a non-refundable ₦4,500,000. Payment terms are not identified, so no accounting contract exists:"}],"blocks":[{"type":"paragraph","text":[{"text":"Dr Cash ₦4,500,000; Cr Liability (deposit received) ₦4,500,000"}]},{"type":"paragraph","text":[{"text":"A further ₦1,000,000 before terms are agreed makes the liability ₦5,500,000; revenue stays nil. Non-refundable does not make it revenue, and it never goes to equity."}]}]},{"text":[{"text":"Implied promise:","bold":true},{"text":" PhoneHub Ltd, an Ikeja retailer, always fits a free screen protector with every phone. Customers expect it from customary practice, so it is a promise in the contract though the receipt is silent."}]},{"text":[{"text":"Software illustration:","bold":true},{"text":" ABC Limited supplies a standard software licence, installs it, provides updates and technical support for five years. The licence works without the updates; installation is routine and is also done by several approved third-party installers. Each item benefits the customer and is separately identifiable: "},{"text":"four","bold":true},{"text":" performance obligations (licence, installation, updates, support). "},{"text":"Others can perform the installation","bold":true},{"text":", the best evidence it is distinct; one invoice or price does not merge items."}]},{"text":[{"text":"Service-type warranty example:","bold":true},{"text":" Eko Electronics Plc sells a television with a 2-year extended warranty for ₦330,000. Stand-alone selling prices (SSPs): television ₦300,000; extended warranty ₦60,000 (total ₦360,000). Television = 300,000/360,000 × 330,000 = ₦275,000 (at delivery). Warranty = 60,000/360,000 × 330,000 = ₦55,000, recognised over 2 years = ₦27,500 a year. The basic manufacturer's guarantee that the set works is assurance-type: provide under IAS 37."}]}]}]},{"number":"2.3","title":"Step 3: determining the transaction price","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Transaction price:","bold":true},{"text":" the amount of consideration to which an entity expects to be entitled in exchange for transferring promised goods or services to a customer, "},{"text":"excluding amounts collected on behalf of third parties","bold":true},{"text":" (e.g. VAT and some other sales taxes)."}]},{"text":[{"text":"Determinants:","bold":true},{"text":" the terms of the contract and the entity's "},{"text":"customary business practices","bold":true},{"text":", taking account of returns, bonuses, discounts, rebates and other variable consideration. The entity's "},{"text":"cost","bold":true},{"text":" of producing the goods is "},{"text":"not","bold":true},{"text":" a determinant."}]},{"text":[{"text":"The four things to consider:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Variable consideration:","bold":true},{"text":" consideration that depends on the occurrence or non-occurrence of a future event (volume discounts, rebates, refunds, bonuses, penalties, returns). Estimate it by the "},{"text":"expected value","bold":true},{"text":" (sum of probability-weighted amounts; best with many possible outcomes) or the "},{"text":"most likely amount","bold":true},{"text":" (best with two outcomes). "},{"text":"Constraint:","bold":true},{"text":" include it only to the extent it is "},{"text":"highly probable","bold":true},{"text":" that a significant reversal of revenue will not occur. Reassess at each reporting date."}]},{"text":[{"te$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 11, $study_guide$xt":"Significant financing component:","bold":true},{"text":" adjust for the "},{"text":"time value of money","bold":true},{"text":" when the timing of payment gives the customer or the entity a significant financing benefit. Practical expedient: no adjustment if the gap between transfer and payment is "},{"text":"one year or less","bold":true},{"text":"."}]},{"text":[{"text":"Non-cash consideration:","bold":true},{"text":" measure at "},{"text":"fair value","bold":true},{"text":"; if fair value cannot be reasonably estimated, use the SSP of the goods or services promised."}]},{"text":[{"text":"Consideration payable to a customer","bold":true},{"text":" (e.g. slotting fees, coupons): "},{"text":"reduce the transaction price","bold":true},{"text":", unless it is payment for a distinct good or service from the customer."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Formulas:","bold":true},{"text":" Transaction price excluding VAT = VAT-inclusive amount ÷ (1 + VAT rate). Expected value = Σ (amount × probability). Present value = Amount due ÷ (1 + r)^n."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"VAT:","bold":true},{"text":" an invoice of ₦1,075,000 including VAT at 7.5% gives 1,075,000 ÷ 1.075 = "},{"text":"₦1,000,000","bold":true},{"text":"; the ₦75,000 is owed to the tax authority. (Trap: 1,075,000 × 92.5% = ₦994,375 is wrong.)"}]},{"text":[{"text":"Rebate:","bold":true},{"text":" Eko Foods Plc sells 5,000 cartons at ₦2,000 to a distributor, with a 4% rebate it expects to pay. Transaction price = 5,000 × 2,000 × 96% = "},{"text":"₦9,600,000","bold":true},{"text":" (the ₦400,000 is a refund liability)."}]},{"text":[{"text":"Expected value:","bold":true},{"text":" Benin Builders Ltd has a ₦10,000,000 fee plus a bonus: nil (20%), ₦500,000 (50%), ₦1,000,000 (30%). Expected bonus = 0 + 250,000 + 300,000 = ₦550,000, so transaction price = ₦10,550,000 (if the constraint is passed). If the bonus were all-or-nothing, use the most likely amount instead."}]},{"text":[{"text":"Volume discount (worked fully).","bold":true},{"text":" ABC Limited sells to XYZ at ₦200 per unit for 2017, falling to ₦150 per unit "},{"text":"for all units","bold":true},{"text":" if XYZ buys more than 1,200 units in the year. At the start ABC does not expect the target to be met."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"30.06.17: 600 × ₦200 = ₦120,000. Dr Trade receivables 120,000; Cr Revenue 120,000."}]},{"text":[{"text":"01.10.17: 500 more units; ABC now expects the target. 500 × ₦150 = ₦75,000. Dr Trade receivables 75,000; Cr Revenue 75,000."}]},{"text":[{"text":"Catch-up on the first 600 units: 600 × (200 − 150) = ₦30,000 "},{"text":"reduction","bold":true},{"text":". Dr Revenue 30,000; Cr Trade receivables 30,000."}]},{"text":[{"text":"01.12.17: 200 × ₦150 = ₦30,000. Dr Trade receivables 30,000; Cr Revenue 30,000."}]},{"text":[{"text":"Total = 120,000 + 75,000 − 30,000 + 30,000 = "},{"text":"₦195,000","bold":true},{"text":" = 1,300 × ₦150 (check). Net revenue on 01.10.17 = ₦45,000."}]}]},{"type":"paragraph","text":[{"text":"If the target is expected "},{"text":"from the start","bold":true},{"text":", use the lower price from day one (e.g. 1,200 units at ₦800, not ₦1,000 = ₦960,000); if it is "},{"text":"never","bold":true},{"text":" expected (and not met), use the full price throughout (700 × ₦5,000 = ₦3,500,000). Estimating a volume discount is part of "},{"text":"Step 3","bold":true},{"text":"."}]}]},{"text":[{"text":"Significant financing:","bold":true},{"text":" On 1 January 2025, Ikeja Motors Ltd delivers equipment; the customer pays ₦5,000,000 on 31 December 2026; discount rate 10%. Revenue on delivery = 5,000,000 ÷ 1.10² = "},{"text":"₦4,132,231","bold":true},{"text":" (nearest naira). Interest income: 2025 = 10% × 4,132,231 = ₦413,223; 2026 = 10% × 4,545,454 = ₦454,546 (rounded so the total reaches ₦5,000,000). Interest is finance income, not sales revenue."}]},{"text":[{"text":"Non-cash:","bold":true},{"text":" a customer pays with 2,000 bags of cement, fair value ₦5,500 each: revenue = "},{"text":"₦11,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Consideration payable:","bold":true},{"text":" Eko Foods Plc sells ₦20,000,000 of goods to a supermarket and pays it a ₦1,000,000 shelf-placement fee for no distinct service. Revenue = 20,000,000 − 1,000,000 = "},{"text":"₦19,000,000","bold":true},{"text":"."}]}]}]},{"number":"2.4","title":"Step 4: allocating the transaction price","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Stand-alone selling price (SSP):","bold":true},{"text":" the price at which an entity would sell a promised good or service separately to a customer."}]},{"text":[{"text":"Allocate the transaction price to each performance obligation in proportion to "},{"text":"relative stand-alone selling prices","bold":true},{"text":" at contract inception (not costs, order of delivery or equal shares)."}]},{"text":[{"text":"Formula:","bold":true},{"text":" Allocation to an obligation = (SSP of that obligation ÷ Total of all SSPs) × Transaction price."}]},{"text":[{"text":"Discount:","bold":true},{"text":" Discount = Total SSPs − Transaction price. Allocate it to "},{"text":"all","bold":true},{"text":" performance obligations proportionately (on an SSP basis), unless observable evidence shows it relates to specific obligations only."}]},{"text":[{"text":"If an SSP is not observable, estimate it","bold":true},{"text":", using:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Adjusted market assessment approach:","bold":true},{"text":" what customers in the market would pay."}]},{"text":[{"text":"Expected cost plus a margin approach.","bold":true}]},{"text":[{"text":"Residual approach:","bold":true},{"text":" total transaction price less observable SSPs of the other items (only where the SSP is highly variable or uncertain)."}]}]}],"explainMore":[{"type":"list","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 12, $study_guide$ordered":false,"items":[{"text":[{"text":"Two items:","bold":true},{"text":" a software licence and 12-month support are sold for ₦1,200,000. SSPs: licence ₦1,000,000; support ₦300,000; total ₦1,300,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Licence: 1,000,000/1,300,000 × 1,200,000 = "},{"text":"₦923,077","bold":true}]},{"text":[{"text":"Support: 300,000/1,300,000 × 1,200,000 = "},{"text":"₦276,923","bold":true}]},{"text":[{"text":"Total ₦1,200,000 (nearest naira). Use fractions, not rounded percentages (76.92% × 1,200,000 = ₦923,040, slightly off)."}]}]}]},{"text":[{"text":"Discount allocation:","bold":true},{"text":" a computer (SSP ₦500,000) and printer (SSP ₦300,000) sold for ₦700,000. Discount = 800,000 − 700,000 = "},{"text":"₦100,000","bold":true},{"text":". Computer 5/8 × 700,000 = "},{"text":"₦437,500","bold":true},{"text":"; printer 3/8 × 700,000 = "},{"text":"₦262,500","bold":true},{"text":". Discount borne: computer ₦62,500, printer ₦37,500. For one item: share of discount = (its SSP ÷ total SSPs) × discount, e.g. earbuds (SSP ₦100,000) in a ₦500,000 bundle sold for ₦450,000 take 1/5 × 50,000 = ₦10,000."}]},{"text":[{"text":"Three items:","bold":true},{"text":" Lagos Smart Homes Ltd sells CCTV, installation and one year's maintenance for ₦2,700,000. SSPs: CCTV ₦2,000,000; installation ₦400,000; maintenance ₦600,000; total ₦3,000,000. Ratio = 2,700,000/3,000,000 = 0.9: CCTV ₦1,800,000; installation ₦360,000; maintenance ₦540,000. Each item's percentage of the price equals its SSP share (CCTV 2/3 = 66.67%)."}]},{"text":[{"text":"Estimating SSP:","bold":true},{"text":" a support service costs ₦400,000 to provide and the entity's normal margin is 25% on cost: SSP = 400,000 × 1.25 = ₦500,000."}]},{"text":[{"text":"Traps:","bold":true},{"text":" do not give items their full SSP and the leftover to one item (residual approach, limited cases only), or the discount to the last-delivered or dearest item."}]}]}]},{"number":"2.5","title":"Step 5: recognising revenue (point in time or over time)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Recognise revenue "},{"text":"when (or as)","bold":true},{"text":" a performance obligation is satisfied by transferring control of a promised good or service."}]},{"text":[{"text":"Control:","bold":true},{"text":" the ability to "},{"text":"direct the use of, and obtain substantially all of the remaining benefits from","bold":true},{"text":", the asset."}]},{"text":[{"text":"Over time","bold":true},{"text":" if "},{"text":"any one","bold":true},{"text":" of 3 criteria is met; otherwise "},{"text":"at a point in time","bold":true},{"text":":"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The customer "},{"text":"simultaneously receives and consumes","bold":true},{"text":" the benefits as the entity performs (e.g. cleaning, security)."}]},{"text":[{"text":"The entity's performance "},{"text":"creates or enhances an asset that the customer controls","bold":true},{"text":" as it is created or enhanced (e.g. building on the customer's land)."}]},{"text":[{"text":"The entity's performance "},{"text":"does not create an asset with an alternative use","bold":true},{"text":" to the entity "},{"text":"and","bold":true},{"text":" the entity has an "},{"text":"enforceable right to payment for performance completed to date","bold":true},{"text":" (both parts needed)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"5 indicators that control has passed at a point in time:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The entity has a "},{"text":"present right to payment","bold":true},{"text":"."}]},{"text":[{"text":"The customer has "},{"text":"legal title","bold":true},{"text":"."}]},{"text":[{"text":"The entity has transferred "},{"text":"physical possession","bold":true},{"text":"."}]},{"text":[{"text":"The customer has the "},{"text":"significant risks and rewards","bold":true},{"text":" of ownership."}]},{"text":[{"text":"The customer has "},{"text":"accepted","bold":true},{"text":" the asset."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Typical pattern:","bold":true},{"text":" goods at a point in time; services over time."}]},{"text":[{"text":"Over time:","bold":true},{"text":" select a "},{"text":"measure of progress","bold":true},{"text":" towards complete satisfaction. "},{"text":"Output methods","bold":true},{"text":" (surveys of work done, milestones, units delivered, time elapsed) or "},{"text":"input methods","bold":true},{"text":" (costs incurred, labour hours)."}]},{"text":[{"text":"Formula (cost-to-cost input method):","bold":true},{"text":" Revenue to date = (Costs incurred to date ÷ Total expected costs) × Transaction price. Revenue this year = Revenue to date − Revenue recognised in earlier years."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Point in time:","bold":true},{"text":" a customer pays for a generator in Alaba Market and carries it home: revenue at the point of sale (control passes), not on first use or over its warranty or life."}]},{"text":[{"text":"Over time:","bold":true},{"text":" GuardSafe Ltd guards a Lekki estate for 12 months (criterion 1); BuildRight Ltd builds on its customer's land in Abuja (criterion 2); Ekiti Fabrication Ltd makes a machine to a unique design with an enforceable right to payment for work done (criterion 3)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"simultaneously receives and consumes\" is an "},{"text":"over-time","bold":true},{"text":" criterion, not a point-in-time indicator; \"legal title\" is a point-in-time indicator, not a contract criterion or distinct test."}]},{"text":[{"text":"Time-based (straight line):","bold":true},{"text":" On 1 April 2025, Ibadan Cleaners Ltd signs a 12-month contract for ₦1,200,000. Year to 31 December 2025: 1,200,000 × 9/12 = "},{"text":"₦900,000","bold":true},{"text":"; $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 13, $study_guide$₦300,000 next year. Similarly ₦900,000 of support spread evenly over 5 years gives ₦180,000 a year."}]},{"text":[{"text":"Cost-to-cost:","bold":true},{"text":" Delta Roads Ltd: price ₦80,000,000; total expected costs ₦60,000,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"First year: costs to date ₦15,000,000: 15/60 = 25%; revenue = ₦20,000,000."}]},{"text":[{"text":"Second year: costs to date ₦42,000,000 (estimate unchanged): 42/60 = 70%; cumulative revenue ₦56,000,000; second-year revenue = 56,000,000 − 20,000,000 = "},{"text":"₦36,000,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Steps 4 and 5 together:","bold":true},{"text":" On 1 October 2025, a telecom company sells a phone plus 12 months of data for ₦360,000. SSPs: phone ₦250,000, data ₦200,000 (total ₦450,000). Phone = 250/450 × 360,000 = ₦200,000 (point in time, 1 October). Data = ₦160,000, earned evenly: 160,000 × 3/12 = ₦40,000. Revenue to 31 December 2025 = "},{"text":"₦240,000","bold":true},{"text":"; the other ₦120,000 is a contract liability (deferred revenue)."}]}]}]},{"number":"2.6","title":"Contract costs and principal vs agent","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Incremental costs of obtaining a contract","bold":true},{"text":" (costs the entity would not have incurred without the contract, e.g. a sales commission): recognise as an "},{"text":"asset","bold":true},{"text":" if the entity expects to recover them. Practical expedient: "},{"text":"expense","bold":true},{"text":" them if the amortisation period would be "},{"text":"one year or less","bold":true},{"text":"."}]},{"text":[{"text":"Costs incurred "},{"text":"whether or not","bold":true},{"text":" the contract is won (bid costs, legal fees, travel) are "},{"text":"expensed","bold":true},{"text":", unless explicitly chargeable to the customer."}]},{"text":[{"text":"Costs to fulfil a contract","bold":true},{"text":" (not covered by IAS 2, IAS 16 or IAS 38): an asset only if all 3 apply: (1) they relate directly to a contract; (2) they generate or enhance resources used to satisfy future performance obligations; (3) they are expected to be recovered. General and administrative costs and wasted materials are expensed."}]},{"text":[{"text":"Contract cost assets are "},{"text":"amortised","bold":true},{"text":" on a systematic basis consistent with the transfer of the related goods or services, and tested for "},{"text":"impairment","bold":true},{"text":"."}]},{"text":[{"text":"Principal:","bold":true},{"text":" controls the good or service "},{"text":"before","bold":true},{"text":" it is transferred to the customer; recognises revenue "},{"text":"gross","bold":true},{"text":" (full amount). "},{"text":"Agent:","bold":true},{"text":" arranges for another party to provide it; recognises revenue "},{"text":"net","bold":true},{"text":" (its fee or commission)."}]},{"text":[{"text":"Indicators of a principal:","bold":true},{"text":" (1) primarily responsible for fulfilling the promise; (2) bears "},{"text":"inventory risk","bold":true},{"text":"; (3) has "},{"text":"discretion in setting the price","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Commission:","bold":true},{"text":" Abuja Data Ltd pays its salesperson ₦600,000 commission for winning a 3-year service contract. Asset ₦600,000; amortise 600,000 ÷ 3 = "},{"text":"₦200,000","bold":true},{"text":" a year. The ₦150,000 legal fees on the bid, paid whether it won or not, are expensed."}]},{"text":[{"text":"Agent vs principal:","bold":true},{"text":" Oja Online Ltd sells a ₦50,000 blender on its website for a vendor who ships it, sets the price and bears inventory risk; Oja keeps 10%. Oja is an agent: revenue = "},{"text":"₦5,000","bold":true},{"text":". Had Oja bought and held the blenders and set the price, it would be principal: revenue ₦50,000, cost of sales ₦45,000."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IFRS 15: issued 28 May 2014, effective 1 January 2018; replaced IAS 18, IAS 11, IFRIC 13, 15, 18 and SIC-31."}]},{"text":[{"text":"Revenue = income from ordinary activities; recognised when (or as) "},{"text":"control","bold":true},{"text":" passes."}]},{"text":[{"text":"Five steps: contract, performance obligations, transaction price, allocate, recognise."}]},{"text":[{"text":"Contract: 5 criteria; fail one and money received is a liability while you keep reassessing."}]},{"text":[{"text":"Distinct = capable of being distinct + separately identifiable; a series counts as one obligation."}]},{"text":[{"text":"Transaction price excludes VAT; covers variable consideration (expected value or most likely amount, constrained), financing, non-cash, consideration payable."}]},{"text":[{"text":"Allocate on relative SSPs; spread any discount over all obligations; estimate SSPs not observable."}]},{"text":[{"text":"Over time (3 criteria) with a measure of progress; otherwise point in time (5 indicators)."}]},{"text":[{"text":"Commissions capitalised (expedient if 1 year or less); principal gross, agent net; service-type warranty is a separate obligation."}]}]}],"theory":{"itemId":"2e164bcb-4351-5dfb-a698-0355350a6d6d","question":[{"type":"paragraph","text":[{"text":"On 1 July 2025, Ikeja Solar Ltd sells a solar system for ₦4,500,000, covering equipment, installation and 12 months' maintenance. SSPs: equipment ₦3,600,000; installation ₦600,000; maintenance ₦800,000. Equipment is delivered and installed in July 2025; maintenance is provided evenly. Calculate revenue for the year ended 31 December 2025."}]}]},"practice":[{"topic":"IFRS 15 Revenue","named":false}]}},{"kind":"note","itemId":"11c15e88-47cf-50f8-9e38-ec586598067d","sourceKey":"guide-topic:3","position":3,"payload":{"title":"IAS 1 Presentation of Financial Statements","body":"The objective, scope and complete set of financial statements; the eight general features; the statement of financial position a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 14, $study_guide$nd current/non-current classification; profit or loss and other comprehensive income (nature vs function, OCI, reclassification); the statement of changes in equity, cash flows and notes; preparing the statements from a trial balance.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The objective, scope and complete set of financial statements; the eight general features; the statement of financial position and current/non-current classification; profit or loss and other comprehensive income (nature vs function, OCI, reclassification); the statement of changes in equity, cash flows and notes; preparing the statements from a trial balance."}],"lessons":[{"number":"3.1","title":"Objective, scope and the complete set","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Objective:","bold":true},{"text":" to prescribe the basis for presentation of general purpose financial statements to ensure "},{"text":"comparability","bold":true},{"text":" both with the entity's own previous periods and with other entities. IAS 1 sets the line items for every statement "},{"text":"except the statement of cash flows","bold":true},{"text":" (IAS 7)."}]},{"text":[{"text":"Scope:","bold":true},{"text":" all general purpose financial statements (individual, separate or consolidated; banks included), but "},{"text":"not","bold":true},{"text":" the structure and content of "},{"text":"condensed interim financial statements","bold":true},{"text":" (IAS 34)."}]},{"text":[{"text":"General purpose financial statements:","bold":true},{"text":" those intended to meet the needs of users who are not in a position to require an entity to prepare reports tailored to their particular information needs."}]},{"text":[{"text":"Financial statements:","bold":true},{"text":" a "},{"text":"structured representation of the financial position and financial performance","bold":true},{"text":" of an entity, giving information useful for economic decisions. They also show the results of "},{"text":"management's stewardship","bold":true},{"text":" of the resources entrusted to it."}]}]},{"type":"paragraph","text":[{"text":"Complete set of financial statements:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Statement of financial position as at the end of the period."}]},{"text":[{"text":"Statement of profit or loss and other comprehensive income for the period."}]},{"text":[{"text":"Statement of changes in equity for the period."}]},{"text":[{"text":"Statement of cash flows for the period."}]},{"text":[{"text":"Notes, comprising material accounting policy information and other explanatory information."}]},{"text":[{"text":"Comparative information for the preceding period."}]},{"text":[{"text":"A statement of financial position at the "},{"text":"beginning of the preceding period","bold":true},{"text":", when a retrospective policy change, retrospective restatement or reclassification has a material effect on it."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"directors' report","bold":true},{"text":", a financial review by management, environmental reports and value added statements sit "},{"text":"outside","bold":true},{"text":" the financial statements and outside IFRSs: they are "},{"text":"not","bold":true},{"text":" part of the set."}]},{"text":[{"text":"Titles:","bold":true},{"text":" other titles are permitted, e.g. \"statement of comprehensive income\"."}]},{"text":[{"text":"One or two statements:","bold":true},{"text":" a single statement (profit or loss section first, then OCI), or a separate statement of profit or loss that "},{"text":"immediately precedes","bold":true},{"text":" the statement presenting comprehensive income, which "},{"text":"begins with profit or loss","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Significant accounting policies\" was replaced by \""},{"text":"material accounting policy information","bold":true},{"text":"\" from 2023; options may use either phrase."}]},{"text":[{"text":"Third statement of financial position:","bold":true},{"text":" Ikeja Paints Plc (year end 31 December 2025) changes a policy retrospectively with a material effect at 1 January 2024. It presents "},{"text":"three","bold":true},{"text":": 31 December 2025, 31 December 2024 and 1 January 2024."}]},{"text":[{"text":"IFRS 18 "},{"text":"Presentation and Disclosure in Financial Statements","italic":true},{"text":" (issued April 2024) replaces IAS 1 for periods beginning on or after 1 January 2027. Learn IAS 1 as set out here."}]}]}]},{"number":"3.2","title":"The eight general features","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Fair presentation and compliance:","bold":true},{"text":" faithful representation of transactions in line with the "},{"text":"Conceptual Framework's definitions and recognition criteria","bold":true},{"text":". A complying entity makes an "},{"text":"explicit and unreserved statement of compliance in the notes","bold":true},{"text":", and cannot claim compliance unless it meets "},{"text":"all","bold":true},{"text":" requirements. Disclosure or notes "},{"text":"cannot rectify","bold":true},{"text":" inappropriate accounting policies."}]},{"text":[{"text":"Going concern:","bold":true},{"text":" prepare on this basis "},{"text":"unless management intends to liquidate the entity or cease trading, or has no realistic alternative but to do so","bold":true},{"text":". Management looks "},{"text":"at least, but not limited to, twelve months from the end of the reporting period","bold":true},{"text":". If not a going concern, disclose "},{"text":"that fact, the basis used and the reason","bold":true},{"text":"."}]},{"text":[{"text":"Accrual basis:","bold":true},{"text":" for everything except cash flow information."}]},{"text":[{"text":"Materiality and aggregation:","bold":true},{"text":" "},{"text":"Material","bold":true},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 15, $study_guide$ext":" information is information whose omission, misstatement or obscuring could reasonably be expected to influence decisions that primary users make on the basis of general purpose financial statements. It depends on "},{"text":"nature or magnitude, or both","bold":true},{"text":". An immaterial item is "},{"text":"aggregated","bold":true},{"text":" with others and may still warrant separate presentation in the notes."}]},{"text":[{"text":"Offsetting:","bold":true},{"text":" do not offset assets and liabilities, or income and expenses, "},{"text":"unless required or permitted by an IFRS","bold":true},{"text":"."}]},{"text":[{"text":"Frequency:","bold":true},{"text":" a complete set "},{"text":"at least annually","bold":true},{"text":". For a longer or shorter period, disclose "},{"text":"the reason","bold":true},{"text":" and "},{"text":"that amounts are not entirely comparable","bold":true},{"text":"."}]},{"text":[{"text":"Comparative information:","bold":true},{"text":" minimum "},{"text":"two","bold":true},{"text":" statements of financial position, two statements of profit or loss and OCI, two statements of cash flows and two statements of changes in equity, with related notes."}]},{"text":[{"text":"Consistency of presentation:","bold":true},{"text":" keep presentation unless (a) a "},{"text":"significant change in the nature of operations","bold":true},{"text":" (or a review) makes another presentation more appropriate, or (b) "},{"text":"an IFRS requires","bold":true},{"text":" a change."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accrual:","bold":true},{"text":" Surulere Prints Ltd delivers goods worth ₦4m in December 2025 and is paid in February 2026: revenue belongs in 2025."}]},{"text":[{"text":"Not offsetting:","bold":true},{"text":" assets net of valuation allowances. Receivables ₦45m less allowance ₦3m are shown at "},{"text":"₦42m","bold":true},{"text":"."}]},{"text":[{"text":"Required netting:","bold":true},{"text":" a disposal gain = proceeds − carrying amount − selling expenses. Ota Bottling Ltd sells a generator for ₦8m, carrying amount ₦5.5m, selling costs ₦0.3m: gain = 8 − 5.5 − 0.3 = "},{"text":"₦2.2m","bold":true},{"text":". Gains and losses on a group of similar transactions (e.g. foreign exchange) are shown "},{"text":"net, but separately if material","bold":true},{"text":"."}]},{"text":[{"text":"Departure","bold":true},{"text":" from an IFRS is allowed only in "},{"text":"extremely rare","bold":true},{"text":" cases where compliance would be so misleading that it conflicts with the objective of financial statements; the departure and its effect are disclosed."}]},{"text":[{"text":"Reclassifying comparatives:","bold":true},{"text":" Ibadan Ceramics Ltd moves delivery costs from administrative to distribution costs. It "},{"text":"reclassifies the comparatives unless impracticable","bold":true},{"text":" (cannot be done after every reasonable effort) and discloses the "},{"text":"nature, amount and reason","bold":true},{"text":". A new director's preference or a higher profit is never a valid reason."}]}]}]},{"number":"3.3","title":"Statement of financial position","mustKnow":[{"type":"paragraph","text":[{"text":"Minimum line items:","bold":true}]},{"type":"table","header":[[{"text":"Assets"}],[{"text":"Liabilities and equity"}]],"rows":[[[{"text":"Property, plant and equipment"}],[{"text":"Trade and other payables"}]],[[{"text":"Investment property"}],[{"text":"Provisions"}]],[[{"text":"Intangible assets"}],[{"text":"Financial liabilities"}]],[[{"text":"Financial assets"}],[{"text":"Current tax liabilities and assets"}]],[[{"text":"Equity-accounted investments"}],[{"text":"Deferred tax liabilities and assets"}]],[[{"text":"Biological assets"}],[{"text":"Liabilities of disposal groups held for sale"}]],[[{"text":"Inventories"}],[{"text":"Non-controlling interests, within equity"}]],[[{"text":"Trade and other receivables"}],[{"text":"Issued capital and reserves of owners of the parent"}]],[[{"text":"Cash and cash equivalents; assets held for sale"}],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost of sales (or any income or expense) is "},{"text":"not","bold":true},{"text":" a line item here. Add lines and subtotals when relevant."}]},{"text":[{"text":"Use a current/non-current split "},{"text":"unless","bold":true},{"text":" an "},{"text":"order of liquidity","bold":true},{"text":" presentation is "},{"text":"reliable and more relevant","bold":true},{"text":" (many financial institutions)."}]},{"text":[{"text":"Deferred tax","bold":true},{"text":" is "},{"text":"always non-current","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Current asset","bold":true},{"text":" if: (1) realised, sold or consumed in the "},{"text":"normal operating cycle","bold":true},{"text":"; (2) held primarily for "},{"text":"trading","bold":true},{"text":"; (3) realised within "},{"text":"twelve months","bold":true},{"text":" after the reporting period; or (4) "},{"text":"cash or cash equivalent","bold":true},{"text":", unless restricted for at least twelve months. Otherwise non-current."}]},{"type":"paragraph","text":[{"text":"Current liability","bold":true},{"text":" if: (1) settled in the "},{"text":"normal operating cycle","bold":true},{"text":"; (2) held primarily for "},{"text":"trading","bold":true},{"text":"; (3) due within "},{"text":"twelve months","bold":true},{"text":"; or (4) the entity has "},{"text":"no right at the end of the reporting period","bold":true},{"text":" to defer settlement for at least twelve months. Otherwise non-current."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Operating cycle:","bold":true},{"text":" time from acquiring assets for processing to realising them in cash. If not clearly identifiable, "},{"text":"assume twelve months","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cycle beats twelve months:","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 16, $study_guide$bold":true},{"text":" Onitsha Spirits Ltd's whisky matured over three years is a "},{"text":"current asset","bold":true},{"text":". Port Harcourt Oil Services Ltd's trade payables due in 14 months are "},{"text":"current","bold":true},{"text":", being working capital of the normal cycle."}]},{"text":[{"text":"Refinancing after year end:","bold":true},{"text":" Abuja Cement Plc's loan is due four months after 31 December 2025; long-term refinancing is agreed on 20 February 2026. At the reporting date there was no right to defer, so it is "},{"text":"current","bold":true},{"text":"; the refinancing is a "},{"text":"non-adjusting event","bold":true},{"text":". (A right at the reporting date to roll over under an existing facility would make it non-current.)"}]},{"text":[{"text":"Covenant breach:","bold":true},{"text":" a breach by the year end making the loan repayable on demand gives a "},{"text":"current","bold":true},{"text":" liability, even if the lender waives it after the year end. If, "},{"text":"by the year end","bold":true},{"text":", the lender grants a grace period ending "},{"text":"at least twelve months","bold":true},{"text":" later, the loan is "},{"text":"non-current","bold":true},{"text":"."}]},{"text":[{"text":"Intention is irrelevant:","bold":true},{"text":" with a right to defer for twelve months, a liability is non-current even if management plans to repay early."}]},{"text":[{"text":"Instalment loan:","bold":true},{"text":" ₦60m repayable in four equal annual instalments, first due within twelve months: current ₦15m, non-current 60 − 15 = "},{"text":"₦45m","bold":true},{"text":"."}]},{"text":[{"text":"Classify (₦m):","bold":true},{"text":" inventories 25, receivables 14, cash 9, cash restricted by court order for four years 6, plant 70. Current assets = 25 + 14 + 9 = "},{"text":"48","bold":true},{"text":". Trade payables 30, overdraft 5, current tax 12, current portion of loan 10, loan due 2029 50, deferred tax 7. Current liabilities = 30 + 5 + 12 + 10 = "},{"text":"57","bold":true},{"text":"."}]},{"text":[{"text":"Notes subclassify lines (e.g. inventories into materials, work in progress, finished goods) and give share capital details and the nature and purpose of each reserve."}]}]}]},{"number":"3.4","title":"Statement of profit or loss and other comprehensive income","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Besides the two sections, present: "},{"text":"profit or loss; total other comprehensive income; comprehensive income for the period","bold":true},{"text":". Also show profit and comprehensive income attributable to "},{"text":"non-controlling interests and owners of the parent","bold":true},{"text":"."}]},{"text":[{"text":"Other comprehensive income:","bold":true},{"text":" income and expenses (including reclassification adjustments) not recognised in profit or loss as required or permitted by other IFRSs."}]},{"text":[{"text":"Total comprehensive income:","bold":true},{"text":" the change in equity in a period from transactions and other events, "},{"text":"other than transactions with owners in their capacity as owners","bold":true},{"text":". TCI = Profit or loss + OCI."}]},{"text":[{"text":"Reclassification adjustments:","bold":true},{"text":" amounts reclassified to profit or loss in the current period that were recognised in OCI in the current or previous periods."}]},{"text":[{"text":"Minimum profit or loss lines include:","bold":true},{"text":" revenue (interest revenue by the effective interest method shown separately); "},{"text":"finance costs","bold":true},{"text":"; impairment losses (IFRS 9); share of profit of associates and joint ventures; "},{"text":"tax expense","bold":true},{"text":"; "},{"text":"a single amount for discontinued operations","bold":true},{"text":". Changes in revaluation surplus are "},{"text":"not","bold":true},{"text":" a profit or loss line."}]}]},{"type":"table","header":[[{"text":"OCI: will NOT be reclassified to profit or loss"}],[{"text":"OCI: will be reclassified when conditions are met"}]],"rows":[[[{"text":"Changes in revaluation surplus (IAS 16, IAS 38)"}],[{"text":"Translation differences on a foreign operation"}]],[[{"text":"Remeasurements of defined benefit plans"}],[{"text":"Effective portion of cash flow hedge gains and losses"}]],[[{"text":"Equity investments designated at fair value through OCI"}],[{"text":"Debt-type financial assets at fair value through OCI"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"OCI items are shown "},{"text":"net of tax","bold":true},{"text":", or gross with one tax amount split between the two groups."}]},{"text":[{"text":"Extraordinary items are prohibited","bold":true},{"text":" in the statements and the notes."}]}]},{"type":"table","header":[[{"text":"Nature of expense method"}],[{"text":"Function (cost of sales) method"}]],"rows":[[[{"text":"Revenue; Other income"}],[{"text":"Revenue; Cost of sales → Gross profit"}]],[[{"text":"Changes in inventories of finished goods and WIP"}],[{"text":"Other income"}]],[[{"text":"Raw materials and consumables used"}],[{"text":"Distribution costs"}]],[[{"text":"Employee benefits; Depreciation and amortisation"}],[{"text":"Administrative expenses"}]],[[{"text":"Other expenses → Profit before tax"}],[{"text":"Other expenses → Profit before tax"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Nature","bold":true},{"text":" is simple: no allocation to functions. "},{"text":"Function","bold":true},{"text":" can be more relevant but may need arbitrary allocations; it "},{"text":"must also disclose depreciation and amortisation and employee benefits expense","bold":true},{"text":"."}]},{"text":[{"text":"Separate disclosure","bold":true},{"text":" of material items arises from: write-downs of inventories to NRV or PPE to recoverable amount (and reversals); restructurings; disposals of PPE; disposals of investments; discontinued operations; litigation settlements; other reversals of provisi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 17, $study_guide$ons."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Function (₦m):","bold":true},{"text":" revenue 180, cost of sales 105, other income 4, distribution 12, administrative 20, other expenses 3, finance costs 6. Gross profit = 180 − 105 = "},{"text":"75","bold":true},{"text":"; PBT = 75 + 4 − 12 − 20 − 3 − 6 = "},{"text":"38","bold":true},{"text":"."}]},{"text":[{"text":"Nature (₦m):","bold":true},{"text":" revenue 250, other income 6, "},{"text":"decrease","bold":true},{"text":" in inventories 8, raw materials 110, employees 50, depreciation 20, other 15. Expenses = 203; PBT = 256 − 203 = "},{"text":"53","bold":true},{"text":". An "},{"text":"increase","bold":true},{"text":" in inventories reduces total expenses."}]},{"text":[{"text":"An IAS 16 revaluation gain goes to "},{"text":"OCI","bold":true},{"text":". Impairment of receivables, disposal gains, interest revenue and share of an associate's profit go to "},{"text":"profit or loss","bold":true},{"text":"."}]},{"text":[{"text":"TCI:","bold":true},{"text":" profit ₦40m; revaluation gain ₦10m with 30% deferred tax, net = 10 × 70% = ₦7m; translation loss ₦2m. TCI = 40 + 7 − 2 = "},{"text":"₦45m","bold":true},{"text":". If ₦9m belongs to non-controlling interests, owners of the parent get "},{"text":"₦36m","bold":true},{"text":". Reverse: TCI ₦72m including OCI ₦12m means profit = "},{"text":"₦60m","bold":true},{"text":"."}]},{"text":[{"text":"Reclassification:","bold":true},{"text":" translation gain this year ₦3m, then the subsidiary is sold and cumulative gains of ₦5m go to profit or loss. Net OCI = 3 − 5 = "},{"text":"(₦2m)","bold":true},{"text":", so the gain is not counted twice."}]}]}]},{"number":"3.5","title":"Statement of changes in equity, cash flows and notes","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"statement of changes in equity","bold":true},{"text":" links the "},{"text":"statement of financial position and the statement of comprehensive income","bold":true},{"text":". It shows: TCI split between owners of the parent and non-controlling interests; the effects of retrospective application or restatement (IAS 8) for each component; and, for each component, a reconciliation of opening to closing amounts showing changes from "},{"text":"(i) profit or loss, (ii) OCI, (iii) transactions with owners in their capacity as owners","bold":true},{"text":"."}]},{"text":[{"text":"Transactions with owners:","bold":true},{"text":" share issues, buy-backs, "},{"text":"dividends","bold":true},{"text":". Dividends and dividends per share go "},{"text":"in the statement of changes in equity or in the notes","bold":true},{"text":", never as an expense."}]},{"text":[{"text":"Statement of cash flows:","bold":true},{"text":" shows the "},{"text":"ability of the entity to generate cash and cash equivalents and its needs to utilise those cash flows","bold":true},{"text":" (IAS 7)."}]},{"text":[{"text":"Notes:","bold":true},{"text":" (a) basis of preparation and accounting policies; (b) "},{"text":"information required by IFRSs not presented elsewhere","bold":true},{"text":" in the financial statements; (c) other information relevant to understanding them. Usual order: (1) "},{"text":"statement of compliance with IFRSs","bold":true},{"text":"; (2) material accounting policies; (3) supporting information for line items; (4) other disclosures such as contingent liabilities."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Formulas:","bold":true},{"text":" Closing retained earnings = Opening (restated) + Profit − Dividends − Transfers to reserves. Share premium = Shares issued × (Issue price − Nominal value). Closing equity = Opening equity + TCI + Share issues − Dividends."}]},{"text":[{"text":"Worked example","bold":true},{"text":", Ilupeju Foods Ltd, year to 31 December 2025 (₦'000): prior period error overstated earlier profits by 600; issued 4,000,000 ₦1 shares at ₦1.75; profit 5,200; revaluation gain 800; dividends 1,500."}],"blocks":[{"type":"table","header":[[],[{"text":"Share capital"}],[{"text":"Share premium"}],[{"text":"Revaluation surplus"}],[{"text":"Retained earnings"}],[{"text":"Total"}]],"rows":[[[{"text":"1 Jan 2025"}],[{"text":"10,000"}],[{"text":"2,000"}],[{"text":"1,500"}],[{"text":"8,000"}],[{"text":"21,500"}]],[[{"text":"Prior period error"}],[],[],[],[{"text":"(600)"}],[{"text":"(600)"}]],[[{"text":"Restated"}],[{"text":"10,000"}],[{"text":"2,000"}],[{"text":"1,500"}],[{"text":"7,400"}],[{"text":"20,900"}]],[[{"text":"Share issue"}],[{"text":"4,000"}],[{"text":"3,000"}],[],[],[{"text":"7,000"}]],[[{"text":"Profit"}],[],[],[],[{"text":"5,200"}],[{"text":"5,200"}]],[[{"text":"OCI"}],[],[],[{"text":"800"}],[],[{"text":"800"}]],[[{"text":"Dividends"}],[],[],[],[{"text":"(1,500)"}],[{"text":"(1,500)"}]],[[{"text":"31 Dec 2025"}],[{"text":"14,000"}],[{"text":"5,000"}],[{"text":"2,300"}],[{"text":"11,100"}],[{"text":"32,400"}]]]},{"type":"paragraph","text":[{"text":"Share premium = 4,000 × (1.75 − 1.00) = 3,000. TCI = 5,200 + 800 = 6,000. Check: 20,900 + 7,000 + 6,000 − 1,500 = 32,400."}]}]},{"text":[{"text":"Traps:","bold":true},{"text":" OCI goes to its own reserve, not retained earnings. An error adjusts the "},{"text":"opening","bold":true},{"text":" balance. A transfer to general reserve lowers retained earnings without changing total equity: ₦120m + ₦35m − ₦12m dividends − ₦5m transfer = "},{"text":"₦138m","bold":true},{"text":"."}]}]}]},{"number":"3.6","title":"Preparing the statements from a trial balance","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cost of sales","bold":true},{"text":" = Opening inventory + Purchases − Closing inventory (add carriage inwards; deduct returns outwards)."}]},{"text":[{"text":"Charge "},{"text":"depreciation","bold":true},{"text":" for the year and add it to accumulated depreciation."}]},{"text":[{"text":"Accruals","bold":true},{"text":" increase the expense$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 18, $study_guide$ and are current liabilities; "},{"text":"prepayments","bold":true},{"text":" reduce the expense and are current assets."}]},{"text":[{"text":"Group by function: "},{"text":"distribution","bold":true},{"text":" (carriage outwards, selling); "},{"text":"administrative","bold":true},{"text":" (salaries, rent, rates, insurance, office, irrecoverable debts, depreciation); "},{"text":"finance costs","bold":true},{"text":" (full year's interest). Rent received is "},{"text":"other income","bold":true},{"text":"."}]},{"text":[{"text":"Tax is deducted after profit before tax; unpaid tax is a current liability. Dividends go to the statement of changes in equity."}]},{"text":[{"text":"Check total assets = total equity and liabilities."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example.","bold":true},{"text":" Ikorodu Traders Ltd, trial balance at 31 December 2025 (₦'000):"}]},{"type":"table","header":[[{"text":"Account"}],[{"text":"Dr"}],[{"text":"Cr"}]],"rows":[[[{"text":"Land at cost"}],[{"text":"5,000"}],[]],[[{"text":"Plant at cost; accumulated depreciation 1 Jan"}],[{"text":"2,400"}],[{"text":"600"}]],[[{"text":"Inventory 1 Jan 2025"}],[{"text":"900"}],[]],[[{"text":"Purchases; Sales revenue"}],[{"text":"6,200"}],[{"text":"10,400"}]],[[{"text":"Trade receivables; Trade payables"}],[{"text":"1,350"}],[{"text":"980"}]],[[{"text":"Cash at bank"}],[{"text":"410"}],[]],[[{"text":"Salaries 1,150; Rent and rates 360; Electricity 140"}],[{"text":"1,650"}],[]],[[{"text":"Insurance 120; Carriage outwards 90; Irrecoverable debts 40"}],[{"text":"250"}],[]],[[{"text":"Loan interest paid 60; Dividend paid 200"}],[{"text":"260"}],[]],[[{"text":"Share capital (₦1 shares) 4,000; Share premium 500"}],[],[{"text":"4,500"}]],[[{"text":"Retained earnings 1 Jan 2025"}],[],[{"text":"740"}]],[[{"text":"10% loan notes (repayable 2030)"}],[],[{"text":"1,200"}]],[[{"text":"Totals","bold":true}],[{"text":"18,420","bold":true}],[{"text":"18,420","bold":true}]]]},{"type":"paragraph","text":[{"text":"Adjustments: closing inventory 1,100; plant depreciation 15% on cost; electricity accrued 30; insurance prepaid 30; tax 450."}]},{"type":"paragraph","text":[{"text":"Workings: Cost of sales = 900 + 6,200 − 1,100 = 6,000. Depreciation = 15% × 2,400 = 360. Interest = 10% × 1,200 = 120 (60 accrued). Administrative = 1,150 + 360 + (140 + 30) + (120 − 30) + 40 + 360 = 2,170."}]},{"type":"table","header":[[{"text":"Statement of profit or loss, year to 31 Dec 2025"}],[{"text":"₦'000"}]],"rows":[[[{"text":"Revenue"}],[{"text":"10,400"}]],[[{"text":"Cost of sales"}],[{"text":"(6,000)"}]],[[{"text":"Gross profit"}],[{"text":"4,400"}]],[[{"text":"Distribution costs"}],[{"text":"(90)"}]],[[{"text":"Administrative expenses"}],[{"text":"(2,170)"}]],[[{"text":"Finance costs"}],[{"text":"(120)"}]],[[{"text":"Profit before tax"}],[{"text":"2,020"}]],[[{"text":"Income tax expense"}],[{"text":"(450)"}]],[[{"text":"Profit for the year"}],[{"text":"1,570"}]]]},{"type":"paragraph","text":[{"text":"Retained earnings = 740 + 1,570 − 200 = 2,110."}]},{"type":"table","header":[[{"text":"Statement of financial position, 31 Dec 2025"}],[{"text":"₦'000"}]],"rows":[[[{"text":"PPE (5,000 + 2,400 − 600 − 360)"}],[{"text":"6,440"}]],[[{"text":"Inventory 1,100 + receivables 1,350 + prepayment 30 + cash 410"}],[{"text":"2,890"}]],[[{"text":"Total assets","bold":true}],[{"text":"9,330","bold":true}]],[[{"text":"Share capital 4,000 + share premium 500 + retained earnings 2,110"}],[{"text":"6,610"}]],[[{"text":"Non-current liability: 10% loan notes"}],[{"text":"1,200"}]],[[{"text":"Current liabilities: payables 980 + accruals (30 + 60) 90 + tax 450"}],[{"text":"1,520"}]],[[{"text":"Total equity and liabilities","bold":true}],[{"text":"9,330","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Quick test:","bold":true},{"text":" opening inventory ₦1,300,000, purchases ₦9,062,000, sales ₦13,040,000, closing inventory ₦1,600,000. Cost of sales = 1,300 + 9,062 − 1,600 = 8,762; gross profit = "},{"text":"₦4,278,000","bold":true},{"text":". Add rent received 119; deduct depreciation (10% × furniture 300 = 30), irrecoverable debts 60, insurance 69, office 115, rates 21, general 225 (total 520): PBT = 4,278 + 119 − 520 = "},{"text":"₦3,877,000","bold":true},{"text":". Tax comes after this line."}]},{"text":[{"text":"Trap:","bold":true},{"text":" share capital is not an asset. PPE 80 + inventory 15 + receivables 10 + cash 5 = total assets "},{"text":"₦110m","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IAS 1 aims at comparability; it excludes condensed interim statements (IAS 34) and cash flow line items (IAS 7)."}]},{"text":[{"text":"Complete set: SFP, SPLOCI, SOCE, cash flows, notes, comparatives, plus an opening SFP after a material retrospective change. No directors' report."}]},{"text":[{"text":"Eight features: fair presentation, going concern (at least 12 months ahead), accrual, materiality and aggregation, no offsetting unless an IFRS allows, at least annual, comparatives (two of each statement), consistency."}]},{"text":[{"text":"Current: operating cycle, trading, within 12 months, unrestricted cash; liabilities also without a right at the year end to defer for 12 months. Deferred tax is non-current."}]},{"text":[{"text":"Post-year-end refinancing or waivers do not make a loan non-current."}]},{"text":[{"text":"TCI = profit + OCI; revaluation surplus and pension remeasurements are never reclassified; translation and cash flow hedge items are."}]},{"text":[{"text":"Nature or function; function users disclose depreciation and employee benefits. No extraordinary items."}]},{"text":[{"text":"SOCE: profit, OCI and owner transactions for each equity component."}]}]}],"theory":{"itemId":"f4e19e40-4af3-591f-8d76-5f95fbefdf81","question":[{"type":"paragraph","text":[{"text":"Owerri Mills Plc reports profit of ₦30m. OCI (net of tax): revaluation gain on land ₦5m, remeasurement$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 19, $study_guide$ loss on its defined benefit plan ₦1m, translation gain on a foreign operation ₦2m. Opening retained earnings ₦50m; dividends paid ₦8m. Find (a) TCI, (b) OCI that will not be reclassified, (c) closing retained earnings."}]}]},"practice":[{"topic":"IAS 1 Presentation of Financial Statements","named":false}]}},{"kind":"note","itemId":"95357e5d-cc6b-578b-a4d9-00193eb196be","sourceKey":"guide-topic:4","position":4,"payload":{"title":"IAS 2 Inventories","body":"The definition and scope; lower of cost and NRV; what goes into cost and what is kept out; FIFO, weighted average and specific identification (LIFO banned); NRV write-downs and reversals; expense recognition; disclosures; the computations.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The definition and scope; lower of cost and NRV; what goes into cost and what is kept out; FIFO, weighted average and specific identification (LIFO banned); NRV write-downs and reversals; expense recognition; disclosures; the computations."}],"lessons":[{"number":"4.1","title":"What inventories are, and the scope of IAS 2","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IAS 2","bold":true},{"text":" deals with "},{"text":"inventories","bold":true},{"text":" (their cost and measurement); borrowing costs are IAS 23."}]},{"text":[{"text":"Inventories:","bold":true},{"text":" assets (a) "},{"text":"held for sale in the ordinary course of business","bold":true},{"text":"; (b) "},{"text":"in the process of production for such sale","bold":true},{"text":"; or (c) "},{"text":"in the form of materials or supplies to be consumed in the production process or in the rendering of services","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"These are the "},{"text":"3 categories","bold":true},{"text":" in the definition:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Held for sale in the ordinary course of business (finished goods, goods bought for resale)."}]},{"text":[{"text":"In the process of production for such sale (work in progress)."}]},{"text":[{"text":"Materials or supplies to be consumed in production or in rendering services (raw materials, spare parts and consumables used in production)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Goods held for resale include a retailer's merchandise and "},{"text":"land and other property held for resale","bold":true},{"text":"."}]},{"text":[{"text":"Excluded from the scope of IAS 2 (2 items):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Financial instruments","bold":true},{"text":" (IAS 32 and IFRS 9)."}]},{"text":[{"text":"Biological assets related to agricultural activity and agricultural produce at the point of harvest","bold":true},{"text":" (IAS 41)."}]}]}]},{"text":[{"text":"IAS 2's "},{"text":"measurement","bold":true},{"text":" rules do not apply to producers of agricultural and forest products, agricultural produce after harvest and minerals measured at NRV under well-established industry practice, or to "},{"text":"commodity broker-traders","bold":true},{"text":" measuring at fair value less costs to sell."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classification depends on "},{"text":"purpose","bold":true},{"text":", not on what the item is. Ikeja Motors Ltd, a car dealer, holds 40 new cars in its showroom for sale (inventories, IAS 2) and 3 cars used by its sales staff (property, plant and equipment, IAS 16)."}]},{"text":[{"text":"A building is inventory only when it is "},{"text":"held for sale in the ordinary course of business","bold":true},{"text":", for example by a property developer such as Lekki Homes Plc. A head office is PPE (IAS 16); a building held to earn rental income is investment property (IAS 40). Cost or size never decides it."}]},{"text":[{"text":"Trap: \"assets held for use in the supply of goods over more than one period\" describes PPE, "},{"text":"not","bold":true},{"text":" one of the 3 inventory categories."}]},{"text":[{"text":"Trap: work in progress, raw materials, a retailer's goods and production spares are all "},{"text":"inside","bold":true},{"text":" IAS 2."}]}]}]},{"number":"4.2","title":"Measurement and the cost of inventories","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic rule:","bold":true},{"text":" inventories shall be measured at the "},{"text":"lower of cost and net realisable value (NRV)","bold":true},{"text":". Never the higher; never fair value less costs to sell (except broker-traders, above); no depreciation."}]},{"text":[{"text":"Cost of inventories","bold":true},{"text":" = Costs of purchase + Costs of conversion + Other costs incurred in bringing the inventories to their "},{"text":"present location and condition","bold":true},{"text":"."}]},{"text":[{"text":"Costs of purchase","bold":true},{"text":" = Purchase price + Import duties and other taxes (other than those "},{"text":"subsequently recoverable","bold":true},{"text":" from the tax authorities) + Transport + Handling + Other costs directly attributable to acquiring the goods − Trade discounts, rebates and similar items."}]},{"text":[{"text":"Costs of conversion","bold":true},{"text":" = Direct labour (and other costs directly related to units produced) + Systematic allocation of "},{"text":"fixed","bold":true},{"text":" and "},{"text":"variable","bold":true},{"text":" production overheads."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Fixed production overheads","bold":true},{"text":" (factory depreciation, maintenance, factory management) are allocated on the basis of "},{"text":"normal capacity","bold":true},{"text":". Unallocated fixed overhead (from low production or idle plant) is an "},{"text":"expense","bold":true},{"text":" in the period."}]},{"text":[{"text":"Rate = Fixed production overheads ÷ Normal capacity (units). If output is below normal: Amount expensed = Fix$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 20, $study_guide$ed overheads − (Actual units × Rate). If output is "},{"text":"abnormally high","bold":true},{"text":": Rate = Fixed overheads ÷ Actual units, so inventory is not measured above cost."}]},{"text":[{"text":"Variable production overheads","bold":true},{"text":" (indirect materials, indirect labour) are allocated on the "},{"text":"actual use","bold":true},{"text":" of the production facilities."}]}]}]},{"text":[{"text":"Other costs","bold":true},{"text":" are included only to the extent they bring inventories to their present location and condition, for example non-production overheads or the cost of designing products for specific customers."}]}]},{"type":"paragraph","text":[{"text":"Costs excluded from the cost of inventories (expense them when incurred), 4 items:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Abnormal amounts of wasted materials, labour or other production costs.","bold":true}]},{"text":[{"text":"Storage costs","bold":true},{"text":", unless those costs are "},{"text":"necessary in the production process before a further production stage","bold":true},{"text":"."}]},{"text":[{"text":"Administrative overheads","bold":true},{"text":" that do not contribute to bringing inventories to their present location and condition."}]},{"text":[{"text":"Selling costs.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Borrowing costs","bold":true},{"text":" are included only in the limited circumstances set by IAS 23 (Topic 8). Where goods are bought on "},{"text":"deferred settlement terms","bold":true},{"text":", the extra paid above normal credit price is "},{"text":"interest expense","bold":true},{"text":" over the financing period, not inventory cost."}]},{"text":[{"text":"Joint products:","bold":true},{"text":" shared costs are allocated on a rational, consistent basis (e.g. relative sales value); an immaterial "},{"text":"by-product","bold":true},{"text":" is measured at NRV and deducted from the main product's cost."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (purchase cost).","bold":true},{"text":" Kano Agro Traders Ltd imports goods: list price ₦2,400,000; trade discount 10% (₦240,000); non-recoverable import duty ₦180,000; recoverable VAT ₦162,000; carriage inwards ₦60,000; insurance in transit ₦20,000; advertising ₦50,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Net purchase price: ₦2,400,000 − ₦240,000 = ₦2,160,000"}]},{"text":[{"text":"Cost = ₦2,160,000 + duty ₦180,000 + carriage ₦60,000 + insurance ₦20,000 = "},{"text":"₦2,420,000","bold":true}]},{"text":[{"text":"Excluded: recoverable VAT (reclaimed, so not a cost) and advertising (a selling cost)."}]}]}]},{"text":[{"text":"Worked example (conversion cost).","bold":true},{"text":" Aba Leather Works Ltd makes a batch of bags: materials ₦1,500,000 (including ₦100,000 abnormal waste); direct labour ₦600,000; variable production overheads ₦250,000; fixed production overheads allocated at normal capacity ₦400,000; general administration ₦200,000; selling costs ₦150,000; storage of finished bags awaiting sale ₦80,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost = (₦1,500,000 − ₦100,000) + ₦600,000 + ₦250,000 + ₦400,000 = "},{"text":"₦2,650,000","bold":true}]},{"text":[{"text":"Abnormal waste, administration, selling and finished-goods storage are expensed."}]}]}]},{"text":[{"text":"Worked example (normal capacity).","bold":true},{"text":" Ogun Paints Ltd has fixed production overheads of ₦3,000,000. Normal capacity is 50,000 units."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Rate = ₦3,000,000 ÷ 50,000 = ₦60 per unit."}]},{"text":[{"text":"Low year, 40,000 units made: absorbed into inventory 40,000 × ₦60 = ₦2,400,000; expensed ₦3,000,000 − ₦2,400,000 = "},{"text":"₦600,000","bold":true},{"text":"."}]},{"text":[{"text":"Abnormally high year, 60,000 units made: rate falls to ₦3,000,000 ÷ 60,000 = ₦50 per unit, so no more than the ₦3,000,000 actually incurred is put into inventory."}]}]}]},{"text":[{"text":"Trap: direct labour and fixed overheads on normal capacity are "},{"text":"included","bold":true},{"text":". Storage between two production stages (e.g. maturing a product before bottling) is "},{"text":"included","bold":true},{"text":"; storage of finished goods awaiting sale is "},{"text":"not","bold":true},{"text":"."}]}]}]},{"number":"4.3","title":"Cost formulas: specific identification, FIFO and weighted average","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Specific identification:","bold":true},{"text":" specific costs attributed to identified items. It "},{"text":"must","bold":true},{"text":" be used for items "},{"text":"not ordinarily interchangeable","bold":true},{"text":" and goods or services "},{"text":"produced and segregated for specific projects","bold":true},{"text":" (e.g. custom jewellery made for a named customer)."}]},{"text":[{"text":"For all other items, use "},{"text":"FIFO","bold":true},{"text":" or "},{"text":"weighted average cost","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"FIFO (first-in, first-out):","bold":true},{"text":" items bought or made first are sold first, so "},{"text":"closing inventory = the most recent purchases","bold":true},{"text":"."}]},{"text":[{"text":"Weighted average cost:","bold":true},{"text":" cost of each item = weighted average of the cost of similar items at the start of the period and those bought or made during it. Calculated on a "},{"text":"periodic","bold":true},{"text":" basis or "},{"text":"as each additional shipment is received","bold":true},{"text":" (moving average)."}]},{"text":[{"text":"Periodic weighted average cost per unit = (Cost of opening inventory + Cost of purchases) ÷ (Opening units + Units purchased)."}]}]}]},{"text":[{"text":"LIFO (last-in, first-out) is NOT allowed","bold$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 21, $study_guide$":true},{"text":" under IAS 2."}]},{"text":[{"text":"Consistency:","bold":true},{"text":" use the "},{"text":"same cost formula for all inventories having a similar nature and use","bold":true},{"text":" to the entity. A different nature or use may justify a different formula; a different geographical location alone does "},{"text":"not","bold":true},{"text":"."}]},{"text":[{"text":"Standard cost","bold":true},{"text":" and the "},{"text":"retail method","bold":true},{"text":" may be used for convenience if the results "},{"text":"approximate cost","bold":true},{"text":". Retail method: Cost = Sales value of inventory − Gross margin at an appropriate percentage; it suits retailers with many fast-moving items with similar margins."}]},{"text":[{"text":"Units in closing inventory = Opening units + Units purchased − Units sold (or issued)."}]},{"text":[{"text":"Cost of sales = Opening inventory + Purchases − Closing inventory."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (FIFO and weighted average).","bold":true},{"text":" Ilorin Rice Mills Ltd: opening inventory 500 bags at ₦30,000; purchases 1,000 bags at ₦33,000, then 500 bags at ₦36,000. It sold 1,600 bags at ₦45,000 each."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total available: 500 + 1,000 + 500 = 2,000 bags; cost ₦15,000,000 + ₦33,000,000 + ₦18,000,000 = ₦66,000,000."}]},{"text":[{"text":"Closing units: 2,000 − 1,600 = 400 bags."}]},{"text":[{"text":"FIFO:","bold":true},{"text":" the 400 left are from the last purchase: 400 × ₦36,000 = "},{"text":"₦14,400,000","bold":true},{"text":". Cost of sales = ₦66,000,000 − ₦14,400,000 = "},{"text":"₦51,600,000","bold":true},{"text":"."}]},{"text":[{"text":"Weighted average (periodic):","bold":true},{"text":" ₦66,000,000 ÷ 2,000 = ₦33,000 per bag. Closing = 400 × ₦33,000 = "},{"text":"₦13,200,000","bold":true},{"text":". Cost of sales = ₦66,000,000 − ₦13,200,000 = "},{"text":"₦52,800,000","bold":true},{"text":"."}]},{"text":[{"text":"Revenue 1,600 × ₦45,000 = ₦72,000,000. Gross profit: FIFO ₦20,400,000; weighted average ₦19,200,000. With rising prices, FIFO gives the higher closing inventory and profit."}]}]}]},{"text":[{"text":"Issues spread through the year.","bold":true},{"text":" FIFO gives the same closing inventory whether you track each issue or work at the year end: find closing units, then price them from the latest purchases backwards. If 1,000 units remain and the last purchase was 1,200 units at ₦3.50, closing cost = 1,000 × ₦3.50 = ₦3,500."}]},{"text":[{"text":"Moving average","bold":true},{"text":" (recalculated on each receipt) can differ from periodic. Opening 100 units at ₦200 (₦20,000); buy 100 at ₦260 (₦26,000); new average ₦46,000 ÷ 200 = ₦230. Sell 150; 50 remain at ₦230 = ₦11,500. Buy 150 at ₦300 (₦45,000); new average (₦11,500 + ₦45,000) ÷ 200 = ₦282.50. Closing 200 units = "},{"text":"₦56,500","bold":true},{"text":". On a periodic basis: (₦20,000 + ₦26,000 + ₦45,000) ÷ 350 = ₦260; closing 200 × ₦260 = "},{"text":"₦52,000","bold":true},{"text":"."}]},{"text":[{"text":"Retail method.","bold":true},{"text":" Allen Avenue Mart Ltd counts closing inventory at selling price of ₦5,000,000; its gross margin is 20% of selling price. Cost = ₦5,000,000 × (100% − 20%) = "},{"text":"₦4,000,000","bold":true},{"text":"."}]},{"text":[{"text":"Trap: a retailer may "},{"text":"not","bold":true},{"text":" use LIFO and need "},{"text":"not","bold":true},{"text":" use specific identification for every item; the retail method is fine if it approximates cost. No switching formula each year."}]}]}]},{"number":"4.4","title":"Net realisable value, write-downs and reversals","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Net realisable value (NRV):","bold":true},{"text":" the estimated selling price in the ordinary course of business "},{"text":"less the estimated costs of completion","bold":true},{"text":" and "},{"text":"the estimated costs necessary to make the sale","bold":true},{"text":"."}]},{"text":[{"text":"NRV = Estimated selling price − Estimated costs of completion − Estimated costs to sell."}]},{"text":[{"text":"Write-down = Cost − NRV (only when NRV is below cost). Carrying amount = lower of cost and NRV."}]},{"text":[{"text":"Why cost may not be recoverable:","bold":true},{"text":" inventories are damaged; wholly or partly obsolete; selling prices have declined; or estimated costs of completion or of making the sale have increased."}]},{"text":[{"text":"Write-downs are normally made "},{"text":"item by item","bold":true},{"text":", or by "},{"text":"grouping similar or related items","bold":true},{"text":" where appropriate (same product line, similar end uses, produced and marketed in the same area, not practicable to evaluate separately). "},{"text":"Not","bold":true},{"text":" on a whole classification (e.g. all finished goods) or on total inventories."}]},{"text":[{"text":"Materials rule:","bold":true},{"text":" materials and supplies held for use in production are "},{"text":"not written down below cost","bold":true},{"text":" if the finished products they go into are expected to sell "},{"text":"at or above cost","bold":true},{"text":". If a fall in the price of materials shows that the finished products' cost will exceed NRV, the materials are written down, and "},{"text":"replacement cost","bold":true},{"text":" may be the best available measure of their NRV."}]},{"text":[{"text":"Firm sales contracts:","bold":true},{"text":" NRV of inventory held to satisfy firm contracts is based on the "},{"text":"contract price","bold":true},{"text":"; any quantity above the contract is based on general selling prices."}]},{"text":[{"text":"Reversal:","bold":true},{"text":" NRV is reassessed each period. If the causes of a write-down no longer exist or NRV has clearly risen, the write-down is "},{"text":"reversed","bold":true},{"text":", limited to the "},{"text":"original write-down","b$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 22, $study_guide$old":true},{"text":", so the new carrying amount is the "},{"text":"lower of cost and the revised NRV","bold":true},{"text":". Never above cost."}]},{"text":[{"text":"NRV is "},{"text":"entity-specific","bold":true},{"text":"; fair value is a market price."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Simple case.","bold":true},{"text":" Cost ₦10,000, NRV ₦8,000: written-down value is "},{"text":"₦8,000","bold":true},{"text":" (write-down ₦2,000)."}]},{"text":[{"text":"Worked example (completion costs).","bold":true},{"text":" Abeokuta Adire Ltd holds fabric costing ₦800,000. Expected selling price ₦900,000 after finishing costing ₦120,000; selling costs ₦60,000."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NRV = ₦900,000 − ₦120,000 − ₦60,000 = ₦720,000"}]},{"text":[{"text":"Write-down = ₦800,000 − ₦720,000 = "},{"text":"₦80,000","bold":true},{"text":"; carrying amount ₦720,000."}]},{"text":[{"text":"Trap: comparing cost with selling price alone (₦900,000) wrongly gives no write-down."}]}]}]},{"text":[{"text":"Worked example (per unit).","bold":true},{"text":" 200 phone cases cost ₦3,000 each; selling price ₦3,200; packaging and delivery ₦400 per unit. NRV per unit = ₦3,200 − ₦400 = ₦2,800, below cost. Carrying amount = 200 × ₦2,800 = "},{"text":"₦560,000","bold":true},{"text":"."}]},{"text":[{"text":"Worked example (item by item).","bold":true},{"text":" Gbagada Stores Ltd:"}]}]},{"type":"table","header":[[{"text":"Line"}],[{"text":"Cost (₦)"}],[{"text":"NRV (₦)"}],[{"text":"Lower (₦)"}]],"rows":[[[{"text":"A"}],[{"text":"400,000"}],[{"text":"520,000"}],[{"text":"400,000"}]],[[{"text":"B"}],[{"text":"300,000"}],[{"text":"240,000"}],[{"text":"240,000"}]],[[{"text":"C"}],[{"text":"150,000"}],[{"text":"180,000"}],[{"text":"150,000"}]],[[{"text":"Total"}],[{"text":"850,000"}],[{"text":"940,000"}],[{"text":"790,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Item by item gives ₦790,000 (write-down ₦60,000 on line B). Comparing totals (₦850,000 against ₦940,000) would wrongly hide B's loss."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Firm contract.","bold":true},{"text":" 1,000 cartons cost ₦4,500 each; 600 are under contract at ₦5,000; the general price is ₦4,200 (ignore selling costs). Carrying amount = 600 × ₦4,500 + 400 × ₦4,200 = "},{"text":"₦4,380,000","bold":true},{"text":"."}]},{"text":[{"text":"Materials rule in practice.","bold":true},{"text":" Agege Bakery Ltd's flour has fallen below cost on the market, but the bread made from it will still sell above total cost: the flour is "},{"text":"not written down","bold":true},{"text":"."}]},{"text":[{"text":"Worked example (reversal).","bold":true},{"text":" An item cost ₦500,000 and was written down to NRV of ₦420,000 last year. It is still held."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NRV now ₦540,000: reverse ₦80,000 only (back to cost ₦500,000), not ₦120,000."}]},{"text":[{"text":"NRV now ₦460,000: reverse ₦460,000 − ₦420,000 = ₦40,000; carrying amount ₦460,000."}]}]}]},{"text":[{"text":"Journal entries.","bold":true},{"text":" Write-down: Dr Cost of sales / Cr Inventory. Reversal: Dr Inventory / Cr Cost of sales."}]}]}]},{"number":"4.5","title":"Recognition as an expense, disclosures and the full computation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When inventories are "},{"text":"sold","bold":true},{"text":", their carrying amount is recognised as an "},{"text":"expense in the period in which the related revenue is recognised","bold":true},{"text":" (matching), not when bought, made or paid for."}]},{"text":[{"text":"Write-downs to NRV and all losses of inventories","bold":true},{"text":" (theft, fire, spoilage) are recognised as an "},{"text":"expense in the period the write-down or loss occurs","bold":true},{"text":"."}]},{"text":[{"text":"Reversals","bold":true},{"text":" of write-downs are recognised as a "},{"text":"reduction in the amount of inventories recognised as an expense","bold":true},{"text":" in the period the reversal occurs."}]},{"text":[{"text":"Inventory used as a component of self-constructed PPE is expensed over that asset's life."}]}]},{"type":"paragraph","text":[{"text":"Disclosures required by IAS 2:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The accounting policies adopted, including the "},{"text":"cost formula","bold":true},{"text":" used."}]},{"text":[{"text":"The "},{"text":"total carrying amount","bold":true},{"text":" of inventories and the carrying amount in classifications suitable to the entity (e.g. merchandise, production supplies, materials, work in progress, finished goods)."}]},{"text":[{"text":"The carrying amount of inventories carried at fair value less costs to sell."}]},{"text":[{"text":"The amount of inventories "},{"text":"recognised as an expense","bold":true},{"text":" during the period."}]},{"text":[{"text":"The amount of any "},{"text":"write-down","bold":true},{"text":" recognised as an expense."}]},{"text":[{"text":"The amount of any "},{"text":"reversal","bold":true},{"text":" of a write-down recognised as a reduction in expense."}]},{"text":[{"text":"The "},{"text":"circumstances or events","bold":true},{"text":" that led to the reversal."}]},{"text":[{"text":"The carrying amount of inventories "},{"text":"pledged as security","bold":true},{"text":" for liabilities."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Full computation (cost formula, NRV and profit).","bold":true},{"text":" Take Ilorin Rice Mills Ltd from Lesson 4.3 (FIFO). The 400 bags left have an estimated selling price of ₦40,000 each and costs to sell of ₦5,000 each. Operating expenses are ₦6,000,000."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"FIFO cost of closing inventory = ₦14,400,000."}]},{"text":[{"text":"NRV = 400 × (₦40,000 − ₦5,000) = ₦14,000,000."}]},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 23, $study_guide${"text":[{"text":"Closing inventory = lower = "},{"text":"₦14,000,000","bold":true},{"text":"; write-down ₦400,000."}]},{"text":[{"text":"Cost of sales = Opening ₦15,000,000 + Purchases ₦51,000,000 − Closing ₦14,000,000 = ₦52,000,000 (that is ₦51,600,000 FIFO cost of bags sold + ₦400,000 write-down)."}]},{"text":[{"text":"Gross profit = ₦72,000,000 − ₦52,000,000 = ₦20,000,000."}]},{"text":[{"text":"Profit before tax = ₦20,000,000 − ₦6,000,000 = "},{"text":"₦14,000,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"If NRV had been "},{"text":"above","bold":true},{"text":" FIFO cost, closing inventory would stay at cost and there would be no write-down: always compare first, then put the lower figure into cost of sales."}]},{"text":[{"text":"Trap: write-downs and theft losses are "},{"text":"both","bold":true},{"text":" expensed at once; they are never deferred, spread forward, taken to OCI or adjusted against opening retained earnings."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Inventories: held for sale; in production for sale; materials or supplies for production or services."}]},{"text":[{"text":"Outside IAS 2: financial instruments; biological assets and agricultural produce at harvest."}]},{"text":[{"text":"Measure at the "},{"text":"lower of cost and NRV","bold":true},{"text":", item by item."}]},{"text":[{"text":"Cost = purchase + conversion + other costs to bring to present location and condition; deduct trade discounts; exclude recoverable taxes."}]},{"text":[{"text":"Excluded: abnormal waste, most storage, non-contributing admin overheads, selling costs. Fixed overheads on normal capacity."}]},{"text":[{"text":"Specific identification for non-interchangeable or project items; otherwise FIFO or weighted average; "},{"text":"LIFO banned","bold":true},{"text":"; same formula for similar inventories."}]},{"text":[{"text":"NRV = selling price − costs of completion − costs to sell. Materials not written down if the finished product sells at or above cost."}]},{"text":[{"text":"Reversal capped at the original write-down; never above cost."}]},{"text":[{"text":"Expense on sale when revenue is recognised; write-downs and losses expensed at once."}]}]}],"theory":{"itemId":"d829ed04-b4f2-54c3-8629-41ef118db268","question":[{"type":"paragraph","text":[{"text":"Mushin Fabrics Ltd holds a batch of cloth costing ₦600,000. It is expected to sell for ₦650,000 after further dyeing costing ₦70,000, and selling costs of ₦30,000 will be incurred. At what amount should the cloth be measured, and what entry is needed?"}]}]},"practice":[{"topic":"IAS 2 Inventories","named":false}]}},{"kind":"note","itemId":"d48566b3-ac38-55a0-925c-8c926fabb819","sourceKey":"guide-topic:5","position":5,"payload":{"title":"IAS 8 Accounting Policies, Changes in Accounting Estimates and Errors","body":"Aim and definitions; selecting policies (the hierarchy) and consistency; changes in policy (retrospective); changes in estimates (prospective); prior period errors (retrospective restatement); impracticability; disclosures; computations.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Aim and definitions; selecting policies (the hierarchy) and consistency; changes in policy (retrospective); changes in estimates (prospective); prior period errors (retrospective restatement); impracticability; disclosures; computations."}],"lessons":[{"number":"5.1","title":"Aim, scope and key definitions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Aim (objective):","bold":true},{"text":" to prescribe the criteria for selecting and changing accounting policies, and the treatment and disclosure of changes in policies, changes in estimates and corrections of errors, to "},{"text":"enhance the relevance and reliability","bold":true},{"text":" of financial statements and their "},{"text":"comparability","bold":true},{"text":" with previous periods and with other entities."}]},{"text":[{"text":"3 areas:","bold":true},{"text":" (1) changes in accounting policies; (2) changes in accounting estimates; (3) errors. Events after the reporting period are "},{"text":"not","bold":true},{"text":" one of them (that is IAS 10)."}]},{"text":[{"text":"Accounting policies:","bold":true},{"text":" the specific principles, bases, conventions, rules and practices applied by an entity in preparing and presenting financial statements."}]},{"text":[{"text":"Accounting estimates:","bold":true},{"text":" monetary amounts in financial statements that are subject to measurement uncertainty (e.g. useful lives, residual values, allowance for doubtful debts, inventory obsolescence)."}]},{"text":[{"text":"Prior period errors:","bold":true},{"text":" omissions from, and misstatements in, the financial statements for one or more prior periods arising from a failure to use, or misuse of, reliable information that (a) was available when those statements were authorised for issue and (b) could reasonably be expected to have been obtained and taken into account."}]},{"text":[{"text":"Retrospective application:","bold":true},{"text":" applying a new accounting policy as if it had always been applied."}]},{"text":[{"text":"Retrospective restatement:","bold":true},{"text":" correcting amounts as if a prior period error had never occurred."}]},{"text":[{"text":"Prospective application:","bold":true},{"text":" applying the change to current and future periods only."}]},{"text":[{"text":"Impracticable:","bold":true},{"text":" the entity cannot apply a requirement after making every reasonable effort to do so."}]},{"text":[{"text":"Material:","bold":true},{"text":" information is material if omitting, misstating or obscuring it could reasonably be expected to influence decisions that primary users make on the basis of those financial statements. Materiality is judged by the "},{"text":"size or nature","bold":true},{"text":" of the item, or both, in the surrounding circumstances."}]}]},{"type":"table","header":[[{"tex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 24, $study_guide$t":"Item"}],[{"text":"Treatment"}]],"rows":[[[{"text":"Change in accounting policy"}],[{"text":"Retrospective application"}]],[[{"text":"Change in accounting estimate"}],[{"text":"Prospective"}]],[[{"text":"Prior period error"}],[{"text":"Retrospective restatement"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Watch the two \"retrospective\" words: "},{"text":"application","italic":true},{"text":" goes with a "},{"text":"policy","bold":true},{"text":", "},{"text":"restatement","italic":true},{"text":" goes with an "},{"text":"error","bold":true},{"text":". Options swap them."}]},{"text":[{"text":"A policy is the "},{"text":"rule","bold":true},{"text":" (\"inventory at weighted average cost\"); an estimate is the "},{"text":"amount","bold":true},{"text":" the rule needs under uncertainty (\"this lorry lasts 8 years\"). An option calling policies monetary amounts and estimates rules has them backwards."}]},{"text":[{"text":"Older wording defines a "},{"text":"change in accounting estimate","italic":true},{"text":" as an adjustment of the carrying amount of an asset or liability, or of an asset's periodic consumption, from assessing their present status and expected future benefits and obligations. The treatment is the same."}]}]}]},{"number":"5.2","title":"Selecting and applying accounting policies","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Where an IFRS applies:","bold":true},{"text":" the policy for that item must be determined by applying that Standard or Interpretation and any relevant implementation guidance. Policies need not be applied where the effect is immaterial."}]},{"text":[{"text":"Where no IFRS applies:","bold":true},{"text":" management uses its judgement to develop and apply a policy that gives information that is:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"relevant","bold":true},{"text":" to users' economic decision-making needs; and"}]},{"text":[{"text":"reliable","bold":true},{"text":", in that the financial statements:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"represent faithfully the financial position, financial performance and cash flows;"}]},{"text":[{"text":"reflect the "},{"text":"economic substance","bold":true},{"text":" of transactions, not merely their legal form;"}]},{"text":[{"text":"are "},{"text":"neutral","bold":true},{"text":" (free from bias);"}]},{"text":[{"text":"are "},{"text":"prudent","bold":true},{"text":";"}]},{"text":[{"text":"are "},{"text":"complete","bold":true},{"text":" in all material respects."}]}]}]}]}]},{"text":[{"text":"The hierarchy (order management refers to):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"First:","bold":true},{"text":" requirements in IFRSs dealing with "},{"text":"similar and related issues","bold":true},{"text":";"}]},{"text":[{"text":"Then:","bold":true},{"text":" the definitions, recognition criteria and measurement concepts for assets, liabilities, income and expenses in the "},{"text":"Conceptual Framework","bold":true},{"text":";"}]},{"text":[{"text":"May also consider:","bold":true},{"text":" recent pronouncements of other standard-setting bodies using a similar framework, other accounting literature and accepted industry practices, so far as they do not conflict with 1 and 2."}]}]}]},{"text":[{"text":"Consistency:","bold":true},{"text":" apply consistent policies for similar transactions, other events and conditions, "},{"text":"unless","bold":true},{"text":" an IFRS specifically requires or permits categorisation of items for which different policies may be appropriate."}]},{"text":[{"text":"It is "},{"text":"inappropriate","bold":true},{"text":" to make, or leave uncorrected, immaterial departures from IFRSs to achieve a particular presentation of financial position, performance or cash flows."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Kano Agro Ltd meets a transaction no IFRS covers. It must not omit it, copy the tax treatment, or pick \"any policy and disclose it\"; it uses judgement, working down the hierarchy."}]},{"text":[{"text":"Traps: the Conceptual Framework is "},{"text":"second","bold":true},{"text":", after similar IFRSs; industry practice is optional support; reflecting "},{"text":"legal form rather than substance","bold":true},{"text":" is not reliable."}]},{"text":[{"text":"IAS 16 lets land and buildings be revalued while vehicles stay at cost: permitted categorisation, not inconsistency."}]}]}]},{"number":"5.3","title":"Changes in accounting policy","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Frequent changes are undesirable because they make comparison with previous periods harder. An entity changes a policy "},{"text":"only if","bold":true},{"text":" the change:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"is "},{"text":"required by an IFRS","bold":true},{"text":"; or"}]},{"text":[{"text":"results in financial statements providing "},{"text":"reliable and more relevant","bold":true},{"text":" information."}]}]}]},{"text":[{"text":"A change in policy is a change in the "},{"text":"recognition","bold":true},{"text":", "},{"text":"measurement","bold":true},{"text":" or "},{"text":"presentation","bold":true},{"text":" basis:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Recognition:","bold":true},{"text":" e.g. capitalising expenditure previously written off."}]},{"text":[{"text":"Measurement:","bold":true},{"text":" e.g. cost model to fair value model for investment property; FIFO to weighted average."}]},{"text":[{"text":"Presentation:","bold":true},{"text":" e.g. reclassifying costs from administrative expenses to cost of sales."}]}]}]},{"text":[{"text":"Not a change in policy (2):","bold":true},{"text":" (1) applying a policy to transactions that "},{"text":"differ in substance","bold":t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 25, $study_guide$rue},{"text":" from those previously occurring; (2) applying a new policy to transactions that "},{"text":"did not occur before","bold":true},{"text":" or were immaterial."}]},{"text":[{"text":"Initial revaluation","bold":true},{"text":" under IAS 16 or IAS 38 "},{"text":"is","bold":true},{"text":" a change in policy, but it is accounted for under IAS 16/IAS 38 (as a revaluation), "},{"text":"not","bold":true},{"text":" retrospectively under IAS 8."}]},{"text":[{"text":"How to apply:","bold":true},{"text":" follow the IFRS's specific "},{"text":"transitional provisions","bold":true},{"text":". If there are none, or the change is voluntary, apply it "},{"text":"retrospectively","bold":true},{"text":": adjust the "},{"text":"opening balance of each affected component of equity for the earliest prior period presented","bold":true},{"text":", and the other comparative amounts, as if the new policy had always been applied."}]},{"text":[{"text":"IAS 1 then requires a "},{"text":"third statement of financial position","bold":true},{"text":" at the "},{"text":"beginning of the earliest comparative period","bold":true},{"text":" (where the effect on it is material)."}]},{"text":[{"text":"Impracticable for a prior period","bold":true},{"text":" when (3): (a) the effects are not determinable; (b) it needs assumptions about management's intent in that period; (c) it needs significant estimates that cannot be objectively separated from information that came later. If so, apply from the "},{"text":"earliest date that is practicable","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Disclosures","bold":true}]},{"type":"table","header":[[{"text":"Disclosure"}],[{"text":"Required by IFRS"}],[{"text":"Voluntary"}]],"rows":[[[{"text":"Title of the Standard or Interpretation"}],[{"text":"Yes"}],[]],[[{"text":"Nature of the change"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"Description of transitional provisions"}],[{"text":"Yes"}],[]],[[{"text":"Reason the new policy gives reliable and more relevant information"}],[],[{"text":"Yes"}]],[[{"text":"Adjustment to each line item (and EPS) for current and prior periods, so far as practicable"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"Adjustment relating to periods before those presented, so far as practicable"}],[{"text":"Yes"}],[{"text":"Yes"}]],[[{"text":"If retrospective application is impracticable: why, and how and from when applied"}],[{"text":"Yes"}],[{"text":"Yes"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"New IFRS issued but not yet effective:","bold":true},{"text":" IAS 8 "},{"text":"requires","bold":true},{"text":" disclosure of that fact and of known or reasonably estimable information on its likely impact."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ibadan Foods Plc changing policy only to hit a profit bonus: "},{"text":"not permitted","bold":true},{"text":". Shareholder, auditor or accountant approval is not a ground either."}]},{"text":[{"text":"Enugu Steel Ltd buys its "},{"text":"first","bold":true},{"text":" investment property and picks the fair value model: not a change in policy. Nor is capitalising development costs because a project "},{"text":"becomes eligible for the first time","bold":true},{"text":"."}]},{"text":[{"text":"Jos Textiles Plc, year ended 31 December 2025, one year of comparatives, retrospective change: statements of financial position at "},{"text":"31 December 2025, 31 December 2024 and 1 January 2024","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 1 (cost model to fair value model).","bold":true},{"text":" Eko Holdings Plc bought an investment property for ₦60,000,000 on 1 January 2024 and used the cost model, depreciating ₦1,500,000 a year. In 2026 it voluntarily changes to the fair value model, presenting 2025 comparatives. Fair value: ₦66,000,000 at 31 December 2024; ₦70,000,000 at 31 December 2025. Ignore tax."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost-model carrying amount at 31 December 2024 = ₦60,000,000 − ₦1,500,000 = ₦58,500,000."}]},{"text":[{"text":"Adjustment to retained earnings at 1 January 2025 = ₦66,000,000 − ₦58,500,000 = "},{"text":"increase of ₦7,500,000","bold":true},{"text":" (Dr Investment property; Cr Retained earnings b/f)."}]},{"text":[{"text":"Restated 2025 profit: remove depreciation ₦1,500,000; add fair value gain ₦70,000,000 − ₦66,000,000 = ₦4,000,000. Profit is "},{"text":"₦5,500,000 higher","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 2 (FIFO to weighted average).","bold":true},{"text":" Ilupeju Chemicals Ltd changes from FIFO to weighted average in 2026, with 2025 comparatives. Inventory at 31 December 2024: FIFO ₦12,000,000, weighted average ₦11,000,000. At 31 December 2025: FIFO ₦15,000,000, weighted average ₦13,200,000. 2025 profit under FIFO was ₦30,000,000. Ignore tax."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Adjustment to retained earnings at 1 January 2025 = ₦11,000,000 − ₦12,000,000 = "},{"text":"decrease of ₦1,000,000","bold":true},{"text":"."}]},{"text":[{"text":"2025: lower opening inventory reduces cost of sales (+₦1,000,000); lower closing inventory increases cost of sales (−₦1,800,000). Net −₦800,000."}]},{"text":[{"text":"Restated 2025 profit = ₦30,000,000 + ₦1,000,000 − ₦1,800,000 = "},{"text":"₦29,200,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Rule to remember: closing inventory down = profit down; opening inventory down = profit up."}]}]},{"number":"5.4","title":"Changes in accounting estimates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"An estimate is needed when an item "},{"text":"cannot be measured with precision","bold":true},{"text":" and there is some uncertainty. Reasonable estimates do "},{"text":"not","bold":true},{"text":" undermine reliability."}]},{"text":[{"text":"Examples:","bold":true},{"text":" inventory$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 26, $study_guide$ obsolescence; fair value of financial assets or liabilities; useful lives of non-current assets; residual values; the depreciation method (pattern of consumption); allowance for doubtful debts; warranty obligations."}]},{"text":[{"text":"A change in estimate results from "},{"text":"new information or new developments","bold":true},{"text":", so it is "},{"text":"not","bold":true},{"text":" the correction of an error."}]},{"text":[{"text":"A change in "},{"text":"measurement basis","bold":true},{"text":" (e.g. cost model to revaluation or fair value model) is a change in "},{"text":"policy","bold":true},{"text":", not estimate."}]},{"text":[{"text":"A change in "},{"text":"depreciation method","bold":true},{"text":" (straight line to reducing balance) is a change in "},{"text":"estimate","bold":true},{"text":"."}]},{"text":[{"text":"If it is "},{"text":"difficult to distinguish","bold":true},{"text":" a policy change from an estimate change, treat it as a change in "},{"text":"estimate","bold":true},{"text":"."}]},{"text":[{"text":"Prospective recognition","bold":true},{"text":" in profit or loss of:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the "},{"text":"period of change only","bold":true},{"text":", if it affects that period only; or"}]},{"text":[{"text":"the "},{"text":"period of change and future periods","bold":true},{"text":", if it affects both."}]}]}]},{"text":[{"text":"Where it changes assets or liabilities, adjust their "},{"text":"carrying amount in the period of change","bold":true},{"text":"."}]},{"text":[{"text":"Formula:","bold":true},{"text":" Revised depreciation = (Carrying amount at date of change − Revised residual value) ÷ Remaining useful life."}]},{"text":[{"text":"Disclose:","bold":true},{"text":" the nature and amount of the change affecting the current period or expected to affect future periods (or that the future effect is impracticable to estimate). No IFRS title, \"more relevant\" reason or restated comparatives."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Owerri Bottling Ltd switches vans from straight line to reducing balance: "},{"text":"estimate","bold":true},{"text":", prospective. An entity "},{"text":"can","bold":true},{"text":" change method."}]},{"text":[{"text":"Moving where depreciation is "},{"text":"presented","bold":true},{"text":" in profit or loss is a "},{"text":"presentation","bold":true},{"text":" change: a "},{"text":"policy","bold":true},{"text":", not estimate."}]},{"text":[{"text":"Ilorin Cement Plc cuts a kiln's life from 15 to 10 years on new wear information: estimate, not error."}]},{"text":[{"text":"Kaduna Motors Ltd revises an estimate affecting only this year: current period only."}]}]},{"type":"paragraph","text":[{"text":"Worked example 3 (useful life).","bold":true},{"text":" Ikorodu Plastics Ltd bought a machine for ₦24,000,000, straight line, 10 years, nil residual value. At the start of Year 5 (after 4 years) the "},{"text":"remaining","bold":true},{"text":" life is revised to 3 years."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Old charge = ₦24,000,000 ÷ 10 = ₦2,400,000. Carrying amount after 4 years = ₦24,000,000 − (4 × ₦2,400,000) = ₦14,400,000."}]},{"text":[{"text":"Year 5 charge = ₦14,400,000 ÷ 3 = "},{"text":"₦4,800,000","bold":true},{"text":"; Year 5 profit is ₦2,400,000 lower than under the old estimate."}]},{"text":[{"text":"Carrying amount at end of Year 5 = ₦14,400,000 − ₦4,800,000 = "},{"text":"₦9,600,000","bold":true},{"text":"."}]},{"text":[{"text":"Trap: if the "},{"text":"total","bold":true},{"text":" life is revised to 8 years, remaining life = 8 − 4 = 4, charge = ₦14,400,000 ÷ 4 = ₦3,600,000. Convert total life to remaining life; never re-spread cost from the start."}]}]},{"type":"paragraph","text":[{"text":"Worked example 4 (residual value).","bold":true},{"text":" Apapa Shipping Ltd's crane cost ₦40,000,000, residual value ₦4,000,000, 9 years straight line. At the start of Year 4 the residual value is revised to ₦10,000,000; total life unchanged."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Old charge = (₦40,000,000 − ₦4,000,000) ÷ 9 = ₦4,000,000. Carrying amount after 3 years = ₦40,000,000 − ₦12,000,000 = ₦28,000,000."}]},{"text":[{"text":"Year 4 charge = (₦28,000,000 − ₦10,000,000) ÷ 6 = "},{"text":"₦3,000,000","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 5 (method).","bold":true},{"text":" Oshodi Couriers Ltd's van cost ₦20,000,000, straight line over 5 years, nil residual. At the start of Year 2 it changes to reducing balance at 30%. Carrying amount = ₦20,000,000 − ₦4,000,000 = ₦16,000,000; Year 2 charge = 30% × ₦16,000,000 = "},{"text":"₦4,800,000","bold":true},{"text":". No restatement of Year 1."}]}]},{"number":"5.5","title":"Prior period errors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Errors include (5):","bold":true},{"text":" mathematical mistakes; mistakes in applying accounting policies; oversights; misinterpretations of facts; fraud."}]},{"text":[{"text":"Material prior period errors","bold":true},{"text":" are corrected "},{"text":"retrospectively","bold":true},{"text":" in the first set of financial statements authorised for issue after their discovery, by:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"restating the "},{"text":"comparative amounts","bold":true},{"text":" for the prior period(s) in which the error occurred; or"}]},{"text":[{"text":"if the error occurred before the earliest prior period presented, restating the "},{"text":"opening balances","bold":true},{"text":" of assets, liabilities and equity for the earliest prior period presented."}]}]}]},{"text":[{"text":"The correction is "},{"text":"excluded from profit or loss of the period of discovery","bold":true},{"text":"."}]},{"text":[{"text":"If impracticable, restate from the earliest date practicable (tests as in $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 27, $study_guide$Lesson 5.3)."}]},{"text":[{"text":"Errors found "},{"text":"before","bold":true},{"text":" the statements are authorised for issue are simply corrected in those statements."}]},{"text":[{"text":"Disclose:","bold":true},{"text":" (1) nature of the error; (2) for each prior period presented, so far as practicable, the correction to each line item (and basic and diluted EPS); (3) the correction at the beginning of the earliest prior period presented; (4) if impracticable, the circumstances and how and from when corrected. These need not be repeated in later periods."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Aba Leather Ltd's 2024 depreciation was understated by a clerk's keying mistake with the information available: "},{"text":"error","bold":true},{"text":" (contrast Ilorin Cement's new information: estimate)."}]},{"text":[{"text":"Timing trap: 2017 depreciation found overstated on 25 March 2018. Statements authorised 1 April 2018: "},{"text":"correct the 2017 statements before issue","bold":true},{"text":". Authorised 1 March 2018: "},{"text":"restate 2017 in the 2018 comparatives","bold":true},{"text":". Never just \"reduce 2018 depreciation\"."}]}]},{"type":"paragraph","text":[{"text":"Worked example 6.","bold":true},{"text":" Preparing its 2026 statements, Mushin Distributors Ltd finds three material 2025 errors. Originally reported: 2025 profit ₦18,000,000; retained earnings at 31 December 2025 ₦40,000,000. Ignore tax; treat each error separately."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"(a) Closing inventory at 31 December 2025 overstated by ₦2,000,000 (counting mistake), so cost of sales was understated: restated 2025 profit = ₦18,000,000 − ₦2,000,000 = "},{"text":"₦16,000,000","bold":true},{"text":"."}]},{"text":[{"text":"(b) Repairs of ₦2,500,000 wrongly capitalised as PPE in 2025 (ignore depreciation). Restated retained earnings at 1 January 2026 = ₦40,000,000 − ₦2,500,000 = "},{"text":"₦37,500,000","bold":true},{"text":" (Dr Retained earnings b/f ₦2,500,000; Cr PPE ₦2,500,000)."}]},{"text":[{"text":"(c) Depreciation of ₦1,200,000 omitted from 2025. Restate 2025 profit to ₦18,000,000 − ₦1,200,000 = "},{"text":"₦16,800,000","bold":true},{"text":"; "},{"text":"no","bold":true},{"text":" charge in 2026 profit or loss."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IAS 8 aims at relevance, reliability and comparability; it covers policies, estimates and errors."}]},{"text":[{"text":"Policy = principles, bases, conventions, rules and practices; estimate = monetary amount subject to measurement uncertainty."}]},{"text":[{"text":"No IFRS? Judgement: relevant and reliable; look first to similar IFRSs, then the Conceptual Framework."}]},{"text":[{"text":"Change a policy only if required by IFRS or reliable and more relevant; never to raise profit."}]},{"text":[{"text":"Policy change: transitional provisions, else retrospective; adjust opening equity of the earliest period presented; third statement of financial position. First-time revaluation follows IAS 16/IAS 38."}]},{"text":[{"text":"Estimate change (life, residual value, depreciation method): prospective; charge = (carrying amount − residual) ÷ remaining life."}]},{"text":[{"text":"Doubtful? Treat as estimate. Measurement-basis change = policy."}]},{"text":[{"text":"Material prior period error: retrospective restatement of comparatives, not through current profit."}]},{"text":[{"text":"Impracticable = cannot after every reasonable effort; then apply from the earliest practicable date."}]}]}],"theory":{"itemId":"04a47742-4e01-5f38-a479-e4dd51f113ff","question":[{"type":"paragraph","text":[{"text":"Kogi Power Ltd's generator cost ₦36,000,000, residual value ₦4,000,000, straight line over 8 years. At the start of Year 4 the remaining life is revised to 4 years and the residual value to ₦2,000,000. Classify the change, and compute the Year 4 charge and its effect on profit."}]}]},"practice":[{"topic":"IAS 8 Accounting Policies, Estimates and Errors","named":false}]}},{"kind":"note","itemId":"11c06bb8-026f-5ecc-ab6e-175cd9a7b969","sourceKey":"guide-topic:6","position":6,"payload":{"title":"IAS 16 Property, Plant and Equipment","body":"What PPE is and when it is recognised; what goes into (and stays out of) its cost; subsequent costs; the cost and revaluation models; depreciation, its causes and methods (with formulas); reviews of useful life and residual value; disposal gains and losses; disclosures.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What PPE is and when it is recognised; what goes into (and stays out of) its cost; subsequent costs; the cost and revaluation models; depreciation, its causes and methods (with formulas); reviews of useful life and residual value; disposal gains and losses; disclosures."}],"lessons":[{"number":"6.1","title":"Objective, definitions and recognition","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Objective:","bold":true},{"text":" to prescribe the accounting treatment for PPE so that users can "},{"text":"discern information about an entity's investment in its PPE and the changes in that investment","bold":true},{"text":". The principal issues are recognition of the assets, determining their carrying amounts, and the depreciation charges and impairment losses to recognise."}]},{"text":[{"text":"Property, plant and equipment:","bold":true},{"text":" "},{"text":"tangible","bold":true},{"text":" items that (a) are held for use in the production or supply of goods or services, for rental to others, or for administrative purposes; and (b) are expected to be used during "},{"text":"more than one period","bold":true},{"text":"."}]},{"text":[{"text":"Cost:","bold":true},{"text":" the amount of cash or cash equivalents paid, or the fair value of the other consideration given, to acquire an asset at the time of its acquisition or construction."}]},{"text":[{"text":"Depreciable amount:","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 28, $study_guide$ld":true},{"text":" the cost of an asset, or other amount substituted for cost, less its residual value."}]},{"text":[{"text":"Depreciation:","bold":true},{"text":" the systematic allocation of the depreciable amount of an asset over its useful life."}]},{"text":[{"text":"Accumulated depreciation:","bold":true},{"text":" total depreciation charged from the start to a given date."}]},{"text":[{"text":"Carrying amount:","bold":true},{"text":" the amount at which an asset is recognised after deducting any accumulated depreciation and accumulated impairment losses."}]},{"text":[{"text":"Fair value:","bold":true},{"text":" the price that would be received to sell an asset or paid to transfer a liability in an orderly transaction between market participants at the measurement date (IFRS 13)."}]},{"text":[{"text":"Impairment loss:","bold":true},{"text":" the amount by which the carrying amount of an asset exceeds its recoverable amount."}]},{"text":[{"text":"Recoverable amount:","bold":true},{"text":" the "},{"text":"higher","bold":true},{"text":" of an asset's fair value less costs of disposal and its value in use."}]},{"text":[{"text":"Residual (scrap) value:","bold":true},{"text":" the estimated amount an entity would currently obtain from disposal of the asset, after deducting estimated costs of disposal, if the asset were already of the age and in the condition expected at the end of its useful life."}]},{"text":[{"text":"Useful life:","bold":true},{"text":" (a) the period over which an asset is expected to be available for use; or (b) the number of production or similar units expected to be obtained from it."}]}]},{"type":"paragraph","text":[{"text":"Recognition:","bold":true},{"text":" the cost of an item of PPE is recognised as an asset if, and only if:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"it is "},{"text":"probable","bold":true},{"text":" that future economic benefits associated with the item will flow to the entity; and"}]},{"text":[{"text":"the cost of the item can be "},{"text":"measured reliably","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classification depends on "},{"text":"use","bold":true},{"text":", not on what the item is. Ikeja Motors Ltd sells cars: its showroom building is PPE, but the cars on display for sale are "},{"text":"inventories","bold":true},{"text":" (IAS 2). Cash and receivables are financial assets, never PPE."}]},{"text":[{"text":"Spare parts and stand-by equipment are PPE if used for more than one period; otherwise inventory."}]},{"text":[{"text":"Trap: recoverable amount is the "},{"text":"higher","bold":true},{"text":" of the two figures, not the lower. An impairment loss arises when carrying amount is "},{"text":"above","bold":true},{"text":" recoverable amount, never the other way round. Impairment itself is measured under IAS 36."}]},{"text":[{"text":"Trap: recognition needs no full payment, insurance or minimum value."}]}]}]},{"number":"6.2","title":"Initial measurement: elements of cost","mustKnow":[{"type":"paragraph","text":[{"text":"PPE is measured at "},{"text":"cost","bold":true},{"text":" on initial recognition. Cost comprises:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Purchase price","bold":true},{"text":", including import duties and "},{"text":"non-refundable","bold":true},{"text":" purchase taxes, after deducting trade discounts and rebates."}]},{"text":[{"text":"Directly attributable costs","bold":true},{"text":" of bringing the asset to the location and condition necessary for it to operate as management intends. These are costs that "},{"text":"would have been avoided if the asset had not been bought or built","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"employee benefits arising directly from the construction or acquisition;"}]},{"text":[{"text":"site preparation;"}]},{"text":[{"text":"initial delivery and handling;"}]},{"text":[{"text":"installation and assembly;"}]},{"text":[{"text":"testing whether the asset is functioning properly;"}]},{"text":[{"text":"professional fees (e.g. legal fees, architects, engineers)."}]}]}]},{"text":[{"text":"The "},{"text":"initial estimate of the costs of dismantling and removing","bold":true},{"text":" the item and restoring the site, "},{"text":"discounted to present value","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Excluded from cost (expense them):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"repairs, renewals, repainting and day-to-day servicing;"}]},{"text":[{"text":"administration and general overheads;"}]},{"text":[{"text":"staff training costs;"}]},{"text":[{"text":"wastage and other abnormal costs (e.g. materials wasted in an accident);"}]},{"text":[{"text":"costs of opening a new facility, introducing a new product (including advertising) or doing business in a new location or with a new class of customer;"}]},{"text":[{"text":"costs incurred after the asset is ready for use (including while it is idle or running below capacity), initial operating losses, and relocation or reorganisation costs;"}]},{"text":[{"text":"recoverable taxes (e.g. recoverable VAT)."}]}]},{"type":"paragraph","text":[{"text":"Capitalisation stops when the asset is ready for use","bold":true},{"text":" (capable of operating as intended), even if it is not brought into use until later."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1 (motor vehicle and premises).","bold":true},{"text":" Motor car ₦4,500,000; registration number ₦150,000; road licence fees ₦25,000; delivery of the car ₦35,000; testing the car ₦100,000; purchase of office premises ₦8,000,000; legal fees on the office ₦800,000; driver's wages for the first year ₦1,200,000."}]},{"type":"table","header":[[{"text":"Motor vehicle"}],[{"text":"₦"}]],"rows":[[[{"text":"Motor car"}],[{"text":"4,500,$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 29, $study_guide$000"}]],[[{"text":"Registration number (one-off, needed to put the car on the road)"}],[{"text":"150,000"}]],[[{"text":"Delivery charge"}],[{"text":"35,000"}]],[[{"text":"Testing"}],[{"text":"100,000"}]],[[{"text":"Cost capitalised","bold":true}],[{"text":"4,785,000","bold":true}]]]},{"type":"paragraph","text":[{"text":"Road licence (₦25,000, a recurring running cost) and driver's wages (₦1,200,000) are expensed. Office premises = 8,000,000 + legal fees 800,000 = "},{"text":"₦8,800,000","bold":true},{"text":" (legal fees are professional fees)."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (imported machine).","bold":true},{"text":" Ilupeju Packaging Plc buys a machine: list price ₦8,000,000; trade discount ₦400,000; import duty ₦600,000; recoverable VAT ₦600,000; delivery ₦150,000; installation ₦250,000; testing ₦100,000; staff training ₦200,000; allocated administration overheads ₦120,000. It must remove the machine and restore the site in 8 years at an estimated ₦1,200,000, with a present value of ₦500,000."}]},{"type":"paragraph","text":[{"text":"Cost = 8,000,000 − 400,000 + 600,000 + 150,000 + 250,000 + 100,000 + 500,000 = "},{"text":"₦9,200,000","bold":true},{"text":". Excluded: recoverable VAT, training, overheads, and the undiscounted ₦1,200,000 (only the present value goes in). Journal: Dr Machine 9,200,000; Cr Bank/Payables 8,700,000; Cr Provision for dismantling 500,000."}]},{"type":"paragraph","text":[{"text":"Worked example 3 (self-constructed asset).","bold":true},{"text":" Ogun Cement Plc builds its own warehouse: materials used ₦6,000,000; wages of staff working directly on it ₦2,000,000; materials wasted in an abnormal accident ₦400,000; site preparation ₦700,000; architect's fees ₦300,000; general company overheads ₦500,000. Cost = 6,000,000 + 2,000,000 + 700,000 + 300,000 = "},{"text":"₦9,000,000","bold":true},{"text":". Abnormal waste and general overheads are expensed."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Ready for use trap:","bold":true},{"text":" Lekki Bottling Ltd's line is capable of operating on 1 March, first used on 1 June, and runs below capacity for two months. Capitalisation stops on "},{"text":"1 March","bold":true},{"text":"; later costs are expensed. Low demand does not justify further capitalisation."}]},{"text":[{"text":"Deferred payment beyond normal credit: cost is the "},{"text":"cash price equivalent","bold":true},{"text":" (the rest is interest). Asset received in exchange: cost is normally "},{"text":"fair value","bold":true},{"text":". Sales of items produced while testing go to profit or loss."}]}]}]},{"number":"6.3","title":"Subsequent costs and the measurement models","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Subsequent expenditure","bold":true},{"text":" is capitalised only when it meets the recognition criteria, that is, it "},{"text":"enhances the benefits of the asset","bold":true},{"text":" (more output, longer life, better quality, more revenue). Replacing a major part (a new engine, a new roof) is capitalised and the carrying amount of the replaced part is derecognised."}]},{"text":[{"text":"Day-to-day servicing","bold":true},{"text":" (repairs, maintenance, repainting) is "},{"text":"expensed","bold":true},{"text":"."}]},{"text":[{"text":"After recognition an entity chooses, "},{"text":"for each entire class","bold":true},{"text":" of PPE:"}]}]},{"type":"table","header":[[],[{"text":"Cost model"}],[{"text":"Revaluation model"}]],"rows":[[[{"text":"Carried at"}],[{"text":"Cost less accumulated depreciation and accumulated impairment losses"}],[{"text":"Fair value at revaluation date less subsequent accumulated depreciation and impairment losses"}]],[[{"text":"Condition"}],[{"text":"None"}],[{"text":"Fair value can be measured reliably"}]],[[{"text":"Frequency"}],[{"text":"Not applicable"}],[{"text":"Regular enough that carrying amount does not differ materially from fair value"}]],[[{"text":"Scope"}],[{"text":"Class"}],[{"text":"Entire class","bold":true},{"text":" to which the asset belongs"}]]]},{"type":"paragraph","text":[{"text":"Revaluation rules:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Increase:","bold":true},{"text":" recognised in "},{"text":"other comprehensive income","bold":true},{"text":" and accumulated in equity as "},{"text":"revaluation surplus","bold":true},{"text":", except that it goes to profit or loss to the extent it reverses a previous revaluation decrease of the same asset charged to profit or loss."}]},{"text":[{"text":"Decrease:","bold":true},{"text":" recognised in "},{"text":"profit or loss","bold":true},{"text":", except that it goes to OCI (reducing the surplus) to the extent of any credit balance in the revaluation surplus for "},{"text":"that same asset","bold":true},{"text":"."}]},{"text":[{"text":"The surplus may be transferred "},{"text":"directly to retained earnings","bold":true},{"text":" as the asset is used (excess depreciation) or on derecognition. It never passes through profit or loss."}]}]},{"type":"paragraph","text":[{"text":"Revaluation surplus = Fair value − Carrying amount at revaluation date."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4 (subsequent costs).","bold":true},{"text":" A bus has a carrying amount of ₦3,000,000. Ibadan Transit Ltd spends ₦1,200,000 on a new engine that extends its life, ₦80,000 repainting it and ₦50,000 on routine servicing. New carrying amount = 3,000,000 + 1,200,000 = "},{"text":"₦4,200,000","bold":true},{"text":" (ignoring the year's depreciation). Expense = 80,000 + 50,000 = ₦130,000. Where a question says nothing about the old engine, simply add the capitalised cost."}]},{"type":"paragraph","text":[{"text":"Worked example 5 (revaluation up, then down).","bold":true},{"text":" Owode Mills Plc bought a building for ₦20,000,000 with a 20-year life and nil residual value (depreciation ₦1,000,000 a year). After 4 years: accumu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 30, $study_guide$lated depreciation ₦4,000,000, carrying amount ₦16,000,000. It is revalued to ₦24,000,000."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Surplus = 24,000,000 − 16,000,000 = "},{"text":"₦8,000,000","bold":true},{"text":" (to OCI)."}]},{"text":[{"text":"Journal: Dr Accumulated depreciation 4,000,000; Dr Building (24,000,000 − 20,000,000) 4,000,000; Cr Revaluation surplus 8,000,000."}]},{"text":[{"text":"New depreciation over the remaining 16 years = 24,000,000 ÷ 16 = ₦1,500,000. Excess over historical-cost depreciation = 1,500,000 − 1,000,000 = ₦500,000, transferred each year: Dr Revaluation surplus 500,000; Cr Retained earnings 500,000."}]},{"text":[{"text":"Two years later: carrying amount = 24,000,000 − (2 × 1,500,000) = ₦21,000,000; surplus left = 8,000,000 − (2 × 500,000) = ₦7,000,000. It is revalued down to ₦12,000,000. Decrease = 21,000,000 − 12,000,000 = ₦9,000,000: "},{"text":"₦7,000,000","bold":true},{"text":" against the surplus (OCI) and "},{"text":"₦2,000,000","bold":true},{"text":" to profit or loss."}]}]},{"type":"paragraph","text":[{"text":"Land:","bold":true},{"text":" land costing ₦15,000,000 revalued to ₦19,000,000 gives a ₦4,000,000 surplus in OCI; land can be revalued though not depreciated."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: revaluing one building means revaluing the "},{"text":"whole class","bold":true},{"text":" (e.g. all land and buildings), never one item, and never inventories."}]},{"text":[{"text":"Trap: a revaluation gain is "},{"text":"not","bold":true},{"text":" revenue and not profit; it is OCI."}]}]}]},{"number":"6.4","title":"Depreciation: principles, causes and review","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Purpose:","bold":true},{"text":" to spread cost over the periods of use, "},{"text":"matching the cost of using the asset with the revenue it generates","bold":true},{"text":"; not to build a replacement fund or show market value."}]},{"text":[{"text":"Causes of depreciation (6):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"use;"}]},{"text":[{"text":"physical wear and tear;"}]},{"text":[{"text":"passage of time;"}]},{"text":[{"text":"obsolescence;"}]},{"text":[{"text":"change in technology or fashion;"}]},{"text":[{"text":"depletion (mineral resources such as oil, gas, quarries)."}]}]}]},{"text":[{"text":"Rules:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Depreciable amount = Cost (or revalued amount) − Residual value."}]},{"text":[{"text":"The "},{"text":"method","bold":true},{"text":" must reflect the "},{"text":"pattern in which the asset's future economic benefits are expected to be consumed","bold":true},{"text":". Methods based on revenue are not appropriate."}]},{"text":[{"text":"Component accounting:","bold":true},{"text":" each part with a cost significant to the total is depreciated separately (e.g. an aircraft's engines and its body)."}]},{"text":[{"text":"Depreciation "},{"text":"begins","bold":true},{"text":" when the asset is "},{"text":"available for use","bold":true},{"text":", and "},{"text":"ceases","bold":true},{"text":" at the earlier of classification as held for sale (IFRS 5) and derecognition. It does not stop because the asset is idle."}]},{"text":[{"text":"Land","bold":true},{"text":" normally has an unlimited life and is not depreciated; buildings are. Land and buildings are separated even when bought together."}]},{"text":[{"text":"Useful life, residual value and method are "},{"text":"reviewed at least at each financial year-end","bold":true},{"text":". A change is a "},{"text":"change in accounting estimate, applied prospectively","bold":true},{"text":" (IAS 8)."}]},{"text":[{"text":"The charge goes to profit or loss, unless it is included in the cost of another asset."}]}]}]},{"text":[{"text":"Factors in useful life:","bold":true},{"text":" expected usage, expected physical wear and tear, technical or commercial obsolescence, legal or similar limits (e.g. lease expiry)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Niger Delta oil well losing value as crude is extracted shows "},{"text":"depletion","bold":true},{"text":". A rise in market prices of similar assets is "},{"text":"not","bold":true},{"text":" a cause of depreciation."}]},{"text":[{"text":"If residual value rises to equal or exceed carrying amount, the charge is zero until it falls back below."}]}]},{"type":"paragraph","text":[{"text":"Worked example 6 (change in estimate).","bold":true},{"text":" A machine cost ₦6,000,000, nil residual value, 12-year life: ₦500,000 a year. After 4 years, carrying amount = 6,000,000 − 2,000,000 = ₦4,000,000. The remaining life is revised to 5 years. New charge = 4,000,000 ÷ 5 = "},{"text":"₦800,000","bold":true},{"text":" a year from year 5. No restatement of years 1 to 4."}]}]},{"number":"6.5","title":"Depreciation methods and computations","mustKnow":[{"type":"paragraph","text":[{"text":"Time-based methods (5):","bold":true},{"text":" straight line; reducing balance; sum of the digits; annuity; sinking fund. "},{"text":"Service-based (usage) methods:","bold":true},{"text":" units of production (output, machine hours)."}]},{"type":"paragraph","text":[{"text":"Formulas:"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Straight line: Annual depreciation = (Cost − Residual value) ÷ Useful life"}]},{"text":[{"text":"Straight line at a %: Depreciation = Rate × Depreciable amount (when the question says the rate applies to the depreciable amount)"}]},{"text":[{"text":"Reducing balance: Year 1 depreciation = Rate × Cost; later years = Rate × Carrying amount at the start of the year"}]},{"text":[{"text":"Reducing balance rate: R = (1 − nth root of (S ÷ C)) × 100, where n = useful life, S = residual value, C = cost"}]},{"text":[{"text":"Carrying amount after n years (reducing balance): A = P(1 − r)^n, where P = cost$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 31, $study_guide$, r = rate"}]},{"text":[{"text":"Sum of the digits: Depreciation = (Remaining life at start of year ÷ Sum of the years' digits) × Depreciable amount; sum of digits = n(n + 1) ÷ 2"}]},{"text":[{"text":"Units of production: Rate per unit = (Cost − Residual value) ÷ Total expected units; Depreciation = Rate per unit × Units in the year"}]}]},{"type":"table","header":[[{"text":"Method"}],[{"text":"Pattern of charge"}]],"rows":[[[{"text":"Straight line (\"fixed instalment\")"}],[{"text":"Same every year"}]],[[{"text":"Reducing balance"}],[{"text":"Higher early, falling each year"}]],[[{"text":"Sum of the digits"}],[{"text":"Higher early, falling by a constant amount"}]],[[{"text":"Units of production"}],[{"text":"Varies with use"}]]]},{"type":"paragraph","text":[{"text":"The annuity method builds interest on the capital tied up in the asset into the charge; the sinking fund method charges equal amounts that are also invested in an outside fund to replace the asset."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 7 (straight line).","bold":true},{"text":" Motor car cost ₦2,500,000, residual value ₦250,000, life 5 years. Depreciation = (2,500,000 − 250,000) ÷ 5 = "},{"text":"₦450,000","bold":true},{"text":" a year."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Cost ₦"}],[{"text":"Accumulated depreciation ₦"}],[{"text":"Carrying amount ₦"}]],"rows":[[[{"text":"1"}],[{"text":"2,500,000"}],[{"text":"450,000"}],[{"text":"2,050,000"}]],[[{"text":"2"}],[{"text":"2,500,000"}],[{"text":"900,000"}],[{"text":"1,600,000"}]],[[{"text":"3"}],[{"text":"2,500,000"}],[{"text":"1,350,000"}],[{"text":"1,150,000"}]],[[{"text":"4"}],[{"text":"2,500,000"}],[{"text":"1,800,000"}],[{"text":"700,000"}]],[[{"text":"5"}],[{"text":"2,500,000"}],[{"text":"2,250,000"}],[{"text":"250,000"}]]]},{"type":"paragraph","text":[{"text":"Carrying amount after n years = Cost − n × annual charge. If a rate is given \"on depreciable amount\": a van costing ₦1,500,000 with scrap value ₦300,000 at 25% gives 25% × 1,200,000 = ₦300,000 a year. For part years, time-apportion: an asset with a ₦450,000 annual charge bought on 1 April by a 31 December company bears 450,000 × 9/12 = ₦337,500 in year 1 (unless the question states a full-year policy)."}]},{"type":"paragraph","text":[{"text":"Worked example 8 (reducing balance, rate from the formula).","bold":true},{"text":" Kano Haulage Ltd buys a truck for ₦1,000,000; life 3 years; residual value ₦216,000."}]},{"type":"paragraph","text":[{"text":"R = (1 − cube root of (216,000 ÷ 1,000,000)) × 100 = (1 − cube root of 0.216) × 100 = (1 − 0.6) × 100 = "},{"text":"40%","bold":true},{"text":"."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Depreciation ₦"}],[{"text":"Carrying amount ₦"}]],"rows":[[[{"text":"1"}],[{"text":"40% × 1,000,000 = 400,000"}],[{"text":"600,000"}]],[[{"text":"2"}],[{"text":"40% × 600,000 = 240,000"}],[{"text":"360,000"}]],[[{"text":"3"}],[{"text":"40% × 360,000 = 144,000"}],[{"text":"216,000"}]]]},{"type":"paragraph","text":[{"text":"Check with A = P(1 − r)^n: 1,000,000 × 0.6³ = ₦216,000, the residual value. To find a carrying amount fast, use A = P(1 − r)^n; to find a year's charge, multiply the rate by the opening carrying amount (for year 3: 1,000,000 × 0.6² × 0.4). On a calculator, the nth root is (S ÷ C) to the power 1/n; if a rate is not exact, round to two decimal places and say so."}]},{"type":"paragraph","text":[{"text":"Worked example 9 (sum of the digits).","bold":true},{"text":" Cost ₦1,600,000, residual value ₦100,000, life 5 years. Depreciable amount ₦1,500,000; sum of digits = 5 × 6 ÷ 2 = 15. Charges: 5/15 × 1,500,000 = ₦500,000; then ₦400,000, ₦300,000, ₦200,000, ₦100,000 (total ₦1,500,000)."}]},{"type":"paragraph","text":[{"text":"Worked example 10 (units of production).","bold":true},{"text":" Aba Bottlers Ltd's machine cost ₦8,000,000, residual value ₦800,000, expected output 120,000 machine hours. Rate = 7,200,000 ÷ 120,000 = ₦60 per hour. Year 1 used 18,000 hours: 18,000 × 60 = "},{"text":"₦1,080,000","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: the reducing balance rate is applied to the "},{"text":"carrying amount","bold":true},{"text":", not to cost each year, and residual value is "},{"text":"not","bold":true},{"text":" deducted first. Units of production is "},{"text":"not","bold":true},{"text":" a time-based method."}]}]}]},{"number":"6.6","title":"Derecognition, disposal and disclosures","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Derecognise","bold":true},{"text":" an item of PPE (a) on "},{"text":"disposal","bold":true},{"text":", or (b) when "},{"text":"no future economic benefits","bold":true},{"text":" are expected from its use or disposal. Being fully depreciated is not a reason to derecognise if it is still in use."}]},{"text":[{"text":"Gain or loss on disposal = "},{"text":"Net disposal proceeds − Carrying amount","bold":true},{"text":", where Net disposal proceeds = Selling price − Costs of disposal (including costs of putting the asset in saleable condition) and Carrying amount = Cost − Accumulated depreciation (to the date of disposal)."}]},{"text":[{"text":"The gain or loss goes to "},{"text":"profit or loss","bold":true},{"text":"; a gain is "},{"text":"not classified as revenue","bold":true},{"text":"."}]},{"text":[{"text":"On disposal of a revalued asset, any remaining revaluation surplus is transferred "},{"text":"directly to retained earnings","bold":true},{"text":", not through profit or loss."}]}]},{"type":"paragraph","text":[{"text":"Disclosures","bold":true},{"text":", for each class of PPE:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"measurement bases used for gross carrying amount;"}]},{"text":[{"text":"depreciation methods used;"}]},{"text":[{"text":"useful lives or depreciation rates;"}]},{"text":[{"text":"gross carrying amount and accumulated depreciation (with accumulated impai$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 32, $study_guide$rment losses) at the start and end of the period;"}]},{"text":[{"text":"a reconciliation of carrying amount from start to end showing additions, disposals and assets held for sale, revaluation increases and decreases, impairment losses and reversals, depreciation and other movements."}]}]},{"type":"paragraph","text":[{"text":"Also: restrictions on title and assets pledged as security; spending on assets under construction; commitments to buy PPE; third-party compensation. Revalued classes: revaluation date, whether an independent valuer was used, carrying amount under the cost model, and the revaluation surplus, its movement and restrictions on distribution."}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 11 (disposal).","bold":true},{"text":" Onitsha Freight Ltd bought a truck for ₦8,000,000, residual value ₦800,000, life 6 years, straight line: (8,000,000 − 800,000) ÷ 6 = ₦1,200,000 a year. It sold the truck at the end of year 4 for ₦3,000,000, paying ₦100,000 selling costs."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Accumulated depreciation = 4 × 1,200,000 = ₦4,800,000"}]},{"text":[{"text":"Carrying amount = 8,000,000 − 4,800,000 = ₦3,200,000"}]},{"text":[{"text":"Net proceeds = 3,000,000 − 100,000 = ₦2,900,000"}]},{"text":[{"text":"Loss = 2,900,000 − 3,200,000 = "},{"text":"₦300,000 loss","bold":true}]}]},{"type":"paragraph","text":[{"text":"Disposal account: debit cost 8,000,000; credit accumulated depreciation 4,800,000 and net proceeds 2,900,000; the remaining debit balance of 300,000 is the loss, transferred to profit or loss."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: deduct costs of disposal, and costs of making the asset saleable, from the proceeds. Count the years carefully: bought January 2023 and sold December 2025 is "},{"text":"three","bold":true},{"text":" full years of depreciation."}]},{"text":[{"text":"Trap: compare proceeds with "},{"text":"carrying amount","bold":true},{"text":", never cost."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"PPE = tangible, used in production/supply, rental or administration, for more than one period; recognise if benefits probable and cost reliable."}]},{"text":[{"text":"Initial cost = purchase price (with import duty, net of trade discount, without recoverable taxes) + directly attributable costs + discounted dismantling estimate."}]},{"text":[{"text":"Expense training, overheads, repairs, abnormal waste, and costs after the asset is ready for use."}]},{"text":[{"text":"Subsequent cost is capitalised only if it enhances the asset; servicing and repainting are expensed."}]},{"text":[{"text":"Cost model vs revaluation model, chosen by class; surplus to OCI, decrease to profit or loss after using up that asset's surplus."}]},{"text":[{"text":"Depreciable amount = Cost − Residual value; method follows the pattern of consumption; reviews are changes in estimate, applied prospectively."}]},{"text":[{"text":"Straight line = (C − S) ÷ n; reducing balance rate = 1 − nth root of (S ÷ C); A = P(1 − r)^n."}]},{"text":[{"text":"Gain or loss on disposal = net proceeds − carrying amount, in profit or loss, not revenue."}]}]}],"theory":{"itemId":"9c660b40-0844-5a05-b06f-7b508754459d","question":[{"type":"paragraph","text":[{"text":"Yaba Print Ltd bought a machine for ₦2,000,000 in January 2023, with a scrap value of ₦200,000. It is depreciated at 25% a year on a straight line basis on its depreciable amount. It was sold in December 2025 for ₦900,000 after spending ₦40,000 to put it in sellable condition. Calculate the gain or loss on disposal."}]}]},"practice":[{"topic":"IAS 16 Property, Plant and Equipment","named":false}]}},{"kind":"note","itemId":"50e612ca-5ac5-52e7-befb-cd5c5052deb6","sourceKey":"guide-topic:7","position":7,"payload":{"title":"IAS 20 Government Grants and Disclosure of Government Assistance","body":"The meaning of government, grant and assistance; the two recognition conditions; the capital and income approaches; grants related to assets (deduct from cost or deferred income) and to income; prorating a grant over related costs; repayment; non-monetary grants and low-interest loans; disclosures.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The meaning of government, grant and assistance; the two recognition conditions; the capital and income approaches; grants related to assets (deduct from cost or deferred income) and to income; prorating a grant over related costs; repayment; non-monetary grants and low-interest loans; disclosures."}],"lessons":[{"number":"7.1","title":"Government, grants and assistance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Government:","bold":true},{"text":" the government of nations, government agencies and similar bodies, whether "},{"text":"local, national or international","bold":true},{"text":"."}]},{"text":[{"text":"Government grants:","bold":true},{"text":" government assistance, "},{"text":"quantified in monetary terms","bold":true},{"text":", in the form of "},{"text":"transfers of resources","bold":true},{"text":" to an entity "},{"text":"in return for past or future compliance with certain conditions","bold":true},{"text":" relating to the operating activities of the entity."}]},{"text":[{"text":"Government assistance:","bold":true},{"text":" "},{"text":"any action of government","bold":true},{"text":" aimed at giving economic benefits to an entity or range of entities qualifying under certain criteria."}]},{"text":[{"text":"All government grants are assistance, but not all assistance is a grant.","bold":true},{"text":" A grant has a monetary value and involves a transfer of resources; much assistance does not."}]},{"text":[{"text":"Two types of grant:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Grants related to assets:","bold":true},{"text":" the primary condition is that the entity "},{"text":"purchases, constr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 33, $study_guide$ucts or otherwise acquires non-current assets","bold":true},{"text":"."}]},{"text":[{"text":"Grants related to income:","bold":true},{"text":" grants for "},{"text":"any purpose other than","bold":true},{"text":" supporting the acquisition of non-current assets (e.g. towards wages, training or running costs)."}]}]}]},{"text":[{"text":"Forgivable loans:","bold":true},{"text":" loans that the lender undertakes to waive repayment of under prescribed conditions."}]}]},{"type":"table","header":[[],[{"text":"Grant"}],[{"text":"Assistance without monetary value"}]],"rows":[[[{"text":"Monetary value"}],[{"text":"Yes"}],[{"text":"No (cannot reasonably be valued)"}]],[[{"text":"Accounted for"}],[{"text":"Yes, under IAS 20"}],[{"text":"Not recognised; disclosed if significant"}]],[[{"text":"Examples"}],[{"text":"Cash towards a machine; wage subsidy"}],[{"text":"Tax holiday, free technical or marketing advice, government guarantees"}]]]},{"type":"paragraph","text":[{"text":"Outside IAS 20:","bold":true},{"text":" tax benefits such as tax holidays and investment tax credits (IAS 12); government ownership of shares in the entity; grants on biological assets measured at fair value less costs to sell (IAS 41). Public infrastructure available to everyone (roads, communication networks) is not government assistance."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A state agency, a local government council and an international development authority are all \"government\". A privately owned commercial bank is "},{"text":"not","bold":true},{"text":", even if it lends to the entity."}]},{"text":[{"text":"The Federal Government gives Ikeja Foods Ltd a five-year "},{"text":"pioneer status tax holiday","bold":true},{"text":" with no cash paid: this is "},{"text":"assistance without monetary value","bold":true},{"text":", not a grant."}]},{"text":[{"text":"Lagos State pays ₦40 million to Ota Clinics Ltd on condition it buys a dialysis machine: a "},{"text":"grant related to assets","bold":true},{"text":" (a state grant is still a grant). An agency gives Kano Textiles Ltd ₦15 million towards staff wages, with no asset purchase required: a "},{"text":"grant related to income","bold":true},{"text":"."}]},{"text":[{"text":"Trap: options that reverse the rule (\"all assistance is a grant, but not all grants are assistance\") are wrong."}]}]}]},{"number":"7.2","title":"Recognition, approaches and special grants","mustKnow":[{"type":"paragraph","text":[{"text":"A grant is "},{"text":"not recognised","bold":true},{"text":" until there is "},{"text":"reasonable assurance","bold":true},{"text":" that:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the entity "},{"text":"will comply with the conditions","bold":true},{"text":" attaching to it; and"}]},{"text":[{"text":"the grant "},{"text":"will be received","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Both","bold":true},{"text":" must be met; one alone does not trigger recognition. Receiving the cash is not by itself proof that the conditions will be met."}]},{"type":"paragraph","text":[{"text":"Core principle:","bold":true},{"text":" grants are recognised in "},{"text":"profit or loss on a systematic basis","bold":true},{"text":" over the periods in which the entity recognises as expenses the related costs the grants are intended to compensate."}]},{"type":"paragraph","text":[{"text":"Two broad approaches:","bold":true}]},{"type":"table","header":[[{"text":"Capital approach"}],[{"text":"Income approach"}]],"rows":[[[{"text":"Grant recognised "},{"text":"outside profit or loss","bold":true},{"text":", credited directly to shareholders' interests (equity)"}],[{"text":"Grant recognised "},{"text":"in profit or loss","bold":true},{"text":" over one or more periods"}]],[[{"text":"Argument: it is a financing device, not earned"}],[{"text":"Argument: it is received from a source other than shareholders and is earned by complying with conditions"}]],[[{"text":"Not permitted","bold":true},{"text":" by IAS 20"}],[{"text":"Required","bold":true},{"text":" by IAS 20"}]]]},{"type":"paragraph","text":[{"text":"Special cases:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Grant compensating expenses or losses already incurred","bold":true},{"text":", or giving immediate support with no future related costs: recognised in profit or loss "},{"text":"in the period it becomes receivable","bold":true},{"text":"."}]},{"text":[{"text":"Grant for non-depreciable land","bold":true},{"text":" with conditions (e.g. build a factory on it): recognised over the periods that bear the cost of meeting the conditions (e.g. the life of the factory)."}]},{"text":[{"text":"Forgivable loan:","bold":true},{"text":" treated as a grant when there is reasonable assurance the terms for forgiveness will be met."}]},{"text":[{"text":"Below-market-interest government loan:","bold":true},{"text":" the benefit is a grant, measured as "},{"text":"Loan proceeds − Fair value of the loan","bold":true},{"text":" (initial fair value under IFRS 9)."}]},{"text":[{"text":"Non-monetary grant","bold":true},{"text":" (e.g. land or other assets): recorded at "},{"text":"fair value","bold":true},{"text":", or alternatively at a "},{"text":"nominal amount","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Enugu Agro Ltd is reasonably assured the ₦20 million cash will be paid but not that it can meet the job-creation condition: "},{"text":"recognise nothing yet","bold":true},{"text":". Once both conditions are reasonably assured, recognise it (with a contingent liability if conditions remain)."}]},{"text":[{"text":"Low-interest loan:","bold":true},{"text":" the Bank of Industry lends Oyo Poultry Ltd ₦10,000,000 at a concessionary rate; the fair value of the loan at a market rate is ₦8,200,000. Grant = 10,000,000 − 8,200,000 = "},{"text":"₦1,800,000","bold":true},{"text":", treated as$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 34, $study_guide$ a grant related to whatever it finances. The loan is carried at ₦8,200,000."}]},{"text":[{"text":"Non-monetary grant:","bold":true},{"text":" Ogun State gives Sagamu Ceramics Plc land worth ₦25,000,000 on condition it builds a factory: Dr Land 25,000,000; Cr Deferred income 25,000,000, released over the factory's life."}]},{"text":[{"text":"Trap: the core principle says a "},{"text":"systematic basis","bold":true},{"text":", not \"straight-line only\" and not \"in full when received\"."}]},{"text":[{"text":"Trap: the "},{"text":"capital approach","bold":true},{"text":" means crediting equity. Deducting a grant from an asset is "},{"text":"not","bold":true},{"text":" the capital approach: the grant still reaches profit or loss through lower depreciation."}]}]}]},{"number":"7.3","title":"Grants related to assets","mustKnow":[{"type":"paragraph","text":[{"text":"IAS 20 allows two presentations:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Deduct the grant from the cost (carrying amount) of the asset.","bold":true},{"text":" Dr Bank, Cr Asset. Depreciation is based on the "},{"text":"reduced amount","bold":true},{"text":". The grant reaches profit or loss as lower depreciation."}]},{"text":[{"text":"Deferred income method.","bold":true},{"text":" Dr Bank, Cr Deferred income. The asset stays at "},{"text":"full cost","bold":true},{"text":" and is depreciated on full cost; each year a portion of the grant is moved: "},{"text":"Dr Deferred income, Cr Income statement","bold":true},{"text":" (profit or loss)."}]}]},{"type":"paragraph","text":[{"text":"Formulas (straight line, nil residual value):"}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Method 1: Annual depreciation = (Cost − Grant) ÷ Useful life"}]},{"text":[{"text":"Method 2: Annual depreciation = Cost ÷ Useful life; Annual grant income = Grant ÷ Useful life"}]},{"text":[{"text":"Net annual charge (both methods) = (Cost − Grant) ÷ Useful life"}]},{"text":[{"text":"Deferred income balance after n years = Grant − n × annual grant income"}]}]},{"type":"table","header":[[],[{"text":"Deduct from cost"}],[{"text":"Deferred income"}]],"rows":[[[{"text":"Asset shown at"}],[{"text":"Cost less grant"}],[{"text":"Full cost"}]],[[{"text":"Depreciation"}],[{"text":"On cost less grant"}],[{"text":"On full cost"}]],[[{"text":"Grant income line"}],[{"text":"None"}],[{"text":"Yes, each year"}]],[[{"text":"Separate balance in SFP"}],[{"text":"None"}],[{"text":"Deferred income (current and non-current parts)"}]],[[{"text":"Net effect on profit"}],[{"text":"Same"}],[{"text":"Same"}]]]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 1.","bold":true},{"text":" XYZ Nigeria Limited receives a grant of ₦10,000,000 towards a Micro Magnetic machine costing ₦100,000,000, depreciated straight line over 5 years, nil residual value."}]},{"type":"paragraph","text":[{"text":"Method 1 (deduct from cost):","italic":true}]},{"type":"table","header":[[{"text":"Machine account"}],[{"text":"₦"}],[],[{"text":"₦"}]],"rows":[[[{"text":"Bank (cost)"}],[{"text":"100,000,000"}],[{"text":"Bank (grant)"}],[{"text":"10,000,000"}]],[[],[],[{"text":"Balance c/d"}],[{"text":"90,000,000"}]],[[],[{"text":"100,000,000"}],[],[{"text":"100,000,000"}]]]},{"type":"paragraph","text":[{"text":"Depreciation = 90,000,000 ÷ 5 = "},{"text":"₦18,000,000","bold":true},{"text":" a year for 5 years."}]},{"type":"paragraph","text":[{"text":"Method 2 (deferred income):","italic":true},{"text":" machine stays at ₦100,000,000; depreciation = 100,000,000 ÷ 5 = "},{"text":"₦20,000,000","bold":true},{"text":" a year. Grant income = 10,000,000 ÷ 5 = "},{"text":"₦2,000,000","bold":true},{"text":" a year."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Released to income ₦"}],[{"text":"Deferred income c/d ₦"}]],"rows":[[[{"text":"1"}],[{"text":"2,000,000"}],[{"text":"8,000,000"}]],[[{"text":"2"}],[{"text":"2,000,000"}],[{"text":"6,000,000"}]],[[{"text":"3"}],[{"text":"2,000,000"}],[{"text":"4,000,000"}]],[[{"text":"4"}],[{"text":"2,000,000"}],[{"text":"2,000,000"}]],[[{"text":"5"}],[{"text":"2,000,000"}],[{"text":"nil"}]]]},{"type":"paragraph","text":[{"text":"Net charge under Method 2 = 20,000,000 − 2,000,000 = ₦18,000,000, the same as Method 1."}]},{"type":"paragraph","text":[{"text":"Worked example 2 (balances after two years).","bold":true},{"text":" Onitsha Plastics Ltd buys a machine for ₦50,000,000 with a ₦15,000,000 grant; straight line over 5 years."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Method 1: depreciation = 35,000,000 ÷ 5 = ₦7,000,000; carrying amount at end of year 2 = 35,000,000 − 14,000,000 = "},{"text":"₦21,000,000","bold":true},{"text":". Total depreciation over the whole life = ₦35,000,000."}]},{"text":[{"text":"Method 2: depreciation = 50,000,000 ÷ 5 = ₦10,000,000; grant income ₦3,000,000; net charge ₦7,000,000. End of year 2: machine = 50,000,000 − 20,000,000 = "},{"text":"₦30,000,000","bold":true},{"text":"; deferred income = 15,000,000 − 6,000,000 = "},{"text":"₦9,000,000","bold":true},{"text":" (₦3,000,000 current, ₦6,000,000 non-current). Net 30,000,000 − 9,000,000 = ₦21,000,000, as Method 1."}]},{"text":[{"text":"Trap: under Method 2 the asset's carrying amount ignores the grant entirely. Under Method 1 the balance carried down straight after recording the grant is cost minus grant."}]},{"text":[{"text":"Trap: the release entry credits the "},{"text":"income statement","bold":true},{"text":", not bank, share capital or the asset."}]},{"text":[{"text":"In the statement of cash flows, the asset purchase and the grant receipt are shown as separate items under either method."}]}]}]},{"number":"7.4","title":"Grants related to income","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Grants related to income are "},{"text":"not recognised as income immediately on receipt","bold":true},{"text":"; they are "},{"text":"matched against the related expense","bold":true},{"text":" in t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 35, $study_guide$he periods the costs are incurred."}]},{"text":[{"text":"Presentation (either):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"separately","bold":true},{"text":", or under a general heading such as "},{"text":"\"other income\"","bold":true},{"text":"; or"}]},{"text":[{"text":"as a "},{"text":"deduction from the related expense","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Never credited directly to equity or retained earnings."}]}]},{"type":"paragraph","text":[{"text":"Prorating a grant over related costs (4 steps):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Ascertain the "},{"text":"total cost","bold":true},{"text":"."}]},{"text":[{"text":"Ascertain the "},{"text":"total value of the grant","bold":true},{"text":"."}]},{"text":[{"text":"Prorate the grant using each year's estimated cost","bold":true},{"text":": divide each year's cost by the total cost and multiply by the grant value."}]},{"text":[{"text":"Allocate the amount to the income statement."}]}]},{"type":"paragraph","text":[{"text":"Grant income for a year = (Cost incurred in the year ÷ Total estimated cost) × Total grant"}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 3.","bold":true},{"text":" Aba Leather Ltd receives a grant of ₦12,000,000 for a three-year programme with costs: Year 1 ₦2,000,000; Year 2 ₦3,000,000; Year 3 ₦5,000,000 (total ₦10,000,000)."}]},{"type":"table","header":[[{"text":"Year"}],[{"text":"Working"}],[{"text":"Grant income ₦"}]],"rows":[[[{"text":"1"}],[{"text":"2,000,000 ÷ 10,000,000 × 12,000,000"}],[{"text":"2,400,000"}]],[[{"text":"2"}],[{"text":"3,000,000 ÷ 10,000,000 × 12,000,000"}],[{"text":"3,600,000"}]],[[{"text":"3"}],[{"text":"5,000,000 ÷ 10,000,000 × 12,000,000"}],[{"text":"6,000,000"}]],[[{"text":"Total"}],[],[{"text":"12,000,000"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The total recognised over the whole period always equals the "},{"text":"total grant","bold":true},{"text":", even if the grant is larger than the total cost. Cumulative income to any date = cumulative cost ÷ total cost × grant: by the end of Year 2, (2,000,000 + 3,000,000) ÷ 10,000,000 × 12,000,000 = ₦6,000,000."}]},{"text":[{"text":"The same proportional method is used for a construction programme over several years (for example a grant for building a hangar spread over five years of construction costs)."}]},{"text":[{"text":"Presentation example:","bold":true},{"text":" a ₦4,000,000 wage subsidy for the year, against wages of ₦30,000,000, is shown either as other income of ₦4,000,000 (wages ₦30,000,000) or as net wages of ₦26,000,000."}]},{"text":[{"text":"A grant received to cover losses already suffered (e.g. flood damage last year) goes to profit or loss "},{"text":"when it becomes receivable","bold":true},{"text":"."}]}]}]},{"number":"7.5","title":"Repayment, assistance and disclosures","mustKnow":[{"type":"paragraph","text":[{"text":"A grant that becomes repayable is accounted for as a "},{"text":"change in accounting estimate","bold":true},{"text":" (prospectively)."}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Grant related to income:","bold":true},{"text":" apply the repayment first against any "},{"text":"unamortised deferred credit","bold":true},{"text":"; any excess goes to "},{"text":"profit or loss immediately","bold":true},{"text":"."}]},{"text":[{"text":"Grant related to assets:","bold":true},{"text":" "},{"text":"increase the carrying amount of the asset","bold":true},{"text":" or "},{"text":"reduce the deferred income balance","bold":true},{"text":" by the amount repayable. The "},{"text":"cumulative extra depreciation","bold":true},{"text":" that would have been charged without the grant is recognised "},{"text":"immediately in profit or loss","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Government assistance not recognised","bold":true},{"text":" (no monetary value) is disclosed where significant, for example free technical or marketing advice and government guarantees."}]},{"type":"paragraph","text":[{"text":"Disclosures:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"the accounting policy for government grants, including the "},{"text":"method of presentation","bold":true},{"text":" adopted;"}]},{"text":[{"text":"the "},{"text":"nature and extent","bold":true},{"text":" of grants recognised, and an indication of other forms of government assistance from which the entity has directly benefited;"}]},{"text":[{"text":"unfulfilled conditions and other contingencies","bold":true},{"text":" attaching to government assistance that has been recognised."}]}]}],"explainMore":[{"type":"paragraph","text":[{"text":"Worked example 4 (repayment, income grant).","bold":true},{"text":" Ilorin Rice Mills Ltd received ₦6,000,000; ₦2,000,000 is still in deferred income when it must repay the full ₦6,000,000. Dr Deferred income 2,000,000; Dr Profit or loss 4,000,000; Cr Bank 6,000,000."}]},{"type":"paragraph","text":[{"text":"Worked example 5 (repayment, asset grant).","bold":true},{"text":" A machine cost ₦40,000,000 with a ₦10,000,000 grant, straight line over 5 years. At the end of year 2 the whole grant becomes repayable."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Deduction method:","italic":true},{"text":" carrying amount = 30,000,000 − (2 × 6,000,000) = ₦18,000,000. Add back the grant: Dr Machine 10,000,000; Cr Bank 10,000,000. Extra depreciation that would have been charged = 10,000,000 ÷ 5 × 2 = ₦4,000,000: Dr Profit or loss 4,000,000; Cr Accumulated depreciation 4,000,000. New carrying amount = 18,000,000 + 10,000,000 − 4,000,000 = "},{"text":"₦24,000,000","bold":true},{"text":", which equals 40,000,000 − (2 × 8,000,000)."}]},{"text":[{"text":"Deferred income method:","italic":true},{"text":" deferred income left = 10,000,000 − (2 × 2,000,000) = ₦6,000,000. Dr Deferred income 6,00$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 36, $study_guide$0,000; Dr Profit or loss 4,000,000; Cr Bank 10,000,000."}]}]},{"type":"paragraph","text":[{"text":"Both give the same ₦4,000,000 charge."}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Government = local, national or international governments and agencies; a private bank is not government."}]},{"text":[{"text":"Grant = assistance with a monetary value, a transfer of resources for compliance with conditions; a tax holiday is assistance, not a grant."}]},{"text":[{"text":"Recognise only when reasonably assured of "},{"text":"both","bold":true},{"text":" compliance with conditions and receipt."}]},{"text":[{"text":"Recognise in profit or loss on a systematic basis, matched with the related costs (income approach); the capital approach (credit equity) is not allowed."}]},{"text":[{"text":"Asset grants: deduct from cost (depreciate the net amount) or deferred income (depreciate full cost, release grant ÷ life each year); net effect is identical."}]},{"text":[{"text":"Income grants: other income or deduction from the expense; prorate by each year's cost ÷ total cost × grant."}]},{"text":[{"text":"Repayment = change in estimate; extra depreciation to profit or loss at once."}]},{"text":[{"text":"Non-monetary grants at fair value or nominal amount; low-interest loan benefit = proceeds − fair value."}]}]}],"theory":{"itemId":"769e92ce-e4ee-57ca-9478-2081738e5730","question":[{"type":"paragraph","text":[{"text":"Ilaro Farms Ltd buys a tractor for ₦54,000,000 and receives a government grant of ₦12,000,000 towards it. The tractor is depreciated straight line over 3 years with nil residual value. Show the annual depreciation, the annual grant income and the net charge to profit or loss under each IAS 20 method."}]}]},"practice":[{"topic":"IAS 20 Government Grants","named":false}]}},{"kind":"note","itemId":"f9bf42c7-6af5-5a1d-89cc-a1295f37d298","sourceKey":"guide-topic:8","position":8,"payload":{"title":"IAS 23 Borrowing Costs","body":"The core principle; what borrowing costs are; qualifying assets; specific and general borrowings; the capitalisation rate and investment income; when capitalisation starts, is suspended and stops; disclosures; the computations.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The core principle; what borrowing costs are; qualifying assets; specific and general borrowings; the capitalisation rate and investment income; when capitalisation starts, is suspended and stops; disclosures; the computations."}],"lessons":[{"number":"8.1","title":"Core principle, borrowing costs and qualifying assets","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IAS 23","bold":true},{"text":" deals with "},{"text":"accounting for borrowing costs","bold":true},{"text":". (Government grants are IAS 20, revenue IFRS 15, inventories IAS 2.)"}]},{"text":[{"text":"Core principle:","bold":true},{"text":" borrowing costs that are "},{"text":"directly attributable to the acquisition, construction or production of a qualifying asset","bold":true},{"text":" form part of the cost of that asset and must be "},{"text":"capitalised","bold":true},{"text":". "},{"text":"Other borrowing costs are recognised as an expense","bold":true},{"text":" in the period in which they are incurred."}]},{"text":[{"text":"Capitalisation is "},{"text":"compulsory","bold":true},{"text":", not a choice. (An older version of IAS 23 allowed all borrowing costs to be expensed; the revised standard removed that option.)"}]},{"text":[{"text":"Borrowing costs:","bold":true},{"text":" interest and other costs that an entity incurs in connection with the borrowing of funds."}]},{"text":[{"text":"Qualifying asset:","bold":true},{"text":" an asset that "},{"text":"necessarily takes a substantial period of time","bold":true},{"text":" to get ready for its intended use or sale."}]}]},{"type":"paragraph","text":[{"text":"Borrowing costs include","bold":true},{"text":" (current IAS 23):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Interest expense calculated using the effective interest method","bold":true},{"text":" (IFRS 9)."}]},{"text":[{"text":"Interest in respect of lease liabilities","bold":true},{"text":" (IFRS 16)."}]},{"text":[{"text":"Exchange differences","bold":true},{"text":" arising from foreign currency borrowings "},{"text":"to the extent that they are regarded as an adjustment to interest costs","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Older wording you may meet in questions: interest on bank overdrafts and loans; amortisation of discounts or premiums on borrowings; "},{"text":"amortisation of ancillary costs","bold":true},{"text":" incurred in arranging borrowings (e.g. arrangement fees, "},{"text":"management fees and service charges","bold":true},{"text":" on a loan); and "},{"text":"finance charges on (finance) leases","bold":true},{"text":". Today these all sit inside the effective interest method or lease interest above."}]},{"text":[{"text":"Not borrowing costs:","bold":true},{"text":" dividends on ordinary shares, share issue costs, depreciation, repairs, income tax, audit fees, routine bank charges on customer receipts."}]}]},{"type":"paragraph","text":[{"text":"Qualifying assets (depending on circumstances):","bold":true},{"text":" inventories that take a substantial time to produce, manufacturing plants, "},{"text":"power generation facilities","bold":true},{"text":", intangible assets, investment properties and bearer plants."}]},{"type":"paragraph","text":[{"text":"Not qualifying assets:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Financial assets.","bold":true}]},{"text":[{"text":"Inventories manufactured or produced over a short period of time","bold":true},{"text":"."}]},{"text":[{"text":"Assets that are "},{"text":"ready for their intended use or sale when acquired","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 37, $study_guide$[{"text":"Scope:","bold":true},{"text":" IAS 23 need not be applied to qualifying assets measured at fair value (e.g. biological assets) or to inventories manufactured in large quantities on a repetitive basis."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A power plant that takes two years to build, a toll bridge built over several years, an office complex under construction for two years and a refinery built for the entity's own use are all qualifying assets. A delivery van bought ready for use from a dealer, or machinery ready for use when bought, is "},{"text":"not","bold":true},{"text":"."}]},{"text":[{"text":"Lagos Breweries Ltd borrows to fund routine drinks produced in large quantities within a few days. The drinks are "},{"text":"not","bold":true},{"text":" qualifying assets because they are produced over a short period. Trap: borrowing money does not make an asset qualifying, and it is wrong to say inventories are always, or never, qualifying assets. Whisky maturing in casks for years can qualify."}]},{"text":[{"text":"Trap: \"interest expense under the effective interest method "},{"text":"and","bold":true},{"text":" finance charges on leases\" is the pair of borrowing-cost components; dividends and share issue costs relate to equity, not borrowing."}]}]}]},{"number":"8.2","title":"Directly attributable costs and the two types of borrowing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Directly attributable","bold":true},{"text":" borrowing costs are those that "},{"text":"would have been avoided if the expenditure on the qualifying asset had not been made","bold":true},{"text":". Whether the interest was paid in cash, or is above market rate, does not decide it."}]},{"text":[{"text":"For capitalisation, borrowings are divided into "},{"text":"2 types","bold":true},{"text":":"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Specific borrowings:","bold":true},{"text":" funds borrowed specifically to obtain a particular qualifying asset."}]},{"text":[{"text":"General borrowings:","bold":true},{"text":" funds borrowed generally and used to obtain a qualifying asset."}]}]}]}]},{"type":"table","header":[[],[{"text":"Specific borrowings"}],[{"text":"General borrowings"}]],"rows":[[[{"text":"Amount capitalised"}],[{"text":"Actual borrowing costs incurred in the period "},{"text":"less","bold":true},{"text":" investment income on temporary investment of those borrowings"}],[{"text":"Capitalisation rate × expenditures","bold":true},{"text":" on the asset"}]],[[{"text":"Rate used"}],[{"text":"The loan's own rate"}],[{"text":"Weighted average","bold":true},{"text":" of costs of general borrowings outstanding"}]],[[{"text":"Limit"}],[{"text":"Actual cost of the loan (net of income)"}],[{"text":"Cannot exceed general borrowing costs incurred in the period"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Investment income","bold":true},{"text":" earned by temporarily investing specific borrowings before they are spent is "},{"text":"deducted","bold":true},{"text":", never added."}]},{"text":[{"text":"Capitalisation covers only the "},{"text":"capitalisation period","bold":true},{"text":" (from commencement to cessation, less any suspension); see Lesson 8.4."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Journal for capitalised interest: Dr Property, plant and equipment (asset under construction) / Cr Interest payable (or Bank). Interest outside the capitalisation period, or on loans not used for qualifying assets: Dr Finance costs (profit or loss) / Cr Interest payable."}]},{"text":[{"text":"Investment income on the specific loan: Dr Bank / Cr Property, plant and equipment, so the asset carries only the net cost."}]},{"text":[{"text":"Trap: borrowing costs not directly attributable to a qualifying asset are "},{"text":"expensed as incurred","bold":true},{"text":". They are not charged to retained earnings, deferred, or added to PPE."}]}]}]},{"number":"8.3","title":"Computing the amount to capitalise","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Specific borrowing:","bold":true},{"text":" Capitalised = Loan × Annual rate × (Months in capitalisation period ÷ 12) − Investment income on temporary investment."}]},{"text":[{"text":"Capitalisation rate (general borrowings)","bold":true},{"text":" = general borrowing costs for the period ÷ weighted average general borrowings outstanding in the period. It is a "},{"text":"weighted average","bold":true},{"text":", never the simple average, highest or lowest rate."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Weighted average general borrowings = Σ (Loan × months outstanding ÷ 12). Exclude specific borrowings (until the asset they funded is ready, after which any amount still outstanding joins the general pool)."}]}]}]},{"text":[{"text":"General borrowing:","bold":true},{"text":" Capitalised = Capitalisation rate × Σ (Expenditure × months in capitalisation period after it was incurred ÷ 12)."}]},{"text":[{"text":"Cap:","bold":true},{"text":" amount capitalised from general borrowings ≤ total general borrowing costs actually incurred in the period."}]},{"text":[{"text":"Expenditures","bold":true},{"text":" count only when they result in payments of cash, transfer of other assets or assumption of interest-bearing liabilities. They are "},{"text":"reduced by progress payments received and grants received","bold":true},{"text":" in connection with the asset. Eligible expenditure = Amount spent − Progress payments received − Grants received."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Worked example (specific, investment income).","bold":true},{"text":" Ota Cement Ltd borrowed ₦200 million at 15% on 1 January specifically to build a kiln; work ran all year. Unused funds were temporarily invested, earning ₦3.5 million."}],"blocks":[{"type$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 38, $study_guide$":"list","ordered":false,"items":[{"text":[{"text":"Interest = ₦200m × 15% = ₦30m"}]},{"text":[{"text":"Capitalised = ₦30m − ₦3.5m = "},{"text":"₦26.5m","bold":true}]}]}]},{"text":[{"text":"Worked example (specific, part year).","bold":true},{"text":" Ikot Ekpene Mills Ltd borrowed ₦90 million at 16% on 1 January for a qualifying asset; expenditure and work began on 1 May and ran to 31 December."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capitalised = ₦90m × 16% × 8/12 = "},{"text":"₦9.6m","bold":true}]},{"text":[{"text":"Expensed (January to April) = ₦90m × 16% × 4/12 = ₦4.8m"}]}]}]},{"text":[{"text":"Worked example (general borrowings).","bold":true},{"text":" Enugu Power Ltd (year ended 31 December) had these general borrowings all year: ₦100m at 12%, ₦150m at 16%, ₦50m at 9%. It spent ₦60m on a plant on 1 March and ₦80m on 1 September; work continued to the year end."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Interest: ₦12m + ₦24m + ₦4.5m = ₦40.5m"}]},{"text":[{"text":"Capitalisation rate = ₦40.5m ÷ ₦300m = "},{"text":"13.5%","bold":true}]},{"text":[{"text":"₦60m × 13.5% × 10/12 = ₦6.75m"}]},{"text":[{"text":"₦80m × 13.5% × 4/12 = ₦3.6m"}]},{"text":[{"text":"Capitalised = ₦6.75m + ₦3.6m = "},{"text":"₦10.35m","bold":true},{"text":" (below the ₦40.5m incurred, so the cap does not bite)"}]},{"text":[{"text":"The remaining ₦40.5m − ₦10.35m = ₦30.15m is a finance cost in profit or loss."}]}]}]},{"text":[{"text":"Worked example (loan outstanding part of year).","bold":true},{"text":" General loans: ₦200m at 10% all year, and ₦100m at 15% taken on 1 July. Interest = ₦20m + (₦100m × 15% × 6/12) ₦7.5m = ₦27.5m. Weighted borrowings = ₦200m + (₦100m × 6/12) ₦50m = ₦250m. Rate = ₦27.5m ÷ ₦250m = "},{"text":"11%","bold":true},{"text":"."}]},{"text":[{"text":"Worked example (the cap).","bold":true},{"text":" Benin Builders Ltd's general borrowings cost ₦65m in the year. Rate × weighted expenditure gives ₦78m. It may capitalise only "},{"text":"₦65m","bold":true},{"text":"."}]},{"text":[{"text":"Worked example (grant deducted).","bold":true},{"text":" On 1 April an entity spends ₦80m on a qualifying asset and receives a ₦20m grant for it the same day. Eligible expenditure = ₦80m − ₦20m = ₦60m, to which the rate is applied for the 9 months to 31 December."}]},{"text":[{"text":"Trap: for a simple average of 10%, 5% and 20% you would get 11.67%; that is wrong. Weight each rate by the size of its loan."}]}]}]},{"number":"8.4","title":"Commencement, suspension, cessation and disclosure","mustKnow":[{"type":"paragraph","text":[{"text":"Commencement:","bold":true},{"text":" capitalisation begins on the date the entity "},{"text":"first meets all 3 conditions","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It "},{"text":"incurs expenditures","bold":true},{"text":" for the asset."}]},{"text":[{"text":"It "},{"text":"incurs borrowing costs","bold":true},{"text":"."}]},{"text":[{"text":"It "},{"text":"undertakes activities necessary to prepare the asset","bold":true},{"text":" for its intended use or sale."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Activities\" include "},{"text":"technical and administrative work before physical construction","bold":true},{"text":", such as "},{"text":"obtaining permits","bold":true},{"text":". They do "},{"text":"not","bold":true},{"text":" include merely "},{"text":"holding","bold":true},{"text":" an asset when no production or development that changes its condition is taking place (e.g. land held with no development)."}]}]},{"type":"paragraph","text":[{"text":"Suspension:","bold":true},{"text":" capitalisation is suspended "},{"text":"during extended periods in which active development is suspended","bold":true},{"text":". It is "},{"text":"not","bold":true},{"text":" suspended:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"While "},{"text":"substantial technical and administrative work","bold":true},{"text":" is being carried out."}]},{"text":[{"text":"When a "},{"text":"temporary delay is a necessary part of the process","bold":true},{"text":" (e.g. high water levels that are common in the region during construction season)."}]}]},{"type":"paragraph","text":[{"text":"Cessation:","bold":true},{"text":" capitalisation ceases when "},{"text":"substantially all the activities necessary to prepare the asset for its intended use or sale are complete","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"An asset is normally ready when "},{"text":"physical construction is complete","bold":true},{"text":", even if routine administrative work continues or "},{"text":"minor modifications","bold":true},{"text":" remain (e.g. decoration to a buyer's or user's specification)."}]},{"text":[{"text":"When construction is done "},{"text":"in parts","bold":true},{"text":" and each part can be used "},{"text":"while construction continues on other parts","bold":true},{"text":" (e.g. a business park with several buildings), capitalisation stops for "},{"text":"each part","bold":true},{"text":" when substantially all activities on that part are complete. If the whole must be finished before any part can be used (e.g. an industrial plant with sequential processes), it stops when the whole is complete."}]},{"text":[{"text":"Capitalisation does "},{"text":"not","bold":true},{"text":" depend on when the loan is repaid, when the asset is first used or sold, or when a tenant signs."}]}]},{"type":"paragraph","text":[{"text":"Disclosures (2 items):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The "},{"text":"amount of borrowing costs capitalised","bold":true},{"text":" during the period."}]},{"text":[{"text":"The "},{"text":"capitalisation rate","bold":true},{"text":" used to determine the amount eligible for capitalisation."}]}]}],"explainMore":[{"type":"list","ordered"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 39, $study_guide$:false,"items":[{"text":[{"text":"Worked example (commencement).","bold":true},{"text":" Port Harcourt Marine Ltd borrowed ₦100m at 12% on 1 January for a jetty; expenditure and work began on 1 April. Capitalised = ₦100m × 12% × 9/12 = "},{"text":"₦9m","bold":true},{"text":"; January to March interest ₦3m is expensed, because only 2 of the 3 conditions were met."}]},{"text":[{"text":"Owerri Hotels Ltd holds land bought with a loan, waiting for a better market, with no development activity. Borrowing costs in this period are "},{"text":"not","bold":true},{"text":" capitalised, even though interest and expenditure are being incurred."}]},{"text":[{"text":"Worked example (suspension).","bold":true},{"text":" Jos Mining Ltd's specific ₦60m loan at 10% funds a plant built all year, except 3 months when it deliberately halted work over a contractor dispute (not a necessary part of the process). Capitalised = ₦60m × 10% × 9/12 = "},{"text":"₦4.5m","bold":true},{"text":"; ₦1.5m is expensed."}]},{"text":[{"text":"Necessary delay.","bold":true},{"text":" A Niger Delta bridge stops for some weeks each year because of seasonal high water common in the region: capitalisation "},{"text":"continues","bold":true},{"text":" through those weeks."}]},{"text":[{"text":"Worked example (cessation).","bold":true},{"text":" Calabar Ports Ltd borrowed ₦120m at 15% for a warehouse; everything began on 1 January and substantially all activities were complete at the end of month 10. The loan stayed outstanding all year. Capitalised = ₦120m × 15% × 10/12 = "},{"text":"₦15m","bold":true},{"text":"; the last 2 months' interest (₦3m) is expensed."}]},{"text":[{"text":"Ajah Homes Ltd's apartment block is physically complete; only minor decoration to each buyer's taste remains. Capitalisation has "},{"text":"ceased","bold":true},{"text":"."}]},{"text":[{"text":"Trap: \"the asset has been approved by a regulator\" is "},{"text":"not","bold":true},{"text":" one of the 3 commencement conditions."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"IAS 23 = borrowing costs. Directly attributable costs of a qualifying asset "},{"text":"must","bold":true},{"text":" be capitalised; all others expensed."}]},{"text":[{"text":"Borrowing costs: effective-interest-method interest, lease interest, qualifying exchange differences (older lists: ancillary costs such as management fees and service charges, finance lease charges). Never dividends."}]},{"text":[{"text":"Qualifying asset = necessarily takes a substantial period to get ready. Not financial assets, quick-production inventories or ready-to-use assets."}]},{"text":[{"text":"Directly attributable = would have been avoided without the expenditure."}]},{"text":[{"text":"2 types of borrowing: specific (actual cost less investment income) and general (capitalisation rate × expenditure)."}]},{"text":[{"text":"Capitalisation rate = weighted average cost of general borrowings; amount capped at actual general borrowing costs."}]},{"text":[{"text":"Expenditure is net of progress payments and grants received."}]},{"text":[{"text":"Start when all 3 conditions are met; suspend in extended halts of active development; stop when substantially all activities are complete."}]},{"text":[{"text":"Disclose the amount capitalised and the capitalisation rate."}]}]}],"theory":{"itemId":"ff8c8a26-32df-5eb1-87b2-6bb13386435c","question":[{"type":"paragraph","text":[{"text":"Owode Steel Ltd (year ended 31 December) had general borrowings outstanding all year: ₦400m at 10% and ₦100m at 15%. It built a rolling mill (a qualifying asset) throughout the year, spending ₦120m on 1 January and ₦80m on 1 July. Compute the capitalisation rate and the borrowing costs to capitalise."}]}]},"practice":[{"topic":"IAS 23 Borrowing Costs","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"b202e757-7d10-53d4-bacc-0546607956a5","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Kano Textiles Ltd had net assets of ₦20,000,000 at the start of the year and ₦26,000,000 at the end. There were no capital contributions or dividends. General inflation was 12%, and restoring the company's opening operating capability at year-end prices would cost ₦25,000,000. Compute profit under (a) money financial capital, (b) constant purchasing power financial capital and (c) physical capital maintenance."},"answer":{"kind":"model_answer","itemId":"b98f073c-b5ca-5d95-aea7-0c6a1f4d1557","sourceKey":"guide-answer:1","payload":{"body":"• (a) Capital to maintain = ₦20,000,000. Profit = 26,000,000 − 20,000,000 = ₦6,000,000.\n• (b) Capital to maintain = 20,000,000 × 1.12 = ₦22,400,000. Profit = 26,000,000 − 22,400,000 = ₦3,600,000.\n• (c) Capital to maintain = ₦25,000,000. Profit = 26,000,000 − 25,000,000 = ₦1,000,000.\nThe higher the capital that must be maintained, the lower the profit."}}},{"kind":"theory_question","itemId":"2e164bcb-4351-5dfb-a698-0355350a6d6d","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"On 1 July 2025, Ikeja Solar Ltd sells a solar system for ₦4,500,000, covering equipment, installation and 12 months' maintenance. SSPs: equipment ₦3,600,000; installation ₦600,000; maintenance ₦800,000. Equipment is delivered and installed in July 2025; maintenance is provided evenly. Calculate revenue for the year ended 31 December 2025."},"answer":{"kind":"model_answer","itemId":"9e1e78f9-1efb-59f8-9c71-0aa0c4dd3f2e","sourceKey":"guide-answer:2","payload":{"body":"1. Total SSPs = 3,600,000 + 600,000 + 800,000 = ₦5,000,000. Ratio = 4,500,000 ÷ 5,000,000 = 0.9 (discount ₦500,000 spread over all three).\n2. Allocation: equipment ₦3,240,000; installation ₦540,000; maintenance ₦720,000 (total ₦4,500,000).\n3. Equipment and installation are satisfied in July: ₦3,240,000 + ₦540,000 = ₦3,780,000.\n4. Maintenance over time: 720,000 × 6/12 = ₦360,000.\n5. Revenue for 2025 = 3,780,000 + 360,000 = ₦4,140,000. Contract liability at 31 December 2025 = ₦360,000."}}},{"kind":"theory_question"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_acc_cm201', 40, $study_guide$,"itemId":"f4e19e40-4af3-591f-8d76-5f95fbefdf81","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Owerri Mills Plc reports profit of ₦30m. OCI (net of tax): revaluation gain on land ₦5m, remeasurement loss on its defined benefit plan ₦1m, translation gain on a foreign operation ₦2m. Opening retained earnings ₦50m; dividends paid ₦8m. Find (a) TCI, (b) OCI that will not be reclassified, (c) closing retained earnings."},"answer":{"kind":"model_answer","itemId":"a1be846a-232c-541f-8d64-e711fc820f00","sourceKey":"guide-answer:3","payload":{"body":"(a) OCI = 5 − 1 + 2 = ₦6m; TCI = 30 + 6 = ₦36m.\n(b) 5 − 1 = ₦4m (the translation gain will be reclassified on disposal).\n(c) 50 + 30 − 8 = ₦72m. OCI goes to its own reserves, and dividends are a transaction with owners, not an expense."}}},{"kind":"theory_question","itemId":"d829ed04-b4f2-54c3-8629-41ef118db268","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Mushin Fabrics Ltd holds a batch of cloth costing ₦600,000. It is expected to sell for ₦650,000 after further dyeing costing ₦70,000, and selling costs of ₦30,000 will be incurred. At what amount should the cloth be measured, and what entry is needed?"},"answer":{"kind":"model_answer","itemId":"12cb5ec7-8f4a-5871-8199-d1b1ceccaa40","sourceKey":"guide-answer:4","payload":{"body":"• NRV = ₦650,000 − ₦70,000 − ₦30,000 = ₦550,000.\n• Lower of cost (₦600,000) and NRV (₦550,000) = ₦550,000.\n• Write-down = ₦600,000 − ₦550,000 = ₦50,000, expensed this period: Dr Cost of sales ₦50,000 / Cr Inventory ₦50,000.\n• The ₦50,000 write-down is disclosed in the financial statements."}}},{"kind":"theory_question","itemId":"04a47742-4e01-5f38-a479-e4dd51f113ff","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Kogi Power Ltd's generator cost ₦36,000,000, residual value ₦4,000,000, straight line over 8 years. At the start of Year 4 the remaining life is revised to 4 years and the residual value to ₦2,000,000. Classify the change, and compute the Year 4 charge and its effect on profit."},"answer":{"kind":"model_answer","itemId":"fdfc2b0d-2a8f-5908-828f-50c1d8009dc2","sourceKey":"guide-answer:5","payload":{"body":"1. Revised life and residual value are changes in accounting estimate, applied prospectively: Years 1 to 3 are not restated.\n2. Old charge = (₦36,000,000 − ₦4,000,000) ÷ 8 = ₦4,000,000.\n3. Carrying amount at start of Year 4 = ₦36,000,000 − (3 × ₦4,000,000) = ₦24,000,000.\n4. Year 4 charge = (₦24,000,000 − ₦2,000,000) ÷ 4 = ₦5,500,000.\n5. Year 4 profit is ₦5,500,000 − ₦4,000,000 = ₦1,500,000 lower than under the old estimate. Disclose the nature and amount of the change."}}},{"kind":"theory_question","itemId":"9c660b40-0844-5a05-b06f-7b508754459d","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Yaba Print Ltd bought a machine for ₦2,000,000 in January 2023, with a scrap value of ₦200,000. It is depreciated at 25% a year on a straight line basis on its depreciable amount. It was sold in December 2025 for ₦900,000 after spending ₦40,000 to put it in sellable condition. Calculate the gain or loss on disposal."},"answer":{"kind":"model_answer","itemId":"2548d062-0465-5a63-8d81-11f07ff21829","sourceKey":"guide-answer:6","payload":{"body":"• Depreciable amount = 2,000,000 − 200,000 = ₦1,800,000; annual depreciation = 25% × 1,800,000 = ₦450,000.\n• January 2023 to December 2025 = 3 years; accumulated depreciation = 3 × 450,000 = ₦1,350,000.\n• Carrying amount = 2,000,000 − 1,350,000 = ₦650,000.\n• Net proceeds = 900,000 − 40,000 = ₦860,000.\n• Gain = 860,000 − 650,000 = ₦210,000 profit on disposal, recognised in profit or loss (not revenue)."}}},{"kind":"theory_question","itemId":"769e92ce-e4ee-57ca-9478-2081738e5730","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Ilaro Farms Ltd buys a tractor for ₦54,000,000 and receives a government grant of ₦12,000,000 towards it. The tractor is depreciated straight line over 3 years with nil residual value. Show the annual depreciation, the annual grant income and the net charge to profit or loss under each IAS 20 method."},"answer":{"kind":"model_answer","itemId":"4484aa32-65c4-5619-aff4-b32a8c0b610b","sourceKey":"guide-answer:7","payload":{"body":"• Deduct from cost: depreciation = (54,000,000 − 12,000,000) ÷ 3 = ₦14,000,000; no grant income line; net charge ₦14,000,000.\n• Deferred income: depreciation = 54,000,000 ÷ 3 = ₦18,000,000; grant income = 12,000,000 ÷ 3 = ₦4,000,000; net charge = 18,000,000 − 4,000,000 = ₦14,000,000.\n• Same net effect; only the presentation differs."}}},{"kind":"theory_question","itemId":"ff8c8a26-32df-5eb1-87b2-6bb13386435c","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"Owode Steel Ltd (year ended 31 December) had general borrowings outstanding all year: ₦400m at 10% and ₦100m at 15%. It built a rolling mill (a qualifying asset) throughout the year, spending ₦120m on 1 January and ₦80m on 1 July. Compute the capitalisation rate and the borrowing costs to capitalise."},"answer":{"kind":"model_answer","itemId":"a7c51d26-31a0-561c-b3a6-fd0a2a53a0fb","sourceKey":"guide-answer:8","payload":{"body":"• Interest = ₦400m × 10% + ₦100m × 15% = ₦40m + ₦15m = ₦55m.\n• Capitalisation rate = ₦55m ÷ ₦500m = 11%.\n• ₦120m × 11% × 12/12 = ₦13.2m; ₦80m × 11% × 6/12 = ₦4.4m.\n• Capitalised = ₦13.2m + ₦4.4m = ₦17.6m (below the ₦55m incurred). The other ₦37.4m is a finance cost. Dr PPE ₦17.6m, Dr Finance costs ₦37.4m / Cr Interest payable (or Bank) ₦55m."}}}]}$study_guide$);
